cat > src/main.rs <<'EOF'
use chrono::{NaiveDate, NaiveDateTime};
use chrono::format::ParseErrorKind as K;
fn kind(e: chrono::ParseError) -> &'static str { match e.kind() { K::TooShort => "TooShort", K::TooLong => "TooLong", K::OutOfRange => "OutOfRange", K::Invalid => "Invalid", K::NotEnough => "NotEnough", K::Impossible => "Impossible", K::BadFormat => "BadFormat", _ => "?" } }
fn main() {
    let obs: Vec<(&str, &str)> = vec![
        ("abc","TooShort"),("hello world","TooShort"),("1","TooShort"),("x","TooShort"),("2024","TooShort"),("2024-","TooShort"),("2024-06-","TooShort"),("2024-06","TooShort"),("2024-06-0","TooShort"),("01-06-2024","TooShort"),("x2024-06-01","TooShort"),(" 2024-06-01","TooShort"),("2024-6-1","TooShort"),("2024/06/01","TooShort"),("06/01/2024","TooShort"),("2024.06.01","TooShort"),("June 1, 2024","TooShort"),("Sat, 01 Jun 2024 12:00:00 GMT","TooShort"),
        ("12:00:00","OutOfRange"),("20240601 12:00:00","OutOfRange"),("2024-06-32","OutOfRange"),("2024-02-30","OutOfRange"),("9999-99-99","OutOfRange"),("2024-13-01 25","OutOfRange"),
        ("2024-06-01 12:60","TooLong"),("2024-06-01 25:00:00","TooLong"),("2024-06-01 24:00:00","TooLong"),("2024-06-01 99:99","TooLong"),
    ];
    let re_d = regex::Regex::new(r"\d{4}-\d{2}-\d{2}").unwrap();
    let re_num = regex::Regex::new(r"\d+").unwrap();
    let transforms: Vec<(&str, Box<dyn Fn(&str) -> String>)> = vec![
        ("id", Box::new(|s: &str| s.to_string())),
        ("first10", Box::new(|s: &str| s.chars().take(10).collect())),
        ("first19", Box::new(|s: &str| s.chars().take(19).collect())),
        ("split_space0", Box::new(|s: &str| s.split(' ').next().unwrap_or("").to_string())),
        ("split_T0", Box::new(|s: &str| s.split('T').next().unwrap_or("").to_string())),
        ("re_d_find", Box::new(move |s: &str| re_d.find(s).map(|m| m.as_str().to_string()).unwrap_or_default())),
        ("nums_dash", Box::new(move |s: &str| re_num.find_iter(s).map(|m| m.as_str()).collect::<Vec<_>>().join("-"))),
        ("trim", Box::new(|s: &str| s.trim().to_string())),
        ("plus_time", Box::new(|s: &str| format!("{s} 00:00:00"))),
        ("plus_T_time", Box::new(|s: &str| format!("{s}T00:00:00"))),
    ];
    let fmts = ["%Y-%m-%d", "%Y-%m-%d %H:%M:%S", "%Y-%m-%d %H:%M", "%Y-%m-%dT%H:%M:%S", "%Y-%m-%d %H:%M:%S%.f", "%Y-%m-%dT%H:%M:%S%.f", "%Y-%m-%d %H:%M:%S %z", "%F %T", "%Y-%m-%d %H", "%Y%m%d", "%Y-%m-%dT%H:%M:%S%z", "%Y-%m-%d%z", "%+"];
    for (tn, t) in &transforms {
        for f in fmts {
            for api in ["ND", "NDT"] {
                let mut ok = 0; let mut total = 0; let mut mism = vec![];
                for (s, expect) in &obs {
                    total += 1;
                    let ts = t(s);
                    let got = match api { "ND" => NaiveDate::parse_from_str(&ts, f).map(|_| "Ok").unwrap_or_else(kind), _ => NaiveDateTime::parse_from_str(&ts, f).map(|_| "Ok").unwrap_or_else(kind) };
                    if got == *expect { ok += 1 } else { mism.push(format!("{s:?}:{got}")) }
                }
                if ok >= total - 4 { println!("{tn} {f} {api}: {ok}/{total} mismatches: {:?}", mism); }
            }
        }
    }
}
EOF
cargo run --offline -q 2>&1 | head -40"}

