{"command":"mkdir -p /workspace/src/markdown && cat > /workspace/src/markdown/node.rs <<'EOF'
//! AST node definitions for the markdown parser.

#[derive(Debug, Clone, PartialEq)]
pub enum ListType {
    Bullet,
    Ordered,
}

#[derive(Debug, Clone, PartialEq)]
pub enum DelimType {
    Period,
    Paren,
}

#[derive(Debug, Clone)]
pub struct ListData {
    pub list_type: ListType,
    pub marker_offset: usize,
    pub padding: usize,
    pub start: usize,
    pub delimiter: DelimType,
    pub bullet_char: u8,
    pub tight: bool,
}

impl Default for ListData {
    fn default() -> Self {
        ListData {
            list_type: ListType::Bullet,
            marker_offset: 0,
            padding: 0,
            start: 1,
            delimiter: DelimType::Period,
            bullet_char: 0,
            tight: false,
        }
    }
}

#[derive(Debug, Clone, Copy, PartialEq)]
pub enum TableAlignment {
    None,
    Left,
    Center,
    Right,
}

#[derive(Debug, Clone, Copy, PartialEq)]
pub enum AlertType {
    Note,
    Tip,
    Important,
    Warning,
    Caution,
}

impl AlertType {
    pub fn css_class(&self) -> &'static str {
        match self {
            AlertType::Note => "note",
            AlertType::Tip => "tip",
            AlertType::Important => "important",
            AlertType::Warning => "warning",
            AlertType::Caution => "caution",
        }
    }
    pub fn default_title(&self) -> &'static str {
        match self {
            AlertType::Note => "Note",
            AlertType::Tip => "Tip",
            AlertType::Important => "Important",
            AlertType::Warning => "Warning",
            AlertType::Caution => "Caution",
        }
    }
}

#[derive(Debug, Clone)]
pub enum NodeValue {
    Document,
    BlockQuote,
    MultilineBlockQuote { fence_length: usize, fence_offset: usize },
    List(ListData),
    Item(ListData),
    TaskItem { checked: bool, symbol: u8 },
    DescriptionList,
    DescriptionItem { tight: bool },
    DescriptionTerm,
    DescriptionDetails,
    CodeBlock {
        fenced: bool,
        fence_char: u8,
        fence_length: usize,
        fence_offset: usize,
        info: String,
        literal: String,
    },
    HtmlBlock { block_type: u8, literal: String },
    Paragraph,
    Heading { level: u8, setext: bool },
    ThematicBreak,
    FootnoteDefinition { name: String, total_references: usize },
    Table { alignments: Vec<TableAlignment>, num_columns: usize },
    TableRow { header: bool },
    TableCell,
    Alert { alert_type: AlertType, title: Option<String>, multiline: bool, fence_length: usize, fence_offset: usize },
    // inlines
    Text(String),
    SoftBreak,
    LineBreak,
    Code(String),
    HtmlInline(String),
    Emph,
    Strong,
    Strikethrough,
    Underline,
    Spoiler,
    Link { url: String, title: String },
    Image { url: String, title: String },
    FootnoteReference { name: String, ref_num: usize, ix: usize },
    WikiLink { url: String },
    ShortCode(String),
}

#[derive(Debug, Clone)]
pub struct Node {
    pub value: NodeValue,
    pub parent: Option<usize>,
    pub first_child: Option<usize>,
    pub last_child: Option<usize>,
    pub prev: Option<usize>,
    pub next: Option<usize>,
    pub open: bool,
    pub last_line_blank: bool,
    pub content: String,
    pub start_line: usize,
    pub end_line: usize,
    pub internal_offset: usize,
    pub table_visited: bool,
}

impl Node {
    pub fn new(value: NodeValue, start_line: usize) -> Node {
        Node {
            value,
            parent: None,
            first_child: None,
            last_child: None,
            prev: None,
            next: None,
            open: true,
            last_line_blank: false,
            content: String::new(),
            start_line,
            end_line: start_line,
            internal_offset: 0,
            table_visited: false,
        }
    }
}

pub struct Arena {
    pub nodes: Vec<Node>,
}

impl Arena {
    pub fn new() -> Arena {
        Arena { nodes: Vec::new() }
    }
    pub fn alloc(&mut self, value: NodeValue, line: usize) -> usize {
        self.nodes.push(Node::new(value, line));
        self.nodes.len() - 1
    }
    pub fn get(&self, id: usize) -> &Node {
        &self.nodes[id]
    }
    pub fn get_mut(&mut self, id: usize) -> &mut Node {
        &mut self.nodes[id]
    }
    pub fn append(&mut self, parent: usize, child: usize) {
        self.detach(child);
