                }
            }
        }
    }
    pub fn detach(&mut self, node: usize) {
        let (parent, prev, next) = {
            let n = &self.nodes[node];
            (n.parent, n.prev, n.next)
        };
        if let Some(p) = prev {
            self.nodes[p].next = next;
        } else if let Some(par) = parent {
            self.nodes[par].first_child = next;
        }
        if let Some(n) = next {
            self.nodes[n].prev = prev;
        } else if let Some(par) = parent {
            self.nodes[par].last_child = prev;
        }
        let n = &mut self.nodes[node];
        n.parent = None;
        n.prev = None;
        n.next = None;
    }
    pub fn children(&self, node: usize) -> Vec<usize> {
        let mut out = Vec::new();
        let mut c = self.nodes[node].first_child;
        while let Some(id) = c {
            out.push(id);
            c = self.nodes[id].next;
        }
        out
    }
    pub fn descendants(&self, node: usize) -> Vec<usize> {
        let mut out = Vec::new();
        let mut stack = vec![node];
        while let Some(n) = stack.pop() {
            out.push(n);
            let ch = self.children(n);
            for c in ch.into_iter().rev() {
                stack.push(c);
            }
        }
        out
    }
    pub fn last_child_is_open(&self, node: usize) -> bool {
        match self.nodes[node].last_child {
            Some(c) => self.nodes[c].open,
            None => false,
        }
    }
}
