//! Hand written scanners replacing the re2c generated ones.

pub fn is_space_or_tab(c: u8) -> bool {
    c == b' ' || c == b'\t'
}

pub fn is_line_end(c: u8) -> bool {
    c == b'\n' || c == b'\r'
}

pub fn is_blank(line: &[u8]) -> bool {
    line.iter().all(|&c| c == b' ' || c == b'\t' || c == b'\n' || c == b'\r')
}

/// Match `#{1,6}` followed by space/tab/EOL. Returns (consumed, level).
pub fn atx_heading_start(line: &[u8]) -> Option<(usize, u8)> {
    let mut i = 0;
    while i < line.len() && line[i] == b'#' {
        i += 1;
    }
    if i == 0 || i > 6 {
        return None;
    }
    if i >= line.len() || is_space_or_tab(line[i]) || is_line_end(line[i]) {
        let mut j = i;
        while j < line.len() && is_space_or_tab(line[j]) {
            j += 1;
        }
        Some((j, i as u8))
    } else {
        None
    }
}

/// Open code fence: returns fence length (chars) if the line starts with a valid opening fence.
pub fn open_code_fence(line: &[u8]) -> Option<usize> {
    if line.is_empty() {
        return None;
    }
    let c = line[0];
    if c != b'`' && c != b'~' {
        return None;
    }
    let mut i = 0;
    while i < line.len() && line[i] == c {
        i += 1;
    }
    if i < 3 {
        return None;
    }
    // info string must not contain backticks for backtick fences
    if c == b'`' {
        for &b in &line[i..] {
            if b == b'`' {
                return None;
            }
            if is_line_end(b) {
                break;
            }
        }
    }
    Some(i)
}

/// Close code fence: returns fence length if the line is a closing fence (only spaces after).
pub fn close_code_fence(line: &[u8]) -> Option<usize> {
    if line.is_empty() {
        return None;
    }
    let c = line[0];
    if c != b'`' && c != b'~' {
        return None;
    }
    let mut i = 0;
    while i < line.len() && line[i] == c {
        i += 1;
    }
    if i < 3 {
        return None;
    }
    let mut j = i;
    while j < line.len() && is_space_or_tab(line[j]) {
        j += 1;
    }
    if j >= line.len() || is_line_end(line[j]) {
        Some(i)
    } else {
        None
    }
}

const BLOCK_TAGS: &[&str] = &[
    "address", "article", "aside", "base", "basefont", "blockquote", "body", "caption", "center", "col",
    "colgroup", "dd", "details", "dialog", "dir", "div", "dl", "dt", "fieldset", "figcaption", "figure",
    "footer", "form", "frame", "frameset", "h1", "h2", "h3", "h4", "h5", "h6", "head", "header", "hr",
    "html", "iframe", "legend", "li", "link", "main", "menu", "menuitem", "nav", "noframes", "ol",
    "optgroup", "option", "p", "param", "search", "section", "summary", "table", "tbody", "td", "tfoot", "th",
    "thead", "title", "tr", "track", "ul",
];

fn lower(b: u8) -> u8 {
    b.to_ascii_lowercase()
}

fn starts_with_ci(line: &[u8], s: &str) -> bool {
    let sb = s.as_bytes();
    if line.len() < sb.len() {
        return false;
    }
    for i in 0..sb.len() {
        if lower(line[i]) != sb[i] {
            return false;
        }
    }
    true
}

/// HTML block start conditions 1-6. Returns the block type.
pub fn html_block_start(line: &[u8]) -> Option<u8> {
    if line.is_empty() || line[0] != b'<' {
        return None;
    }
    let rest = &line[1..];
    // type 1: <script, <pre, <style, <textarea followed by space, tab, > or EOL
    for tag in ["script", "pre", "style", "textarea"] {
        if starts_with_ci(rest, tag) {
            let after = &rest[tag.len()..];
            if after.is_empty() || is_space_or_tab(after[0]) || after[0] == b'>' || is_line_end(after[0]) {
                return Some(1);
            }
        }
    }
    // type 2: <!--
    if rest.starts_with(b"!--") {
        return Some(2);
    }
    // type 3: <?
    if rest.starts_with(b"?") {
        return Some(3);
    }
    // type 4: <! followed by an ASCII letter
    if rest.len() >= 2 && rest[0] == b'!' && rest[1].is_ascii_alphabetic() {
        return Some(4);
    }
    // type 5: <![CDATA[
    if rest.starts_with(b"![CDATA[") {
        return Some(5);
    }
    // type 6: < or </ followed by a block tag name then space, tab, EOL, > or />
    let mut j = 0;
    if j < rest.len() && rest[j] == b'/' {
        j += 1;
    }
    let name_start = j;
    while j < rest.len() && rest[j].is_ascii_alphanumeric() {
        j += 1;
    }
    if j > name_start {
        let name: String = rest[name_start..j].iter().map(|&b| lower(b) as char).collect();
        if BLOCK_TAGS.contains(&name.as_str()) {
            let after = &rest[j..];
            if after.is_empty()
                || is_space_or_tab(after[0])
                || is_line_end(after[0])
                || after[0] == b'>'
                || after.starts_with(b"/>")
            {
                return Some(6);
            }
        }
    }
    None
}

/// HTML block start condition 7: a complete open or closing tag alone on the line.
pub fn html_block_start_7(line: &[u8]) -> Option<u8> {
    if line.is_empty() || line[0] != b'<' {
        return None;
    }
    let end = if line[1..].starts_with(b"/") {
        scan_closing_tag(&line[1..]).map(|n| n + 1)
    } else {
        scan_open_tag(&line[1..]).map(|n| n + 1)
    }?;
    // rest of line must be whitespace
    let mut j = end;
    while j < line.len() && is_space_or_tab(line[j]) {
        j += 1;
    }
    if j >= line.len() || is_line_end(line[j]) {
        Some(7)
    } else {
        None
    }
}

/// Scans an open tag (after the '<'). Returns consumed length including '>'.
pub fn scan_open_tag(s: &[u8]) -> Option<usize> {
    let mut i = 0;
    // tag name
    if i >= s.len() || !s[i].is_ascii_alphabetic() {
        return None;
    }
    i += 1;
    while i < s.len() && (s[i].is_ascii_alphanumeric() || s[i] == b'-') {
        i += 1;
    }
    // attributes
    loop {
        // whitespace
        let ws_start = i;
        while i < s.len() && (is_space_or_tab(s[i]) || is_line_end(s[i])) {
            i += 1;
        }
        if i >= s.len() {
            return None;
        }
        if s[i] == b'/' {
            if i + 1 < s.len() && s[i + 1] == b'>' {
                return Some(i + 2);
            }
            return None;
        }
        if s[i] == b'>' {
            return Some(i + 1);
        }
        if i == ws_start {
            return None; // attribute must be preceded by whitespace
        }
        // attribute name
        if !(s[i].is_ascii_alphabetic() || s[i] == b'_' || s[i] == b':') {
            return None;
        }
        i += 1;
        while i < s.len()
            && (s[i].is_ascii_alphanumeric() || s[i] == b'_' || s[i] == b'.' || s[i] == b':' || s[i] == b'-')
        {
            i += 1;
        }
        // optional value spec
        let mut j = i;
        while j < s.len() && (is_space_or_tab(s[j]) || is_line_end(s[j])) {
            j += 1;
        }
        if j < s.len() && s[j] == b'=' {
            j += 1;
            while j < s.len() && (is_space_or_tab(s[j]) || is_line_end(s[j])) {
                j += 1;
            }
            if j >= s.len() {
                return None;
            }
            if s[j] == b'\'' || s[j] == b'"' {
                let q = s[j];
                j += 1;
                while j < s.len() && s[j] != q {
                    j += 1;
                }
                if j >= s.len() {
                    return None;
                }
                j += 1;
            } else {
                let vs = j;
                while j < s.len()
                    && !(is_space_or_tab(s[j])
                        || is_line_end(s[j])
                        || s[j] == b'"'
                        || s[j] == b'\''
                        || s[j] == b'='
                        || s[j] == b'<'
                        || s[j] == b'>'
                        || s[j] == b'`')
                {
                    j += 1;
                }
                if j == vs {
                    return None;
                }
            }
            i = j;
        }
    }
}

/// Scans a closing tag (after the '<'), i.e. `/name >`.
pub fn scan_closing_tag(s: &[u8]) -> Option<usize> {
    if s.is_empty() || s[0] != b'/' {
        return None;
    }
    let mut i = 1;
    if i >= s.len() || !s[i].is_ascii_alphabetic() {
        return None;
    }
    i += 1;
    while i < s.len() && (s[i].is_ascii_alphanumeric() || s[i] == b'-') {
        i += 1;
    }
    while i < s.len() && (is_space_or_tab(s[i]) || is_line_end(s[i])) {
        i += 1;
    }
    if i < s.len() && s[i] == b'>' {
        Some(i + 1)
    } else {
        None
    }
}

/// Returns true if the line contains the end condition of the given HTML block type.
pub fn html_block_end(block_type: u8, line: &[u8]) -> bool {
    let s = line;
    match block_type {
        1 => {
            let l: Vec<u8> = s.iter().map(|&b| lower(b)).collect();
            contains(&l, b"</script>") || contains(&l, b"</pre>") || contains(&l, b"</style>") || contains(&l, b"</textarea>")
        }
        2 => contains(s, b"-->"),
        3 => contains(s, b"?>"),
        4 => contains(s, b">"),
        5 => contains(s, b"]]>"),
        _ => false,
    }
}

fn contains(hay: &[u8], needle: &[u8]) -> bool {
    if needle.len() > hay.len() {
        return false;
    }
    hay.windows(needle.len()).any(|w| w == needle)
}

/// Setext heading underline: returns level (1 for =, 2 for -).
pub fn setext_heading_line(line: &[u8]) -> Option<u8> {
    if line.is_empty() {
        return None;
    }
    let c = line[0];
    if c != b'=' && c != b'-' {
        return None;
    }
    let mut i = 0;
    while i < line.len() && line[i] == c {
        i += 1;
    }
    while i < line.len() && is_space_or_tab(line[i]) {
        i += 1;
    }
    if i >= line.len() || is_line_end(line[i]) {
        Some(if c == b'=' { 1 } else { 2 })
    } else {
        None
    }
}

/// Thematic break: 3+ of the same char (*, -, _) possibly separated by spaces/tabs.
pub fn thematic_break(line: &[u8]) -> Option<usize> {
    if line.is_empty() {
        return None;
    }
    let c = line[0];
    if c != b'*' && c != b'-' && c != b'_' {
        return None;
    }
    let mut count = 0;
    let mut i = 0;
    while i < line.len() {
        let b = line[i];
        if b == c {
            count += 1;
        } else if is_space_or_tab(b) {
