/// Decodes a character reference starting at `s` (which begins with `&`).
/// Returns (consumed bytes, decoded string).
pub fn unescape_entity(s: &[u8]) -> Option<(usize, String)> {
    if s.len() < 3 || s[0] != b'&' {
        return None;
    }
    if s[1] == b'#' {
        let mut i = 2;
        let hex = i < s.len() && (s[i] == b'x' || s[i] == b'X');
        if hex {
            i += 1;
        }
        let start = i;
        let mut cp: u32 = 0;
        while i < s.len() {
            let c = s[i];
            let d = if hex {
                (c as char).to_digit(16)
            } else {
                (c as char).to_digit(10)
            };
            match d {
                Some(d) => {
                    if i - start >= if hex { 6 } else { 7 } {
                        return None;
                    }
                    cp = cp * if hex { 16 } else { 10 } + d;
                }
                None => break,
            }
            i += 1;
        }
        if i == start || i >= s.len() || s[i] != b';' {
            return None;
        }
        let ch = if cp == 0 {
            '\u{FFFD}'
        } else {
            char::from_u32(cp).unwrap_or('\u{FFFD}')
        };
        return Some((i + 1, ch.to_string()));
    }
    let mut i = 1;
    while i < s.len() && s[i].is_ascii_alphanumeric() {
        i += 1;
        if i > 33 {
            return None;
        }
    }
    if i == 1 || i >= s.len() || s[i] != b';' {
        return None;
    }
    let name = std::str::from_utf8(&s[1..i]).ok()?;
    entities::lookup(name).map(|v| (i + 1, v.to_string()))
}

