    let mut out = String::with_capacity(s.len());
    let mut i = 0;
    let mut last = 0;
    while i < b.len() {
        if b[i] == b'&' {
            if let Some((n, dec)) = unescape_entity(&b[i..]) {
                out.push_str(&s[last..i]);
                out.push_str(&dec);
                i += n;
                last = i;
