pub fn normalize_label(s: &str) -> String {
    let mut out = String::new();
    let mut last_was_space = false;
    for c in s.trim().chars() {
        if c.is_whitespace() {
            if !last_was_space {
                out.push(' ');
            }
            last_was_space = true;
        } else {
            last_was_space = false;
            for lc in c.to_uppercase() {
                for l in lc.to_lowercase() {
                    out.push(l);
                }
            }
        }
    }
    out
}

pub fn rtrim(s: &mut String) {
