    s.truncate(trimmed);
}

pub fn ltrim_bytes(s: &[u8]) -> &[u8] {
    let mut i = 0;
    while i < s.len() && is_whitespace_byte(s[i]) {
        i += 1;
    }
    &s[i..]
}

/// Remove trailing blank lines from a string.
pub fn remove_trailing_blank_lines(s: &mut String) {
    let b = s.as_bytes();
    let mut i = b.len();
    while i > 0 {
        let c = b[i - 1];
        if c != b' ' && c != b'\t' && c != b'\n' && c != b'\r' {
            break;
        }
        i -= 1;
    }
    if i == 0 {
        s.clear();
        return;
    }
    // find the end of the line containing position i-1
    let mut j = i;
    while j < b.len() {
        if b[j] == b'\n' || b[j] == b'\r' {
            break;
        }
        j += 1;
    }
    s.truncate(j);
}

pub fn trim_slice(s: &[u8]) -> &[u8] {
    let mut start = 0;
    let mut end = s.len();
    while start < end && is_whitespace_byte(s[start]) {
        start += 1;
    }
    while end > start && is_whitespace_byte(s[end - 1]) {
        end -= 1;
    }
    &s[start..end]
}
