                out.push_str(&s[last..i]);
                out.push_str(&dec);
                i += n;
                last = i;
                continue;
            }
        }
        i += 1;
    }
    out.push_str(&s[last..]);
    out
}

pub fn clean_url(s: &str) -> String {
    let t = s.trim_matches(|c: char| c.is_whitespace());
    if t.is_empty() {
        return String::new();
    }
    if t.starts_with('<') && t.ends_with('>') && t.len() >= 2 {
        unescape(&t[1..t.len() - 1])
    } else {
        unescape(t)
    }
}

pub fn clean_title(s: &str) -> String {
    if s.is_empty() {
        return String::new();
    }
    let b = s.as_bytes();
    let first = b[0];
    let last = b[b.len() - 1];
    if (first == b'\'' && last == b'\'') || (first == b'(' && last == b')') || (first == b'"' && last == b'"') {
        if s.len() >= 2 {
            return unescape(&s[1..s.len() - 1]);
        }
    }
    unescape(s)
}

pub fn normalize_label(s: &str) -> String {
    let mut out = String::new();
    let mut last_was_space = false;
    for c in s.trim().chars() {
        if c.is_whitespace() {
            if !last_was_space {
                out.push(' ');
            }
            last_was_space = true;
        } else {
            last_was_space = false;
            for lc in c.to_uppercase() {
                for l in lc.to_lowercase() {
                    out.push(l);
                }
            }
        }
    }
    out
}

pub fn rtrim(s: &mut String) {
    let trimmed = s.trim_end_matches(|c: char| c == ' ' || c == '\t' || c == '\n' || c == '\r' || c == '\u{b}' || c == '\u{c}').len();
    s.truncate(trimmed);
}

pub fn ltrim_bytes(s: &[u8]) -> &[u8] {
    let mut i = 0;
    while i < s.len() && is_whitespace_byte(s[i]) {
        i += 1;
    }
    &s[i..]
}

/// Remove trailing blank lines from a string.
pub fn remove_trailing_blank_lines(s: &mut String) {
    let b = s.as_bytes();
    let mut i = b.len();
    while i > 0 {
        let c = b[i - 1];
        if c != b' ' && c != b'\t' && c != b'\n' && c != b'\r' {
            break;
        }
        i -= 1;
    }
    if i == 0 {
        s.clear();
        return;
    }
    // find the end of the line containing position i-1
    let mut j = i;
    while j < b.len() {
        if b[j] == b'\n' || b[j] == b'\r' {
            break;
        }
        j += 1;
    }
    s.truncate(j);
}

pub fn trim_slice(s: &[u8]) -> &[u8] {
    let mut start = 0;
    let mut end = s.len();
    while start < end && is_whitespace_byte(s[start]) {
        start += 1;
    }
    while end > start && is_whitespace_byte(s[end - 1]) {
        end -= 1;
    }
    &s[start..end]
}
