//! Block level parsing, modelled after cmark/comrak.

use super::node::*;
use super::scanners;
use super::strings;
use std::collections::HashMap;

pub const TAB_STOP: usize = 4;
pub const CODE_INDENT: usize = 4;
const MAX_LIST_DEPTH: usize = 100;

#[derive(Debug, Clone)]
pub struct Reference {
    pub url: String,
    pub title: String,
}

pub struct Parser {
    pub arena: Arena,
    pub root: usize,
    pub current: usize,
    pub line_number: usize,
    pub offset: usize,
    pub column: usize,
    pub thematic_break_kill_pos: usize,
    pub first_nonspace: usize,
    pub first_nonspace_column: usize,
    pub indent: usize,
    pub blank: bool,
    pub partially_consumed_tab: bool,
    pub last_line_length: usize,
    pub refmap: HashMap<String, Reference>,
    pub footnote_defs: Vec<String>,
}

impl Parser {
    pub fn new() -> Parser {
        let mut arena = Arena::new();
        let root = arena.alloc(NodeValue::Document, 0);
        Parser {
            arena,
            root,
            current: root,
            line_number: 0,
            offset: 0,
            column: 0,
            thematic_break_kill_pos: 0,
            first_nonspace: 0,
            first_nonspace_column: 0,
            indent: 0,
            blank: false,
            partially_consumed_tab: false,
            last_line_length: 0,
            refmap: HashMap::new(),
            footnote_defs: Vec::new(),
        }
    }

    pub fn feed(&mut self, text: &str) {
        let bytes = text.as_bytes();
        let mut i = 0;
        let mut linebuf: Vec<u8> = Vec::new();
        while i < bytes.len() {
            let start = i;
            while i < bytes.len() && bytes[i] != b'\n' && bytes[i] != b'\r' {
                i += 1;
            }
            linebuf.clear();
            linebuf.extend_from_slice(&bytes[start..i]);
            if i < bytes.len() {
                if bytes[i] == b'\r' && i + 1 < bytes.len() && bytes[i + 1] == b'\n' {
                    i += 2;
                } else {
                    i += 1;
                }
            }
            linebuf.push(b'\n');
            self.process_line(&linebuf.clone());
        }
    }

    fn process_line(&mut self, line: &[u8]) {
        // replace NUL
        let mut line_vec: Vec<u8> = line.to_vec();
        for b in line_vec.iter_mut() {
            if *b == 0 {
                // represent U+FFFD; we work in bytes so push the UTF-8 form later
                *b = b'?';
            }
        }
        let line = &line_vec[..];
        self.offset = 0;
        self.column = 0;
        self.blank = false;
        self.partially_consumed_tab = false;
        self.line_number += 1;

        let (container, should_continue, all_matched) = self.check_open_blocks(line);
        if !should_continue {
            self.last_line_length = line.len();
            return;
        }
        let last_matched_container = container;
        let mut container = container;
        let maybe_lazy = matches!(self.arena.get(self.current).value, NodeValue::Paragraph);
        self.open_new_blocks(&mut container, line, all_matched, maybe_lazy);
        self.add_text_to_container(container, last_matched_container, line);
        self.last_line_length = line.len();
    }

    fn check_open_blocks(&mut self, line: &[u8]) -> (usize, bool, bool) {
        let mut container = self.root;
        let mut all_matched = true;
        while self.arena.last_child_is_open(container) {
            container = self.arena.get(container).last_child.unwrap();
            self.find_first_nonspace(line);
            let value = self.arena.get(container).value.clone();
            match value {
                NodeValue::BlockQuote => {
                    if !self.parse_block_quote_prefix(line) {
                        all_matched = false;
                        break;
                    }
                }
                NodeValue::Alert { multiline, fence_length, fence_offset, .. } => {
                    if multiline {
                        if self.parse_multiline_fence_close(line, fence_length, fence_offset, container) {
                            return (container, false, false);
                        }
                    } else if !self.parse_block_quote_prefix(line) {
                        all_matched = false;
                        break;
                    }
                }
                NodeValue::MultilineBlockQuote { fence_length, fence_offset } => {
                    if self.parse_multiline_fence_close(line, fence_length, fence_offset, container) {
                        return (container, false, false);
                    }
                }
                NodeValue::Item(ref nl) | NodeValue::TaskItem { .. } if false => {
                    let _ = nl;
                }
                NodeValue::Item(ref nl) => {
                    let nl = nl.clone();
                    if !self.parse_node_item_prefix(line, container, &nl) {
                        all_matched = false;
                        break;
                    }
                }
                NodeValue::DescriptionItem { .. } => {
                    // description items are matched if details/term prefix matches; handled via details
                    if self.blank {
                        // blank lines are fine
                    }
                }
                NodeValue::DescriptionDetails => {
                    if !self.parse_description_details_prefix(line, container) {
                        all_matched = false;
                        break;
                    }
                }
                NodeValue::CodeBlock { .. } => {
                    match self.parse_code_block_prefix(line, container) {
                        Some(true) => {}
                        Some(false) => {
                            all_matched = false;
                            break;
                        }
                        None => {
                            // closing fence: stop processing this line
                            return (container, false, false);
                        }
                    }
                }
                NodeValue::Heading { .. } => {
                    all_matched = false;
                    break;
                }
                NodeValue::HtmlBlock { block_type, .. } => {
                    if !self.parse_html_block_prefix(block_type) {
                        all_matched = false;
                        break;
                    }
                }
                NodeValue::Paragraph => {
                    if self.blank {
                        all_matched = false;
                        break;
                    }
                }
                NodeValue::Table { .. } => {
                    if self.blank {
                        all_matched = false;
                        break;
                    }
                }
                NodeValue::FootnoteDefinition { .. } => {
                    if !self.parse_footnote_definition_block_prefix(line) {
                        all_matched = false;
                        break;
                    }
                }
                _ => {}
            }
        }
        if !all_matched {
            // back up to the parent
            container = self.arena.get(container).parent.unwrap_or(self.root);
        }
        (container, true, all_matched)
    }

    fn parse_multiline_fence_close(&mut self, line: &[u8], fence_length: usize, _fence_offset: usize, container: usize) -> bool {
        if self.indent <= 3 && self.first_nonspace < line.len() && line[self.first_nonspace] == b'>' {
            if let Some(matched) = scanners::close_multiline_block_quote_fence(&line[self.first_nonspace..]) {
                if matched >= fence_length {
                    let n = line.len() - 1 - self.offset;
                    self.advance_offset(line, n, false);
                    self.current = self.finalize(container);
                    return true;
                }
            }
        }
        false
    }

    fn parse_block_quote_prefix(&mut self, line: &[u8]) -> bool {
        let indent = self.indent;
        if indent <= 3 && self.first_nonspace < line.len() && line[self.first_nonspace] == b'>' {
            let n = self.first_nonspace + 1 - self.offset;
            self.advance_offset(line, n, false);
            if self.offset < line.len() && strings::is_space_or_tab(line[self.offset]) {
                self.advance_offset(line, 1, true);
            }
            return true;
        }
        false
    }

    fn parse_node_item_prefix(&mut self, line: &[u8], container: usize, nl: &ListData) -> bool {
        if self.indent >= nl.marker_offset + nl.padding {
            self.advance_offset(line, nl.marker_offset + nl.padding, true);
            true
        } else if self.blank && self.arena.get(container).first_child.is_some() {
            let n = self.first_nonspace - self.offset;
            self.advance_offset(line, n, false);
            true
        } else {
            false
        }
    }

    fn parse_description_details_prefix(&mut self, line: &[u8], container: usize) -> bool {
        // details continue with indentation of 2 or blank lines
        if self.indent >= 2 {
            self.advance_offset(line, 2, true);
            true
        } else if self.blank && self.arena.get(container).first_child.is_some() {
            let n = self.first_nonspace - self.offset;
            self.advance_offset(line, n, false);
            true
        } else {
            false
        }
    }

    fn parse_footnote_definition_block_prefix(&mut self, line: &[u8]) -> bool {
        if self.indent >= 4 {
            self.advance_offset(line, 4, true);
            true
        } else {
            line == b"\n" || line == b"\r\n"
        }
    }

    /// Returns Some(true) if matched, Some(false) if not, None if closing fence consumed the line.
    fn parse_code_block_prefix(&mut self, line: &[u8], container: usize) -> Option<bool> {
        let (fenced, fence_char, fence_length, fence_offset) = match &self.arena.get(container).value {
            NodeValue::CodeBlock { fenced, fence_char, fence_length, fence_offset, .. } => (*fenced, *fence_char, *fence_length, *fence_offset),
            _ => unreachable!(),
        };
        if !fenced {
            if self.indent >= CODE_INDENT {
                self.advance_offset(line, CODE_INDENT, true);
                return Some(true);
            } else if self.blank {
                let n = self.first_nonspace - self.offset;
                self.advance_offset(line, n, false);
                return Some(true);
            }
            return Some(false);
        }
        let matched = if self.indent <= 3 && self.first_nonspace < line.len() && line[self.first_nonspace] == fence_char {
            scanners::close_code_fence(&line[self.first_nonspace..]).unwrap_or(0)
        } else {
            0
        };
        if matched >= fence_length && matched > 0 {
            let n = line.len() - 1 - self.offset;
            self.advance_offset(line, n, false);
            self.current = self.finalize(container);
            return None;
        }
        // skip optional spaces of fence offset
        let mut i = fence_offset;
        while i > 0 && self.offset < line.len() && strings::is_space_or_tab(line[self.offset]) {
            self.advance_offset(line, 1, true);
            i -= 1;
        }
        Some(true)
    }

    fn parse_html_block_prefix(&mut self, block_type: u8) -> bool {
        match block_type {
            1..=5 => true,
            6 | 7 => !self.blank,
            _ => false,
        }
    }

    fn open_new_blocks(&mut self, container: &mut usize, line: &[u8], all_matched: bool, maybe_lazy: bool) {
        let mut depth = 0;
        loop {
            match self.arena.get(*container).value {
                NodeValue::CodeBlock { .. } | NodeValue::HtmlBlock { .. } => break,
                _ => {}
            }
            self.find_first_nonspace(line);
            let indented = self.indent >= CODE_INDENT;
            let fns = self.first_nonspace;
            let rest = &line[fns..];

            if !indented && scanners::alert_start(rest).is_some() {
                let kind = scanners::alert_start(rest).unwrap();
                let alert_type = match kind {
                    "note" => AlertType::Note,
                    "tip" => AlertType::Tip,
                    "important" => AlertType::Important,
                    "warning" => AlertType::Warning,
                    _ => AlertType::Caution,
                };
                let n = line.len() - 1 - self.offset;
                self.advance_offset(line, n, false);
                *container = self.add_child(*container, NodeValue::Alert { alert_type, title: None, multiline: false, fence_length: 0, fence_offset: 0 });
            } else if !indented && scanners::open_multiline_block_quote_fence(rest).is_some() {
                let fence_length = scanners::open_multiline_block_quote_fence(rest).unwrap();
                let fence_offset = self.first_nonspace - self.offset;
                let n = line.len() - 1 - self.offset;
                self.advance_offset(line, n, false);
                *container = self.add_child(*container, NodeValue::MultilineBlockQuote { fence_length, fence_offset });
            } else if !indented && rest.first() == Some(&b'>') {
                let n = self.first_nonspace + 1 - self.offset;
                self.advance_offset(line, n, false);
                if self.offset < line.len() && strings::is_space_or_tab(line[self.offset]) {
                    self.advance_offset(line, 1, true);
                }
                *container = self.add_child(*container, NodeValue::BlockQuote);
            } else if !indented && scanners::atx_heading_start(rest).is_some() {
                let (matched, level) = scanners::atx_heading_start(rest).unwrap();
                let n = self.first_nonspace + matched - self.offset;
                self.advance_offset(line, n, false);
                *container = self.add_child(*container, NodeValue::Heading { level, setext: false });
            } else if !indented && scanners::open_code_fence(rest).is_some() {
                let matched = scanners::open_code_fence(rest).unwrap();
                let fence_offset = self.first_nonspace - self.offset;
                let fence_char = rest[0];
                *container = self.add_child(
                    *container,
                    NodeValue::CodeBlock { fenced: true, fence_char, fence_length: matched, fence_offset, info: String::new(), literal: String::new() },
                );
                let n = self.first_nonspace + matched - self.offset;
                self.advance_offset(line, n, false);
            } else if !indented
                && (scanners::html_block_start(rest).is_some()
                    || (!matches!(self.arena.get(*container).value, NodeValue::Paragraph) && scanners::html_block_start_7(rest).is_some()))
            {
                let block_type = scanners::html_block_start(rest).or_else(|| scanners::html_block_start_7(rest)).unwrap();
                *container = self.add_child(*container, NodeValue::HtmlBlock { block_type, literal: String::new() });
            } else if !indented && matches!(self.arena.get(*container).value, NodeValue::Paragraph) && scanners::setext_heading_line(rest).is_some() {
                let level = scanners::setext_heading_line(rest).unwrap();
                let has_content = self.resolve_reference_link_definitions(*container);
                if has_content {
                    self.arena.get_mut(*container).value = NodeValue::Heading { level, setext: true };
                    let n = line.len() - 1 - self.offset;
                    self.advance_offset(line, n, false);
                } else {
                    // the paragraph consisted only of reference definitions; treat line normally
                    // fall through by re-running the loop with the (now possibly empty) paragraph removed
                    // cmark: paragraph is kept but empty; the line gets processed below as new content
                    break;
                }
            } else if !indented
                && !(matches!(self.arena.get(*container).value, NodeValue::Paragraph) && !all_matched)
                && self.thematic_break_kill_pos <= self.first_nonspace
                && scanners::thematic_break(rest).is_some()
            {
                *container = self.add_child(*container, NodeValue::ThematicBreak);
                let n = line.len() - 1 - self.offset;
                self.advance_offset(line, n, false);
            } else if !indented && depth < MAX_LIST_DEPTH && scanners::footnote_definition(rest).is_some() {
                let matched = scanners::footnote_definition(rest).unwrap();
                // name between [^ and ]
                let close = rest.iter().position(|&c| c == b']').unwrap();
                let name = String::from_utf8_lossy(&rest[2..close]).to_string();
                let n = self.first_nonspace + matched - self.offset;
                self.advance_offset(line, n, false);
                *container = self.add_child(*container, NodeValue::FootnoteDefinition { name, total_references: 0 });
            } else if !indented && rest.first() == Some(&b':') && rest.len() > 1 && (rest[1] == b' ' || rest[1] == b'\t') && self.parse_desc_list_details(container, line) {
                // handled
            } else if (!indented || matches!(self.arena.get(*container).value, NodeValue::List(..)))
                && self.indent < 4
                && parse_list_marker(line, self.first_nonspace, matches!(self.arena.get(*container).value, NodeValue::Paragraph)).is_some()
            {
                let (matched, mut nl) = parse_list_marker(line, self.first_nonspace, matches!(self.arena.get(*container).value, NodeValue::Paragraph)).unwrap();
                let n = self.first_nonspace + matched - self.offset;
                self.advance_offset(line, n, false);
                let save_partially_consumed_tab = self.partially_consumed_tab;
                let save_offset = self.offset;
                let save_column = self.column;
                while self.column - save_column <= 5 && self.offset < line.len() && strings::is_space_or_tab(line[self.offset]) {
                    self.advance_offset(line, 1, true);
                }
                let i = self.column - save_column;
                if i >= 5 || i < 1 || self.offset >= line.len() || strings::is_line_end(line[self.offset]) {
                    nl.padding = matched + 1;
                    self.offset = save_offset;
                    self.column = save_column;
                    self.partially_consumed_tab = save_partially_consumed_tab;
                    if i > 0 {
                        self.advance_offset(line, 1, true);
                    }
                } else {
                    nl.padding = matched + i;
                }
                nl.marker_offset = self.indent;
                // check whether we need a new list
                let need_new_list = match &self.arena.get(*container).value {
                    NodeValue::List(cl) => !lists_match(cl, &nl),
                    _ => true,
                };
                if need_new_list {
                    *container = self.add_child(*container, NodeValue::List(nl.clone()));
                }
                *container = self.add_child(*container, NodeValue::Item(nl));
                depth += 1;
            } else if indented && !maybe_lazy && !self.blank {
                self.advance_offset(line, CODE_INDENT, true);
                *container = self.add_child(
                    *container,
                    NodeValue::CodeBlock { fenced: false, fence_char: 0, fence_length: 0, fence_offset: 0, info: String::new(), literal: String::new() },
                );
            } else {
                let new_container = if !indented { self.try_opening_table(*container, line) } else { None };
                match new_container {
                    Some(c) => {
                        *container = c;
                    }
                    None => break,
                }
            }
            if self.accepts_lines(*container) {
                // if it's a line container, break out
                break;
            }
        }
    }

    pub fn accepts_lines(&self, node: usize) -> bool {
        matches!(
            self.arena.get(node).value,
            NodeValue::Paragraph | NodeValue::Heading { .. } | NodeValue::CodeBlock { .. } | NodeValue::HtmlBlock { .. }
        )
    }

    fn add_text_to_container(&mut self, mut container: usize, last_matched_container: usize, line: &[u8]) {
        self.find_first_nonspace(line);
        if self.blank {
            if let Some(lc) = self.arena.get(container).last_child {
                self.arena.get_mut(lc).last_line_blank = true;
            }
        }
        let ct = &self.arena.get(container).value;
        let last_line_blank = self.blank
            && !matches!(ct, NodeValue::BlockQuote | NodeValue::Heading { .. } | NodeValue::ThematicBreak)
            && !matches!(ct, NodeValue::CodeBlock { fenced: true, .. })
            && !(matches!(ct, NodeValue::Item(..)) && self.arena.get(container).first_child.is_none() && self.arena.get(container).start_line == self.line_number);
        self.arena.get_mut(container).last_line_blank = last_line_blank;
        let mut tmp = container;
        while let Some(p) = self.arena.get(tmp).parent {
            self.arena.get_mut(p).last_line_blank = false;
            tmp = p;
        }

        if self.current != last_matched_container
            && container == last_matched_container
            && !self.blank
            && matches!(self.arena.get(self.current).value, NodeValue::Paragraph)
        {
            self.add_line(self.current, line);
        } else {
            while self.current != last_matched_container {
                self.current = self.finalize(self.current);
            }
            let value = self.arena.get(container).value.clone();
            match value {
                NodeValue::CodeBlock { .. } => {
                    self.add_line(container, line);
                }
                NodeValue::HtmlBlock { block_type, .. } => {
                    self.add_line(container, line);
                    let matches_end = scanners::html_block_end(block_type, &line[self.first_nonspace..]);
                    if matches_end {
                        container = self.finalize(container);
                    }
                }
                _ => {
                    if self.blank {
                        // do nothing
                    } else if self.accepts_lines(container) {
                        let mut l: Vec<u8> = line.to_vec();
                        if let NodeValue::Heading { setext: false, .. } = value {
                            chop_trailing_hashtags(&mut l);
                        }
                        let n = self.first_nonspace - self.offset;
                        self.advance_offset(&l, n, false);
                        self.add_line(container, &l);
                    } else {
                        // create paragraph container for line
                        container = self.add_child(container, NodeValue::Paragraph);
                        let n = self.first_nonspace - self.offset;
                        self.advance_offset(line, n, false);
                        self.add_line(container, line);
                    }
                }
            }
            self.current = container;
        }
    }

    fn add_line(&mut self, node: usize, line: &[u8]) {
        if self.partially_consumed_tab {
            self.offset += 1;
            let chars_to_tab = TAB_STOP - (self.column % TAB_STOP);
            for _ in 0..chars_to_tab {
                self.arena.get_mut(node).content.push(' ');
            }
        }
        if self.offset < line.len() {
            let s = String::from_utf8_lossy(&line[self.offset..]).to_string();
            self.arena.get_mut(node).content.push_str(&s);
        }
    }

    pub fn can_contain(&self, parent: usize, child: &NodeValue) -> bool {
        match &self.arena.get(parent).value {
            NodeValue::Document
            | NodeValue::BlockQuote
            | NodeValue::MultilineBlockQuote { .. }
            | NodeValue::Alert { .. }
            | NodeValue::FootnoteDefinition { .. }
            | NodeValue::DescriptionTerm
            | NodeValue::DescriptionDetails
            | NodeValue::Item(..)
            | NodeValue::TaskItem { .. } => !matches!(
                child,
                NodeValue::Item(..) | NodeValue::TaskItem { .. } | NodeValue::TableRow { .. } | NodeValue::TableCell | NodeValue::DescriptionItem { .. } | NodeValue::DescriptionTerm | NodeValue::DescriptionDetails
            ) && is_block(child),
            NodeValue::List(..) => matches!(child, NodeValue::Item(..) | NodeValue::TaskItem { .. }),
            NodeValue::DescriptionList => matches!(child, NodeValue::DescriptionItem { .. }),
            NodeValue::DescriptionItem { .. } => matches!(child, NodeValue::DescriptionTerm | NodeValue::DescriptionDetails),
            NodeValue::Table { .. } => matches!(child, NodeValue::TableRow { .. }),
            NodeValue::TableRow { .. } => matches!(child, NodeValue::TableCell),
            _ => false,
        }
    }

    pub fn add_child(&mut self, mut parent: usize, value: NodeValue) -> usize {
        while !self.can_contain(parent, &value) {
            parent = self.finalize(parent);
        }
        let child = self.arena.alloc(value, self.line_number);
        self.arena.append(parent, child);
        child
    }

    pub fn finalize(&mut self, node: usize) -> usize {
        self.arena.get_mut(node).open = false;
        let parent = self.arena.get(node).parent;
        let value = self.arena.get(node).value.clone();
        match value {
            NodeValue::Paragraph => {
                let has_content = self.resolve_reference_link_definitions(node);
                if !has_content {
                    self.arena.detach(node);
                }
            }
            NodeValue::CodeBlock { fenced, .. } => {
                if !fenced {
                    let mut content = std::mem::take(&mut self.arena.get_mut(node).content);
                    strings::remove_trailing_blank_lines(&mut content);
                    content.push('\n');
                    if let NodeValue::CodeBlock { literal, .. } = &mut self.arena.get_mut(node).value {
                        *literal = content;
                    }
                } else {
                    let content = std::mem::take(&mut self.arena.get_mut(node).content);
                    let (first, rest) = match content.find('\n') {
                        Some(pos) => (&content[..pos], &content[pos + 1..]),
                        None => (&content[..], ""),
                    };
                    let info = strings::unescape(first.trim_matches(|c: char| c == ' ' || c == '\t' || c == '\r' || c == '\n'));
                    if let NodeValue::CodeBlock { info: i, literal, .. } = &mut self.arena.get_mut(node).value {
                        *i = info;
                        *literal = rest.to_string();
                    }
                }
            }
            NodeValue::HtmlBlock { .. } => {
                let content = std::mem::take(&mut self.arena.get_mut(node).content);
                if let NodeValue::HtmlBlock { literal, .. } = &mut self.arena.get_mut(node).value {
                    *literal = content;
                }
            }
            NodeValue::List(..) => {
                let tight = self.compute_list_tight(node);
                if let NodeValue::List(nl) = &mut self.arena.get_mut(node).value {
                    nl.tight = tight;
                }
            }
            _ => {}
        }
        parent.unwrap_or(self.root)
    }

    fn compute_list_tight(&self, list: usize) -> bool {
        let mut tight = true;
        let mut item = self.arena.get(list).first_child;
        while let Some(it) = item {
            let itn = self.arena.get(it);
            if itn.last_line_blank && itn.next.is_some() {
                tight = false;
                break;
            }
            let mut subitem = itn.first_child;
            while let Some(si) = subitem {
                let sin = self.arena.get(si);
                if (itn.next.is_some() || sin.next.is_some()) && self.ends_with_blank_line(si) {
                    tight = false;
                    break;
                }
                subitem = sin.next;
            }
            if !tight {
                break;
            }
            item = itn.next;
        }
        tight
    }

    fn ends_with_blank_line(&self, mut node: usize) -> bool {
        loop {
            let n = self.arena.get(node);
            if n.last_line_blank {
                return true;
            }
            match n.value {
                NodeValue::List(..) | NodeValue::Item(..) | NodeValue::TaskItem { .. } => {
                    if let Some(lc) = n.last_child {
                        node = lc;
                        continue;
                    }
                    return false;
                }
                _ => return false,
            }
        }
    }

    pub fn find_first_nonspace(&mut self, line: &[u8]) {
        let mut chars_to_tab = TAB_STOP - (self.column % TAB_STOP);
        if self.first_nonspace <= self.offset {
            self.first_nonspace = self.offset;
            self.first_nonspace_column = self.column;
            loop {
                if self.first_nonspace >= line.len() {
                    break;
                }
                let c = line[self.first_nonspace];
                if c == b' ' {
                    self.first_nonspace += 1;
                    self.first_nonspace_column += 1;
                    chars_to_tab -= 1;
                    if chars_to_tab == 0 {
                        chars_to_tab = TAB_STOP;
                    }
                } else if c == b'\t' {
                    self.first_nonspace += 1;
                    self.first_nonspace_column += chars_to_tab;
                    chars_to_tab = TAB_STOP;
                } else {
                    break;
                }
            }
        }
        self.indent = self.first_nonspace_column - self.column;
        self.blank = self.first_nonspace >= line.len() || strings::is_space_or_tab(line[self.first_nonspace]) || scanners::is_line_end(line[self.first_nonspace]);
        if self.first_nonspace >= line.len() {
            self.blank = true;
        }
    }

    pub fn advance_offset(&mut self, line: &[u8], mut count: usize, columns: bool) {
        while count > 0 {
            if self.offset >= line.len() {
                break;
            }
            let c = line[self.offset];
            if c == b'\t' {
                let chars_to_tab = TAB_STOP - (self.column % TAB_STOP);
                if columns {
                    self.partially_consumed_tab = chars_to_tab > count;
                    let chars_to_advance = std::cmp::min(count, chars_to_tab);
                    self.column += chars_to_advance;
                    self.offset += if self.partially_consumed_tab { 0 } else { 1 };
                    count -= chars_to_advance;
                } else {
                    self.partially_consumed_tab = false;
                    self.column += chars_to_tab;
                    self.offset += 1;
                    count -= 1;
                }
            } else {
                self.partially_consumed_tab = false;
                self.offset += 1;
                self.column += 1;
                count -= 1;
            }
        }
        // Reset first_nonspace so it will be recomputed
        self.first_nonspace = 0;
        self.first_nonspace_column = 0;
    }

    /// Parses link reference definitions at the start of a paragraph's content.
    /// Returns true if content remains.
    fn resolve_reference_link_definitions(&mut self, node: usize) -> bool {
        let content = self.arena.get(node).content.clone();
        let mut pos = 0;
        let bytes = content.as_bytes();
        while pos < bytes.len() && bytes[pos] == b'[' {
            match super::inline::parse_reference_inline(&content[pos..]) {
                Some((consumed, label, url, title)) => {
                    let norm = strings::normalize_label(&label);
                    if !norm.is_empty() && !self.refmap.contains_key(&norm) {
                        self.refmap.insert(norm, Reference { url, title });
                    }
                    pos += consumed;
                }
                None => break,
            }
        }
        let rest = &content[pos..];
        let has_content = !rest.bytes().all(|c| strings::is_whitespace_byte(c));
        self.arena.get_mut(node).content = rest.to_string();
        has_content
    }

    fn parse_desc_list_details(&mut self, container: &mut usize, line: &[u8]) -> bool {
        let mut tight = false;
        let cur = *container;
        let (base, last_child) = match self.arena.get(cur).last_child {
            Some(lc) => (cur, lc),
            None => {
                // detail line directly after the term, without blank line
                let parent = match self.arena.get(cur).parent {
                    Some(p) => p,
                    None => return false,
                };
                tight = true;
                (parent, cur)
            }
        };
        let lc_value = self.arena.get(last_child).value.clone();
        match lc_value {
            NodeValue::Paragraph => {
                let base_parent_is_details = matches!(self.arena.get(base).value, NodeValue::DescriptionDetails);
                if base_parent_is_details {
                    // another details for the same item
                    let item = self.arena.get(base).parent.unwrap();
                    // close the current details
                    let mut c = self.current;
                    while c != item && c != self.root {
                        c = self.finalize(c);
                    }
                    let details = self.arena.alloc(NodeValue::DescriptionDetails, self.line_number);
                    self.arena.append(item, details);
                    self.advance_past_colon(line);
                    *container = details;
                    self.current = details;
                    return true;
                }
                // finalize the paragraph (resolve references)
                if self.arena.get(last_child).open {
                    let mut c = self.current;
                    while c != last_child && c != self.root {
                        c = self.finalize(c);
                    }
                    self.finalize(last_child);
                    self.current = base;
                }
                // reuse previous description list if the paragraph's previous sibling is one
                let prev = self.arena.get(last_child).prev;
                let list = match prev {
                    Some(p) if matches!(self.arena.get(p).value, NodeValue::DescriptionList) => {
                        self.arena.get_mut(p).open = true;
                        p
                    }
                    _ => {
                        let l = self.arena.alloc(NodeValue::DescriptionList, self.line_number);
                        self.arena.insert_before(last_child, l);
                        l
                    }
                };
                let item = self.arena.alloc(NodeValue::DescriptionItem { tight }, self.line_number);
                self.arena.append(list, item);
                let term = self.arena.alloc(NodeValue::DescriptionTerm, self.line_number);
                self.arena.append(item, term);
                self.arena.detach(last_child);
                self.arena.append(term, last_child);
                self.arena.get_mut(term).open = false;
                let details = self.arena.alloc(NodeValue::DescriptionDetails, self.line_number);
                self.arena.append(item, details);
                self.advance_past_colon(line);
                *container = details;
                self.current = details;
                true
            }
            NodeValue::DescriptionList => {
                // blank line then another `: details` for the last item
                let item = match self.arena.get(last_child).last_child {
                    Some(i) => i,
                    None => return false,
                };
                self.arena.get_mut(last_child).open = true;
                self.arena.get_mut(item).open = true;
                let details = self.arena.alloc(NodeValue::DescriptionDetails, self.line_number);
                self.arena.append(item, details);
                self.advance_past_colon(line);
                *container = details;
                self.current = details;
                true
            }
            _ => false,
        }
    }

    fn advance_past_colon(&mut self, line: &[u8]) {
        let n = self.first_nonspace + 1 - self.offset;
        self.advance_offset(line, n, false);
        if self.offset < line.len() && strings::is_space_or_tab(line[self.offset]) {
            self.advance_offset(line, 1, true);
        }
    }

    fn try_opening_table(&mut self, container: usize, line: &[u8]) -> Option<usize> {
        let value = self.arena.get(container).value.clone();
        match value {
            NodeValue::Paragraph => self.try_opening_header(container, line),
            NodeValue::Table { alignments, .. } => self.try_opening_row(container, &alignments, line),
            _ => None,
        }
    }

    fn try_opening_header(&mut self, container: usize, line: &[u8]) -> Option<usize> {
        let rest = &line[self.first_nonspace..];
        if !scanners::table_start(rest) {
            return None;
        }
        let content = self.arena.get(container).content.clone();
        // last line of the paragraph content
        let trimmed = content.trim_end_matches('\n');
        let last_line_start = match trimmed.rfind('\n') {
            Some(i) => i + 1,
            None => 0,
        };
        let header_line = &content[last_line_start..];
        let header_cells = super::table::row(header_line.as_bytes())?;
        let marker_cells = super::table::row(rest)?;
        if header_cells.len() != marker_cells.len() || header_cells.is_empty() {
            return None;
        }
        let mut alignments = Vec::new();
        for cell in &marker_cells {
            let c = cell.trim();
            let left = c.starts_with(':');
            let right = c.ends_with(':');
            alignments.push(match (left, right) {
                (true, true) => TableAlignment::Center,
                (true, false) => TableAlignment::Left,
                (false, true) => TableAlignment::Right,
                (false, false) => TableAlignment::None,
            });
        }
        let num_columns = header_cells.len();
        let table = if last_line_start > 0 {
            // keep preceding lines as a paragraph; insert table after it
            self.arena.get_mut(container).content = content[..last_line_start].to_string();
            self.arena.get_mut(container).open = false;
            let t = self.arena.alloc(NodeValue::Table { alignments, num_columns }, self.line_number);
            self.arena.insert_after(container, t);
            // finalize the paragraph properly (reference definitions)
            let has_content = self.resolve_reference_link_definitions(container);
            if !has_content {
                self.arena.detach(container);
            }
            t
        } else {
            self.arena.get_mut(container).value = NodeValue::Table { alignments, num_columns };
            self.arena.get_mut(container).content = String::new();
            container
        };
        let row = self.arena.alloc(NodeValue::TableRow { header: true }, self.line_number);
        self.arena.append(table, row);
        for cell in header_cells {
            let c = self.arena.alloc(NodeValue::TableCell, self.line_number);
            self.arena.get_mut(c).content = cell;
            self.arena.append(row, c);
        }
        let n = line.len() - 1 - self.offset;
        self.advance_offset(line, n, false);
        self.current = table;
        Some(table)
    }

    fn try_opening_row(&mut self, container: usize, alignments: &[TableAlignment], line: &[u8]) -> Option<usize> {
        if self.blank {
            return None;
        }
        let rest = &line[self.first_nonspace..];
        let cells = super::table::row(rest)?;
        let row = self.arena.alloc(NodeValue::TableRow { header: false }, self.line_number);
        self.arena.append(container, row);
        let n = alignments.len();
        for i in 0..n {
            let c = self.arena.alloc(NodeValue::TableCell, self.line_number);
            self.arena.get_mut(c).content = cells.get(i).cloned().unwrap_or_default();
            self.arena.append(row, c);
        }
        let n = line.len() - 1 - self.offset;
        self.advance_offset(line, n, false);
        Some(row)
    }

    pub fn finish(&mut self) {
        while self.current != self.root {
            self.current = self.finalize(self.current);
        }
        self.finalize(self.root);
    }
}

fn is_block(v: &NodeValue) -> bool {
    !matches!(
        v,
        NodeValue::Text(_)
            | NodeValue::SoftBreak
            | NodeValue::LineBreak
            | NodeValue::Code(_)
            | NodeValue::HtmlInline(_)
            | NodeValue::Emph
            | NodeValue::Strong
            | NodeValue::Strikethrough
            | NodeValue::Underline
            | NodeValue::Spoiler
            | NodeValue::Link { .. }
            | NodeValue::Image { .. }
            | NodeValue::FootnoteReference { .. }
            | NodeValue::WikiLink { .. }
            | NodeValue::ShortCode(_)
    )
}

fn lists_match(a: &ListData, b: &ListData) -> bool {
    a.list_type == b.list_type && a.delimiter == b.delimiter && a.bullet_char == b.bullet_char
}

fn chop_trailing_hashtags(line: &mut Vec<u8>) {
    // remove trailing newline for processing
    let mut end = line.len();
    while end > 0 && (line[end - 1] == b'\n' || line[end - 1] == b'\r') {
        end -= 1;
    }
    let newline_part: Vec<u8> = line[end..].to_vec();
    let mut n = end;
    while n > 0 && strings::is_space_or_tab(line[n - 1]) {
        n -= 1;
    }
    let orig_n = n;
    while n > 0 && line[n - 1] == b'#' {
        n -= 1;
    }
    // Check for a space before the final '#'s; if not, the hashes aren't a closing sequence
    if n != orig_n && (n == 0 || strings::is_space_or_tab(line[n - 1])) {
        // strip trailing spaces too
        while n > 0 && strings::is_space_or_tab(line[n - 1]) {
            n -= 1;
        }
        line.truncate(n);
        line.extend_from_slice(&newline_part);
    } else {
        // just strip trailing spaces
        line.truncate(orig_n);
        line.extend_from_slice(&newline_part);
    }
}

/// Parses a list marker at `pos`. Returns (consumed length, ListData).
pub fn parse_list_marker(line: &[u8], mut pos: usize, interrupts_paragraph: bool) -> Option<(usize, ListData)> {
    let startpos = pos;
    if pos >= line.len() {
        return None;
    }
    let c = line[pos];
    if c == b'*' || c == b'-' || c == b'+' {
        pos += 1;
        if pos >= line.len() || !(strings::is_space_or_tab(line[pos]) || scanners::is_line_end(line[pos])) {
            return None;
        }
        if interrupts_paragraph {
            // require non-blank content after marker
            let mut i = pos;
            while i < line.len() && strings::is_space_or_tab(line[i]) {
                i += 1;
            }
            if i >= line.len() || scanners::is_line_end(line[i]) {
                return None;
            }
        }
        let nl = ListData { list_type: ListType::Bullet, marker_offset: 0, padding: 0, start: 1, delimiter: DelimType::Period, bullet_char: c, tight: false };
        return Some((pos - startpos, nl));
    } else if c.is_ascii_digit() {
        let mut start: usize = 0;
        let mut digits = 0;
        loop {
            start = start * 10 + (line[pos] - b'0') as usize;
            pos += 1;
            digits += 1;
            if !(digits < 9 && pos < line.len() && line[pos].is_ascii_digit()) {
                break;
            }
        }
        if interrupts_paragraph && start != 1 {
            return None;
        }
        if pos >= line.len() {
            return None;
        }
        let d = line[pos];
        if d == b'.' || d == b')' {
            pos += 1;
            if pos >= line.len() || !(strings::is_space_or_tab(line[pos]) || scanners::is_line_end(line[pos])) {
                return None;
            }
            if interrupts_paragraph {
                let mut i = pos;
                while i < line.len() && strings::is_space_or_tab(line[i]) {
                    i += 1;
                }
                if i >= line.len() || scanners::is_line_end(line[i]) {
                    return None;
                }
            }
            let nl = ListData {
                list_type: ListType::Ordered,
                marker_offset: 0,
                padding: 0,
                start,
                delimiter: if d == b'.' { DelimType::Period } else { DelimType::Paren },
                bullet_char: 0,
                tight: false,
            };
            return Some((pos - startpos, nl));
        }
    }
    None
}
