//! GFM table row parsing.

use super::strings;

fn is_table_space(c: u8) -> bool {
    c == b' ' || c == b'\t' || c == 0x0b || c == 0x0c
}

/// scan_table_cell: (escaped_char | [^|\r\n])+ ; returns matched length
fn scan_table_cell(s: &[u8], mut i: usize) -> usize {
    let start = i;
    while i < s.len() {
        let c = s[i];
        if c == b'\\' && i + 1 < s.len() && strings::is_ascii_punct(s[i + 1]) {
            i += 2;
            continue;
        }
        if c == b'|' || c == b'\r' || c == b'\n' {
            break;
        }
        i += 1;
    }
    i - start
}

/// scan_table_cell_end: [|] spacechar*
fn scan_table_cell_end(s: &[u8], mut i: usize) -> usize {
    let start = i;
    if i < s.len() && s[i] == b'|' {
        i += 1;
        while i < s.len() && is_table_space(s[i]) {
            i += 1;
        }
        return i - start;
    }
    0
}

/// scan_table_row_end: spacechar* newline
fn scan_table_row_end(s: &[u8], mut i: usize) -> usize {
    let start = i;
    while i < s.len() && is_table_space(s[i]) {
        i += 1;
    }
    if i < s.len() && s[i] == b'\r' {
        i += 1;
    }
    if i < s.len() && s[i] == b'\n' {
        i += 1;
        return i - start;
    }
    0
}

fn unescape_pipes(s: &[u8]) -> String {
    let mut out = Vec::with_capacity(s.len());
    let mut i = 0;
    while i < s.len() {
        if s[i] == b'\\' && i + 1 < s.len() && s[i + 1] == b'|' {
            out.push(b'|');
            i += 2;
        } else {
            out.push(s[i]);
            i += 1;
        }
    }
    String::from_utf8_lossy(&out).to_string()
}

/// Parses a table row from a string (which should end with a newline).
/// Returns the trimmed cell contents, or None if the string is not a row.
pub fn row(input: &[u8]) -> Option<Vec<String>> {
    let s: Vec<u8>;
    let s = if input.last() == Some(&b'\n') {
        input
    } else {
        s = [input, b"\n"].concat();
        &s[..]
    };
    let len = s.len();
    let mut cells: Vec<String> = Vec::new();
    let mut offset = scan_table_cell_end(s, 0);
    let mut expect_more_cells = true;
    while offset < len && expect_more_cells {
        let cell_matched = scan_table_cell(s, offset);
        let pipe_matched = scan_table_cell_end(s, offset + cell_matched);
        if cell_matched > 0 || pipe_matched > 0 {
            let raw = &s[offset..offset + cell_matched];
            let cell = unescape_pipes(raw);
            cells.push(cell.trim_matches(|c: char| c == ' ' || c == '\t' || c == '\n' || c == '\r' || c == '\u{b}' || c == '\u{c}').to_string());
        }
        offset += cell_matched + pipe_matched;
        if pipe_matched > 0 {
            expect_more_cells = true;
        } else {
            let row_end = scan_table_row_end(s, offset);
            offset += row_end;
            if row_end > 0 && offset != len {
                // not the last line: restart
                cells.clear();
                offset += scan_table_cell_end(s, offset);
                expect_more_cells = true;
            } else {
                expect_more_cells = false;
            }
        }
    }
    if offset != len || cells.is_empty() {
        return None;
    }
    Some(cells)
}
