//! Inline parsing, modelled after cmark/comrak.

use super::block::Reference;
use super::emoji;
use super::node::*;
use super::scanners;
use super::strings;
use std::collections::HashMap;

const MAXBACKTICKS: usize = 80;

struct Delimiter {
    inl: usize,
    position: usize,
    length: usize,
    delim_char: u8,
    can_open: bool,
    can_close: bool,
    prev: Option<usize>,
    next: Option<usize>,
    active: bool,
}

struct Bracket {
    inl_text: usize,
    position: usize,
    image: bool,
    active: bool,
    bracket_after: bool,
    previous_delimiter: Option<usize>,
}

pub struct InlineParser<'a> {
    input: &'a [u8],
    pos: usize,
    arena: &'a mut Arena,
    refmap: &'a HashMap<String, Reference>,
    delims: Vec<Delimiter>,
    last_delim: Option<usize>,
    brackets: Vec<Bracket>,
    backticks: [usize; MAXBACKTICKS + 1],
    scanned_for_backticks: bool,
    no_link_openers: bool,
}

fn is_special(c: u8) -> bool {
    matches!(c, b'\n' | b'\r' | b'`' | b'\\' | b'&' | b'<' | b'[' | b']' | b'!' | b'*' | b'_' | b'~' | b'|' | b':')
}

impl<'a> InlineParser<'a> {
    pub fn new(input: &'a [u8], arena: &'a mut Arena, refmap: &'a HashMap<String, Reference>) -> Self {
        InlineParser {
            input,
            pos: 0,
            arena,
            refmap,
            delims: Vec::new(),
            last_delim: None,
            brackets: Vec::new(),
            backticks: [0; MAXBACKTICKS + 1],
            scanned_for_backticks: false,
            no_link_openers: false,
        }
    }

    fn peek(&self) -> Option<u8> {
        self.input.get(self.pos).copied()
    }
    fn peek_at(&self, p: usize) -> Option<u8> {
        self.input.get(p).copied()
    }
    fn eof(&self) -> bool {
        self.pos >= self.input.len()
    }

    fn make_inline(&mut self, v: NodeValue) -> usize {
        self.arena.alloc(v, 0)
    }

    pub fn parse_inlines(&mut self, parent: usize) {
        while !self.eof() {
            if let Some(n) = self.parse_inline(parent) {
                self.arena.append(parent, n);
            }
        }
        self.process_emphasis(None);
        self.brackets.clear();
        // consolidate adjacent text nodes
        consolidate_text(self.arena, parent);
    }

    fn parse_inline(&mut self, parent: usize) -> Option<usize> {
        let c = self.peek()?;
        let new_inl: Option<usize> = match c {
            b'\n' | b'\r' => Some(self.handle_newline()),
            b'`' => Some(self.handle_backticks()),
            b'\\' => Some(self.handle_backslash()),
            b'&' => Some(self.handle_entity()),
            b'<' => Some(self.handle_pointy_brace()),
            b'*' | b'_' | b'~' | b'|' => Some(self.handle_delim(c)),
            b'[' => {
                if self.peek_at(self.pos + 1) == Some(b'[') {
                    if let Some(w) = self.handle_wikilink() {
                        return Some(w);
                    }
                }
                self.pos += 1;
                let inl = self.make_inline(NodeValue::Text("[".to_string()));
                self.push_bracket(false, inl);
                Some(inl)
            }
            b']' => self.handle_close_bracket(),
            b'!' => {
                self.pos += 1;
                if self.peek() == Some(b'[') && self.peek_at(self.pos + 1) != Some(b'^') {
                    self.pos += 1;
                    let inl = self.make_inline(NodeValue::Text("![".to_string()));
                    self.push_bracket(true, inl);
                    Some(inl)
                } else {
                    Some(self.make_inline(NodeValue::Text("!".to_string())))
                }
            }
            b':' => Some(self.handle_shortcode()),
            _ => {
                let endpos = self.find_special_char();
                let text = String::from_utf8_lossy(&self.input[self.pos..endpos]).to_string();
                self.pos = endpos;
                Some(self.make_inline(NodeValue::Text(text)))
            }
        };
        let _ = parent;
        new_inl
    }

    fn find_special_char(&self) -> usize {
        let mut n = self.pos + 1;
        while n < self.input.len() && !is_special(self.input[n]) {
            n += 1;
        }
        n
    }

    fn handle_newline(&mut self) -> usize {
        let nlpos = self.pos;
        if self.input[self.pos] == b'\r' {
            self.pos += 1;
        }
        if self.pos < self.input.len() && self.input[self.pos] == b'\n' {
            self.pos += 1;
        }
        self.skip_spaces();
        if nlpos > 1 && self.input[nlpos - 1] == b' ' && self.input[nlpos - 2] == b' ' {
            self.make_inline(NodeValue::LineBreak)
        } else {
            self.make_inline(NodeValue::SoftBreak)
        }
    }

    fn skip_spaces(&mut self) {
        while let Some(c) = self.peek() {
            if c == b' ' || c == b'\t' {
                self.pos += 1;
            } else {
                break;
            }
        }
    }

    fn take_while(&mut self, c: u8) -> usize {
        let start = self.pos;
        while self.peek() == Some(c) {
            self.pos += 1;
        }
        self.pos - start
    }

    fn scan_to_closing_backtick(&mut self, openticklength: usize) -> Option<usize> {
        if openticklength > MAXBACKTICKS {
            return None;
        }
        if self.scanned_for_backticks && self.backticks[openticklength] <= self.pos {
            return None;
        }
        loop {
            while let Some(c) = self.peek() {
                if c == b'`' {
                    break;
                }
                self.pos += 1;
            }
            if self.eof() {
                self.scanned_for_backticks = true;
                return None;
            }
            let numticks = self.take_while(b'`');
            if numticks <= MAXBACKTICKS {
                self.backticks[numticks] = self.pos - numticks;
            }
            if numticks == openticklength {
                return Some(self.pos);
            }
        }
    }

    fn handle_backticks(&mut self) -> usize {
        let startpos = self.pos;
        let openticks = self.take_while(b'`');
        let endpos = self.scan_to_closing_backtick(openticks);
        match endpos {
            None => {
                self.pos = startpos + openticks;
                self.make_inline(NodeValue::Text("`".repeat(openticks)))
            }
            Some(endpos) => {
                let raw = &self.input[startpos + openticks..endpos - openticks];
                let mut buf: Vec<u8> = raw.iter().map(|&b| if b == b'\n' || b == b'\r' { b' ' } else { b }).collect();
                // strip one space from each side if both sides have a space and not all spaces
                if buf.len() >= 2 && buf[0] == b' ' && buf[buf.len() - 1] == b' ' && buf.iter().any(|&b| b != b' ') {
                    buf = buf[1..buf.len() - 1].to_vec();
                }
                let s = String::from_utf8_lossy(&buf).to_string();
                self.make_inline(NodeValue::Code(s))
            }
        }
    }

    fn handle_backslash(&mut self) -> usize {
        self.pos += 1;
        match self.peek() {
            Some(c) if strings::is_ascii_punct(c) => {
                self.pos += 1;
                self.make_inline(NodeValue::Text((c as char).to_string()))
            }
            Some(b'\n') | Some(b'\r') => {
                // hard line break
                self.handle_newline_after_backslash()
            }
            _ => self.make_inline(NodeValue::Text("\\".to_string())),
        }
    }

    fn handle_newline_after_backslash(&mut self) -> usize {
        if self.input[self.pos] == b'\r' {
            self.pos += 1;
        }
        if self.pos < self.input.len() && self.input[self.pos] == b'\n' {
            self.pos += 1;
        }
        self.skip_spaces();
        self.make_inline(NodeValue::LineBreak)
    }

    fn handle_entity(&mut self) -> usize {
        match strings::unescape_entity(&self.input[self.pos..]) {
            Some((n, s)) => {
                self.pos += n;
                self.make_inline(NodeValue::Text(s))
            }
            None => {
                self.pos += 1;
                self.make_inline(NodeValue::Text("&".to_string()))
            }
        }
    }

    fn handle_pointy_brace(&mut self) -> usize {
        self.pos += 1;
        let rest = &self.input[self.pos..];
        if let Some(n) = scan_autolink_uri(rest) {
            let url = String::from_utf8_lossy(&rest[..n - 1]).to_string();
            self.pos += n;
            let link = self.make_inline(NodeValue::Link { url: url.clone(), title: String::new() });
            let t = self.make_inline(NodeValue::Text(url));
            self.arena.append(link, t);
            return link;
        }
        if let Some(n) = scan_autolink_email(rest) {
            let addr = String::from_utf8_lossy(&rest[..n - 1]).to_string();
            self.pos += n;
            let link = self.make_inline(NodeValue::Link { url: format!("mailto:{}", addr), title: String::new() });
            let t = self.make_inline(NodeValue::Text(addr));
            self.arena.append(link, t);
            return link;
        }
        if let Some(n) = scan_html_tag(rest) {
            let s = String::from_utf8_lossy(&self.input[self.pos - 1..self.pos + n]).to_string();
            self.pos += n;
            return self.make_inline(NodeValue::HtmlInline(s));
        }
        self.make_inline(NodeValue::Text("<".to_string()))
    }

    fn handle_shortcode(&mut self) -> usize {
        // :name: where name is [A-Za-z0-9_+-]+
        let start = self.pos + 1;
        let mut i = start;
        while i < self.input.len() && (self.input[i].is_ascii_alphanumeric() || matches!(self.input[i], b'_' | b'+' | b'-')) {
            i += 1;
        }
        if i > start && i < self.input.len() && self.input[i] == b':' {
            let name = std::str::from_utf8(&self.input[start..i]).unwrap_or("");
            if let Some(e) = emoji::lookup(name) {
                self.pos = i + 1;
                return self.make_inline(NodeValue::ShortCode(e.to_string()));
            }
        }
        self.pos += 1;
        self.make_inline(NodeValue::Text(":".to_string()))
    }

    fn scan_delims(&mut self, c: u8) -> (usize, bool, bool) {
        let before_char = if self.pos == 0 {
            '\n'
        } else {
            let mut before_char_pos = self.pos - 1;
            // back up to the start of the UTF-8 sequence
            while before_char_pos > 0 && (self.input[before_char_pos] >> 6 == 2) {
                before_char_pos -= 1;
            }
            std::str::from_utf8(&self.input[before_char_pos..self.pos]).ok().and_then(|s| s.chars().next()).unwrap_or('\u{FFFD}')
        };
        let mut numdelims = 0;
        if c == b'\'' || c == b'"' {
            numdelims += 1;
            self.pos += 1;
        } else {
            while self.peek() == Some(c) {
                numdelims += 1;
                self.pos += 1;
            }
        }
        let after_char = if self.eof() {
            '\n'
        } else {
            std::str::from_utf8(&self.input[self.pos..std::cmp::min(self.pos + 4, self.input.len())])
                .ok()
                .or_else(|| {
                    // try progressively shorter
                    for l in (1..4).rev() {
                        if self.pos + l <= self.input.len() {
                            if let Ok(s) = std::str::from_utf8(&self.input[self.pos..self.pos + l]) {
                                return Some(s);
                            }
                        }
                    }
                    None
                })
                .and_then(|s| s.chars().next())
                .unwrap_or('\u{FFFD}')
        };
        let left_flanking = numdelims > 0
            && !after_char.is_whitespace()
            && !(strings::is_punctuation(after_char) && !before_char.is_whitespace() && !strings::is_punctuation(before_char));
        let right_flanking = numdelims > 0
            && !before_char.is_whitespace()
            && !(strings::is_punctuation(before_char) && !after_char.is_whitespace() && !strings::is_punctuation(after_char));
        let (can_open, can_close) = if c == b'_' {
            (
                left_flanking && (!right_flanking || strings::is_punctuation(before_char)),
                right_flanking && (!left_flanking || strings::is_punctuation(after_char)),
            )
        } else {
            (left_flanking, right_flanking)
        };
        (numdelims, can_open, can_close)
    }

    fn handle_delim(&mut self, c: u8) -> usize {
        let startpos = self.pos;
        let (numdelims, can_open, can_close) = self.scan_delims(c);
        let contents = String::from_utf8_lossy(&self.input[startpos..self.pos]).to_string();
        let inl = self.make_inline(NodeValue::Text(contents));
        let is_delim = match c {
            b'|' => numdelims == 2,
            b'~' => numdelims <= 2,
            _ => true,
        };
        if (can_open || can_close) && is_delim {
            self.push_delimiter(c, can_open, can_close, inl, startpos, numdelims);
        }
        inl
    }

    fn push_delimiter(&mut self, c: u8, can_open: bool, can_close: bool, inl: usize, position: usize, length: usize) {
        let d = Delimiter { inl, position, length, delim_char: c, can_open, can_close, prev: self.last_delim, next: None, active: true };
        self.delims.push(d);
        let idx = self.delims.len() - 1;
        if let Some(l) = self.last_delim {
            self.delims[l].next = Some(idx);
        }
        self.last_delim = Some(idx);
    }

    fn remove_delimiter(&mut self, idx: usize) {
        let (prev, next) = (self.delims[idx].prev, self.delims[idx].next);
        if let Some(p) = prev {
            self.delims[p].next = next;
        }
        match next {
            Some(n) => self.delims[n].prev = prev,
            None => self.last_delim = prev,
        }
        self.delims[idx].active = false;
    }

    fn first_delim_after(&self, stack_bottom: Option<usize>) -> Option<usize> {
        // walk from last_delim backwards until prev == stack_bottom
        let mut closer = self.last_delim;
        while let Some(c) = closer {
            if self.delims[c].prev == stack_bottom {
                break;
            }
            closer = self.delims[c].prev;
        }
        closer
    }

    fn process_emphasis(&mut self, stack_bottom: Option<usize>) {
        // openers_bottom indexed by [delim char kind][length % 3][can_open]
        let mut openers_bottom: HashMap<(u8, usize, bool), Option<usize>> = HashMap::new();
        let mut closer = self.first_delim_after(stack_bottom);
        while let Some(cl) = closer {
            if self.delims[cl].can_close {
                let key = (self.delims[cl].delim_char, self.delims[cl].length % 3, self.delims[cl].can_open);
                let bottom = *openers_bottom.get(&key).unwrap_or(&stack_bottom);
                let mut opener = self.delims[cl].prev;
                let mut opener_found = false;
                while let Some(op) = opener {
                    if opener == stack_bottom || opener == bottom {
                        break;
                    }
                    if self.delims[op].can_open && self.delims[op].delim_char == self.delims[cl].delim_char {
                        let odd_match = (self.delims[cl].can_open || self.delims[op].can_close)
                            && self.delims[cl].length % 3 != 0
                            && (self.delims[op].length + self.delims[cl].length) % 3 == 0;
                        if !odd_match {
                            opener_found = true;
                            break;
                        }
                    }
                    opener = self.delims[op].prev;
                }
                let old_closer = cl;
                if opener_found {
                    closer = self.insert_emph(opener.unwrap(), cl);
                } else {
                    closer = self.delims[cl].next;
                }
                if !opener_found {
                    openers_bottom.insert(key, self.delims[old_closer].prev);
                    if !self.delims[old_closer].can_open {
                        self.remove_delimiter(old_closer);
                    }
                }
            } else {
                closer = self.delims[cl].next;
            }
        }
        // remove all delimiters above stack_bottom
        let mut d = self.last_delim;
        while let Some(di) = d {
            if d == stack_bottom {
                break;
            }
            let prev = self.delims[di].prev;
            self.remove_delimiter(di);
            d = prev;
        }
    }

    fn insert_emph(&mut self, opener: usize, closer: usize) -> Option<usize> {
        let opener_char = self.delims[opener].delim_char;
        let opener_num = self.delims[opener].length;
        let closer_num = self.delims[closer].length;
        let use_delims = if closer_num >= 2 && opener_num >= 2 { 2 } else { 1 };
        let opener_inl = self.delims[opener].inl;
        let closer_inl = self.delims[closer].inl;
        self.delims[opener].length -= use_delims;
        self.delims[closer].length -= use_delims;
        if let NodeValue::Text(t) = &mut self.arena.get_mut(opener_inl).value {
            let n = t.len() - use_delims;
            t.truncate(n);
        }
        if let NodeValue::Text(t) = &mut self.arena.get_mut(closer_inl).value {
            let n = t.len() - use_delims;
            t.truncate(n);
        }
        let value = match opener_char {
            b'~' => NodeValue::Strikethrough,
            b'|' => NodeValue::Spoiler,
            b'_' if use_delims == 2 => NodeValue::Underline,
            _ => {
                if use_delims == 1 {
                    NodeValue::Emph
                } else {
                    NodeValue::Strong
                }
            }
        };
        let emph = self.make_inline(value);
        // move nodes between opener_inl and closer_inl into emph
        let mut tmp = self.arena.get(opener_inl).next;
        while let Some(t) = tmp {
            if t == closer_inl {
                break;
            }
            let next = self.arena.get(t).next;
            self.arena.append(emph, t);
            tmp = next;
        }
        self.arena.insert_after(opener_inl, emph);
        // remove delimiters between opener and closer
        let mut d = self.delims[closer].prev;
        while let Some(di) = d {
            if di == opener {
                break;
            }
            let prev = self.delims[di].prev;
            self.remove_delimiter(di);
            d = prev;
        }
        if self.delims[opener].length == 0 {
            self.arena.detach(opener_inl);
            self.remove_delimiter(opener);
        }
        if self.delims[closer].length == 0 {
            self.arena.detach(closer_inl);
            let next = self.delims[closer].next;
            self.remove_delimiter(closer);
            next
        } else {
            Some(closer)
        }
    }

    fn push_bracket(&mut self, image: bool, inl_text: usize) {
        let len = self.brackets.len();
        if len > 0 {
            self.brackets[len - 1].bracket_after = true;
        }
        self.brackets.push(Bracket { inl_text, position: self.pos, image, active: true, bracket_after: false, previous_delimiter: self.last_delim });
    }

    fn handle_close_bracket(&mut self) -> Option<usize> {
        self.pos += 1;
        let initial_pos = self.pos;
        let brackets_len = self.brackets.len();
        if brackets_len == 0 {
            return Some(self.make_inline(NodeValue::Text("]".to_string())));
        }
        if !self.brackets[brackets_len - 1].active {
            self.brackets.pop();
            return Some(self.make_inline(NodeValue::Text("]".to_string())));
        }
        let is_image = self.brackets[brackets_len - 1].image;
        let after_link_text_pos = self.pos;

        // footnote reference
        if !is_image {
            let opener_inl = self.brackets[brackets_len - 1].inl_text;
            let mut text = String::new();
            let mut all_text = true;
            let mut sib = self.arena.get(opener_inl).next;
            while let Some(s) = sib {
                match &self.arena.get(s).value {
                    NodeValue::Text(t) => text.push_str(t),
                    _ => {
                        all_text = false;
                        break;
                    }
                }
                sib = self.arena.get(s).next;
            }
            if all_text && text.len() > 1 && text.as_bytes()[0] == b'^' && !text[1..].contains(' ') {
                let name = text[1..].to_string();
                let inl = self.make_inline(NodeValue::FootnoteReference { name, ref_num: 0, ix: 0 });
                // remove text siblings after opener and the opener itself
                let mut sib = self.arena.get(opener_inl).next;
                while let Some(s) = sib {
                    let next = self.arena.get(s).next;
                    self.arena.detach(s);
                    sib = next;
                }
                self.arena.insert_after(opener_inl, inl);
                self.arena.detach(opener_inl);
                self.brackets.pop();
                return None;
            }
        }

        // inline link?
        let mut url = String::new();
        let mut title = String::new();
        let mut matched = false;
        if self.peek() == Some(b'(') {
            let sps = scan_spacechars(&self.input[self.pos + 1..]);
            if let Some(n) = manual_scan_link_url(&self.input[self.pos + 1 + sps..]) {
                let starturl = self.pos + 1 + sps;
                let endurl = starturl + n;
                let starttitle = endurl + scan_spacechars(&self.input[endurl..]);
                let endtitle = if starttitle == endurl { starttitle } else { starttitle + scan_link_title(&self.input[starttitle..]).unwrap_or(0) };
                let endall = endtitle + scan_spacechars(&self.input[endtitle..]);
                if self.peek_at(endall) == Some(b')') {
                    self.pos = endall + 1;
                    url = strings::clean_url(&String::from_utf8_lossy(&self.input[starturl..endurl]));
                    title = strings::clean_title(&String::from_utf8_lossy(&self.input[starttitle..endtitle]));
                    matched = true;
                } else {
                    self.pos = after_link_text_pos;
                }
            }
        }
        if !matched {
            // reference link
            let mut found_label = false;
            let mut raw_label = String::new();
            if let Some((n, label)) = link_label(&self.input[self.pos..]) {
                self.pos += n;
                raw_label = label;
                found_label = true;
            }
            if !found_label {
                // empty or missing second label; use text between brackets
                let start = self.brackets[brackets_len - 1].position;
                raw_label = String::from_utf8_lossy(&self.input[start..initial_pos - 1]).to_string();
                found_label = true;
            }
            if found_label {
                if let Some(r) = self.refmap.get(&strings::normalize_label(&raw_label)) {
                    url = r.url.clone();
                    title = r.title.clone();
                    matched = true;
                }
            }
        }
        if !matched {
            self.brackets.pop();
            self.pos = initial_pos;
            return Some(self.make_inline(NodeValue::Text("]".to_string())));
        }

        let inl = self.make_inline(if is_image { NodeValue::Image { url, title } } else { NodeValue::Link { url, title } });
        let opener_inl = self.brackets[brackets_len - 1].inl_text;
        self.arena.insert_before(opener_inl, inl);
        let mut tmp = self.arena.get(opener_inl).next;
        while let Some(t) = tmp {
            let next = self.arena.get(t).next;
            self.arena.append(inl, t);
            tmp = next;
        }
        self.arena.detach(opener_inl);
        let prev_delim = self.brackets[brackets_len - 1].previous_delimiter;
        self.process_emphasis(prev_delim);
        self.brackets.pop();
        if !is_image {
            for b in self.brackets.iter_mut() {
                if !b.image {
                    b.active = false;
                }
            }
        }
        None
    }

    fn handle_wikilink(&mut self) -> Option<usize> {
        // at "[["
        let start = self.pos;
        let mut i = self.pos + 2;
        let mut pipe: Option<usize> = None;
        let end;
        loop {
            if i + 1 >= self.input.len() {
                return None;
            }
            let c = self.input[i];
            if c == b']' && self.input[i + 1] == b']' {
                end = i;
                break;
            }
            if c == b'|' && pipe.is_none() {
                pipe = Some(i);
            }
            if c == b'\n' || c == b'\r' || c == b'[' {
                return None;
            }
            i += 1;
        }
        let (label_bytes, url_bytes) = match pipe {
            Some(p) => (&self.input[start + 2..p], &self.input[p + 1..end]),
            None => (&self.input[start + 2..end], &self.input[start + 2..end]),
        };
        if url_bytes.is_empty() && label_bytes.is_empty() {
            return None;
        }
        let url = strings::clean_url(&String::from_utf8_lossy(url_bytes));
        let label = String::from_utf8_lossy(label_bytes).to_string();
        self.pos = end + 2;
        let inl = self.make_inline(NodeValue::WikiLink { url });
        let t = self.make_inline(NodeValue::Text(label));
        self.arena.append(inl, t);
        Some(inl)
    }
}

pub fn consolidate_text(arena: &mut Arena, parent: usize) {
    let mut child = arena.get(parent).first_child;
    while let Some(c) = child {
        let next = arena.get(c).next;
        if let NodeValue::Text(_) = arena.get(c).value {
            // merge following text nodes
            let mut n = next;
            let mut merged = String::new();
            while let Some(nn) = n {
                if let NodeValue::Text(t) = &arena.get(nn).value {
                    merged.push_str(t);
                    let nx = arena.get(nn).next;
                    arena.detach(nn);
                    n = nx;
                } else {
                    break;
                }
            }
            if !merged.is_empty() {
                if let NodeValue::Text(t) = &mut arena.get_mut(c).value {
                    t.push_str(&merged);
                }
            }
            child = n;
        } else {
            consolidate_text(arena, c);
            child = next;
        }
    }
}

pub fn scan_spacechars(s: &[u8]) -> usize {
    let mut i = 0;
    while i < s.len() && strings::is_whitespace_byte(s[i]) {
        i += 1;
    }
    i
}

/// Scans a link URL (either <...> or a bare one with balanced parens). Returns length.
pub fn manual_scan_link_url(s: &[u8]) -> Option<usize> {
    let mut i = 0;
    if i < s.len() && s[i] == b'<' {
        i += 1;
        while i < s.len() {
            let c = s[i];
            if c == b'>' {
                return Some(i + 1);
            } else if c == b'\\' {
                i += 2;
            } else if c == b'\n' || c == b'\r' || c == b'<' {
                return None;
            } else {
                i += 1;
            }
        }
        None
    } else {
        manual_scan_link_url_2(s)
    }
}

fn manual_scan_link_url_2(s: &[u8]) -> Option<usize> {
    let mut i = 0;
    let mut nb_p = 0;
    while i < s.len() {
        let c = s[i];
        if c == b'\\' && i + 1 < s.len() && strings::is_ascii_punct(s[i + 1]) {
            i += 2;
        } else if c == b'(' {
            nb_p += 1;
            i += 1;
            if nb_p > 32 {
                return None;
            }
        } else if c == b')' {
            if nb_p == 0 {
                break;
            }
            nb_p -= 1;
            i += 1;
        } else if c.is_ascii_whitespace() || c < 0x20 {
            break;
        } else {
            i += 1;
        }
    }
    if i >= s.len() && !(i == 0) {
        // reached the end without closing; caller checks for ')'
        return Some(i);
    }
    if nb_p != 0 {
        return None;
    }
    Some(i)
}

/// Scans a link title. Returns length including quotes.
pub fn scan_link_title(s: &[u8]) -> Option<usize> {
    if s.is_empty() {
        return None;
    }
    let q = s[0];
    let close = match q {
        b'"' => b'"',
        b'\'' => b'\'',
        b'(' => b')',
        _ => return None,
    };
    let mut i = 1;
    while i < s.len() {
        let c = s[i];
        if c == b'\\' && i + 1 < s.len() && strings::is_ascii_punct(s[i + 1]) {
            i += 2;
            continue;
        }
        if c == close {
            return Some(i + 1);
        }
        if q == b'(' && c == b'(' {
            return None;
        }
        i += 1;
    }
    None
}

/// Parses a link label `[...]`. Returns (consumed, label contents).
pub fn link_label(s: &[u8]) -> Option<(usize, String)> {
    if s.is_empty() || s[0] != b'[' {
        return None;
    }
    let mut i = 1;
    let mut length = 0;
    while i < s.len() {
        let c = s[i];
        if c == b'[' {
            return None;
        }
        if c == b']' {
            break;
        }
        if c == b'\\' {
            i += 1;
            length += 1;
            if i < s.len() && strings::is_ascii_punct(s[i]) {
                i += 1;
                length += 1;
            }
            continue;
        }
        i += 1;
        length += 1;
        if length > 1000 {
            return None;
        }
    }
    if i < s.len() && s[i] == b']' {
        let label = String::from_utf8_lossy(&s[1..i]).to_string();
        // label must contain at least one non-whitespace char to be a "real" label
        if label.bytes().all(|b| strings::is_whitespace_byte(b)) {
            return None;
        }
        Some((i + 1, label))
    } else {
        None
    }
}

/// Parses a reference definition at the start of `s`. Returns (consumed, label, url, title).
pub fn parse_reference_inline(s: &str) -> Option<(usize, String, String, String)> {
    let b = s.as_bytes();
    let (n, label) = link_label(b)?;
    let mut pos = n;
    if pos >= b.len() || b[pos] != b':' {
        return None;
    }
    pos += 1;
    // spaces and up to one newline
    pos += scan_spacechars(&b[pos..]);
    let url_len = manual_scan_link_url(&b[pos..])?;
    if url_len == 0 {
        return None;
    }
    let url_raw = &s[pos..pos + url_len];
    pos += url_len;
    let beforetitle = pos;
    let sps = scan_spacechars(&b[pos..]);
    let mut title = String::new();
    let mut matched_title = false;
    if sps > 0 {
        let tpos = pos + sps;
        if let Some(tl) = scan_link_title(&b[tpos..]) {
            // title must be followed by end of line
            let after = tpos + tl;
            let mut k = after;
            while k < b.len() && (b[k] == b' ' || b[k] == b'\t') {
                k += 1;
            }
            if k >= b.len() || b[k] == b'\n' || b[k] == b'\r' {
                title = strings::clean_title(&s[tpos..after]);
                pos = after;
                matched_title = true;
            }
        }
    }
    if !matched_title {
        pos = beforetitle;
    }
    // parse final spaces and newline
    let mut k = pos;
    while k < b.len() && (b[k] == b' ' || b[k] == b'\t') {
        k += 1;
    }
    if k < b.len() && b[k] != b'\n' && b[k] != b'\r' {
        if matched_title {
            // garbage after title: try without title
            pos = beforetitle;
            k = pos;
            while k < b.len() && (b[k] == b' ' || b[k] == b'\t') {
                k += 1;
            }
            if k < b.len() && b[k] != b'\n' && b[k] != b'\r' {
                return None;
            }
            title = String::new();
        } else {
            return None;
        }
    }
    // consume newline
    if k < b.len() && b[k] == b'\r' {
        k += 1;
    }
    if k < b.len() && b[k] == b'\n' {
        k += 1;
    }
    let url = strings::clean_url(url_raw);
    Some((k, label, url, title))
}

fn scan_autolink_uri(s: &[u8]) -> Option<usize> {
    // scheme: [A-Za-z][A-Za-z0-9.+-]{1,31} ':' [^<>\x00-\x20]* '>'
    let mut i = 0;
    if i >= s.len() || !s[i].is_ascii_alphabetic() {
        return None;
    }
    i += 1;
    while i < s.len() && (s[i].is_ascii_alphanumeric() || s[i] == b'.' || s[i] == b'+' || s[i] == b'-') {
        i += 1;
    }
    if i < 2 || i > 32 {
        return None;
    }
    if i >= s.len() || s[i] != b':' {
        return None;
    }
    i += 1;
    while i < s.len() {
        let c = s[i];
        if c == b'>' {
            return Some(i + 1);
        }
        if c == b'<' || c <= 0x20 {
            return None;
        }
        i += 1;
    }
    None
}

fn scan_autolink_email(s: &[u8]) -> Option<usize> {
    // [a-zA-Z0-9.!#$%&'*+/=?^_`{|}~-]+ @ [a-zA-Z0-9](?:[a-zA-Z0-9-]{0,61}[a-zA-Z0-9])? (\.[a-zA-Z0-9](?:[a-zA-Z0-9-]{0,61}[a-zA-Z0-9])?)* >
    let mut i = 0;
    while i < s.len() && (s[i].is_ascii_alphanumeric() || b".!#$%&'*+/=?^_`{|}~-".contains(&s[i])) {
        i += 1;
    }
    if i == 0 || i >= s.len() || s[i] != b'@' {
        return None;
    }
    i += 1;
    loop {
        // label
        if i >= s.len() || !s[i].is_ascii_alphanumeric() {
            return None;
        }
        let start = i;
        i += 1;
        while i < s.len() && (s[i].is_ascii_alphanumeric() || s[i] == b'-') {
            i += 1;
        }
        if i - start > 63 || s[i - 1] == b'-' {
            return None;
        }
        if i < s.len() && s[i] == b'.' {
            i += 1;
            continue;
        }
        break;
    }
    if i < s.len() && s[i] == b'>' {
        Some(i + 1)
    } else {
        None
    }
}

/// Scans an inline HTML tag after '<'. Returns length (not counting the '<').
fn scan_html_tag(s: &[u8]) -> Option<usize> {
    if s.is_empty() {
        return None;
    }
    // comment
    if s.starts_with(b"!--") {
        // <!--> and <!---> are valid per spec 0.31; comment text until -->
        let mut i = 3;
        if s[i..].starts_with(b">") {
            return Some(i + 1);
        }
        if s[i..].starts_with(b"->") {
            return Some(i + 2);
        }
        while i + 2 < s.len() + 0 {
            if s[i] == b'-' && s[i + 1] == b'-' && i + 2 < s.len() && s[i + 2] == b'>' {
                return Some(i + 3);
            }
            if i + 2 >= s.len() {
                break;
            }
            i += 1;
        }
        return None;
    }
    // processing instruction
    if s.starts_with(b"?") {
        let mut i = 1;
        while i + 1 < s.len() {
            if s[i] == b'?' && s[i + 1] == b'>' {
                return Some(i + 2);
            }
            i += 1;
        }
        return None;
    }
    // declaration
    if s.len() >= 2 && s[0] == b'!' && s[1].is_ascii_alphabetic() {
        let mut i = 2;
        while i < s.len() {
            if s[i] == b'>' {
                return Some(i + 1);
            }
            i += 1;
        }
        return None;
    }
    // CDATA
    if s.starts_with(b"![CDATA[") {
        let mut i = 8;
        while i + 2 < s.len() {
            if s[i] == b']' && s[i + 1] == b']' && s[i + 2] == b'>' {
                return Some(i + 3);
            }
            i += 1;
        }
        return None;
    }
    if s[0] == b'/' {
        return scanners::scan_closing_tag(s);
    }
    scanners::scan_open_tag(s)
}
