//! Post-processing passes: footnotes, task lists, autolinks.

use super::node::*;
use super::strings;
use std::collections::HashMap;

pub fn process_footnotes(arena: &mut Arena, root: usize) {
    // collect definitions
    let mut defs: HashMap<String, usize> = HashMap::new();
    let mut def_order: Vec<usize> = Vec::new();
    for n in arena.descendants(root) {
        if let NodeValue::FootnoteDefinition { name, .. } = &arena.get(n).value {
            let key = strings::normalize_label(name);
            if !defs.contains_key(&key) {
                defs.insert(key, n);
                def_order.push(n);
            }
        }
    }
    // detach all definitions
    for &d in &def_order {
        arena.detach(d);
    }
    // find references in document order
    let mut ix_counter = 0usize;
    let mut used: Vec<usize> = Vec::new();
    let mut ix_map: HashMap<usize, usize> = HashMap::new();
    let mut ref_counts: HashMap<usize, usize> = HashMap::new();
    let nodes = arena.descendants(root);
    for n in nodes {
        let (name, is_ref) = match &arena.get(n).value {
            NodeValue::FootnoteReference { name, .. } => (name.clone(), true),
            _ => (String::new(), false),
        };
        if !is_ref {
            continue;
        }
        let key = strings::normalize_label(&name);
        match defs.get(&key) {
            Some(&d) => {
                let ix = *ix_map.entry(d).or_insert_with(|| {
                    ix_counter += 1;
                    used.push(d);
                    ix_counter
                });
                let cnt = ref_counts.entry(d).or_insert(0);
                *cnt += 1;
                let ref_num = *cnt;
                let def_name = match &arena.get(d).value {
                    NodeValue::FootnoteDefinition { name, .. } => name.clone(),
                    _ => name.clone(),
                };
                arena.get_mut(n).value = NodeValue::FootnoteReference { name: def_name, ref_num, ix };
            }
            None => {
                arena.get_mut(n).value = NodeValue::Text(format!("[^{}]", name));
            }
        }
    }
    // re-append used definitions in order
    for d in used {
        let total = *ref_counts.get(&d).unwrap_or(&0);
        if let NodeValue::FootnoteDefinition { total_references, .. } = &mut arena.get_mut(d).value {
            *total_references = total;
        }
        arena.append(root, d);
    }
}

pub fn process_tasklists(arena: &mut Arena, root: usize) {
    for n in arena.descendants(root) {
        if !matches!(arena.get(n).value, NodeValue::Item(..)) {
            continue;
        }
        let para = match arena.get(n).first_child {
            Some(p) if matches!(arena.get(p).value, NodeValue::Paragraph) => p,
            _ => continue,
        };
        let text_node = match arena.get(para).first_child {
            Some(t) => t,
            None => continue,
        };
        let (checked, symbol, rest) = {
            let t = match &arena.get(text_node).value {
                NodeValue::Text(t) => t,
                _ => continue,
            };
            let b = t.as_bytes();
            if b.len() < 3 || b[0] != b'[' || b[2] != b']' {
                continue;
            }
            let sym = b[1];
            if sym == b'[' || sym == b']' || sym.is_ascii_whitespace() && sym != b' ' {
                continue;
            }
            // require a space after ] unless at end of text with following node? comrak requires `] ` or end
            if b.len() == 3 {
                // "[x]" alone; only a task if followed by nothing (end of paragraph)
                (sym != b' ', sym, String::new())
            } else if b[3] == b' ' {
                (sym != b' ', sym, t[4..].to_string())
            } else {
                continue;
            }
        };
        if let NodeValue::Text(t) = &mut arena.get_mut(text_node).value {
            *t = rest;
        }
        arena.get_mut(n).value = NodeValue::TaskItem { checked, symbol };
    }
}

fn is_in_link(arena: &Arena, mut node: usize) -> bool {
    while let Some(p) = arena.get(node).parent {
        if matches!(arena.get(p).value, NodeValue::Link { .. } | NodeValue::WikiLink { .. }) {
            return true;
        }
        node = p;
    }
    false
}

pub fn process_autolinks(arena: &mut Arena, root: usize) {
    let mut stack = vec![root];
    while let Some(n) = stack.pop() {
        // children first collected since we may insert siblings
        let children = arena.children(n);
        for c in children.into_iter().rev() {
            stack.push(c);
        }
        if let NodeValue::Text(_) = arena.get(n).value {
            if is_in_link(arena, n) {
                continue;
            }
            autolink_text_node(arena, n);
        }
    }
}

fn autolink_text_node(arena: &mut Arena, node: usize) {
    let text = match &arena.get(node).value {
        NodeValue::Text(t) => t.clone(),
        _ => return,
    };
    let contents = text.as_bytes();
    let len = contents.len();
    let mut i = 0;
    while i < len {
        let m = match contents[i] {
            b':' => url_match(contents, i),
            b'w' | b'W' => www_match(contents, i),
            b'@' => email_match(contents, i),
            _ => None,
        };
        if let Some((url, rewind, link_end)) = m {
            let start = i - rewind;
            let end = i + link_end;
            let link_text = String::from_utf8_lossy(&contents[start..end]).to_string();
            let before = String::from_utf8_lossy(&contents[..start]).to_string();
            let after = String::from_utf8_lossy(&contents[end..]).to_string();
            arena.get_mut(node).value = NodeValue::Text(before);
            let link = arena.alloc(NodeValue::Link { url, title: String::new() }, 0);
            let t = arena.alloc(NodeValue::Text(link_text), 0);
            arena.append(link, t);
            arena.insert_after(node, link);
            if !after.is_empty() {
                let rest = arena.alloc(NodeValue::Text(after), 0);
                arena.insert_after(link, rest);
                autolink_text_node(arena, rest);
            }
            return;
        }
        i += 1;
    }
}

fn is_space(c: u8) -> bool {
    matches!(c, b' ' | b'\t' | b'\n' | b'\r' | 0x0b | 0x0c)
}

fn check_domain(data: &[u8], allow_short: bool) -> Option<usize> {
    let mut np = 0;
    let mut uscore1 = 0;
    let mut uscore2 = 0;
    let s = String::from_utf8_lossy(data);
    let mut end = data.len();
    let mut first = true;
    for (i, c) in s.char_indices() {
        if first {
            first = false;
            continue;
        }
        if c == '_' {
            uscore2 += 1;
        } else if c == '.' {
            uscore1 = uscore2;
            uscore2 = 0;
            np += 1;
        } else if !(!c.is_whitespace() && !strings::is_punctuation(c)) && c != '-' {
            end = i;
            break;
        }
    }
    if uscore1 > 0 || uscore2 > 0 {
        return None;
    }
    if allow_short {
        Some(end)
    } else if np > 0 {
        Some(end)
    } else {
        None
    }
}

fn autolink_delim(data: &[u8], mut link_end: usize) -> usize {
    for (i, &b) in data.iter().enumerate().take(link_end) {
        if b == b'<' {
            link_end = i;
            break;
        }
    }
    while link_end > 0 {
        let cclose = data[link_end - 1];
        let copen = if cclose == b')' { Some(b'(') } else { None };
        if b"?!.,:*_~'\"".contains(&cclose) {
            link_end -= 1;
        } else if cclose == b';' {
            let mut new_end = link_end - 2;
            while new_end > 0 && data[new_end].is_ascii_alphabetic() {
                new_end -= 1;
            }
            if new_end < link_end - 2 && data[new_end] == b'&' {
                link_end = new_end;
            } else {
                link_end -= 1;
            }
        } else if let Some(copen) = copen {
            let mut closing = 0;
            let mut opening = 0;
            for &b in &data[..link_end] {
                if b == copen {
                    opening += 1;
                } else if b == cclose {
                    closing += 1;
                }
            }
            if closing <= opening {
                break;
            }
            link_end -= 1;
        } else {
            break;
        }
    }
    link_end
}

/// Returns (url, rewind, link_end)
fn url_match(contents: &[u8], i: usize) -> Option<(String, usize, usize)> {
    const SCHEMES: [&[u8]; 3] = [b"http", b"https", b"ftp"];
    let size = contents.len();
    if size - i < 4 || contents[i + 1] != b'/' || contents[i + 2] != b'/' {
        return None;
    }
    let mut rewind = 0;
    while rewind < i && contents[i - rewind - 1].is_ascii_alphabetic() {
        rewind += 1;
    }
    if !SCHEMES.iter().any(|s| &contents[i - rewind..i] == *s) {
        return None;
    }
    let domain_len = check_domain(&contents[i + 3..], true)?;
    let mut link_end = 3 + domain_len;
    while link_end < size - i && !is_space(contents[i + link_end]) && contents[i + link_end] != b'<' {
        link_end += 1;
    }
    link_end = autolink_delim(&contents[i..], link_end);
    if link_end == 0 {
        return None;
    }
    let url = String::from_utf8_lossy(&contents[i - rewind..i + link_end]).to_string();
    Some((url, rewind, link_end))
}

fn www_match(contents: &[u8], i: usize) -> Option<(String, usize, usize)> {
    if i > 0 {
        let p = contents[i - 1];
        if !is_space(p) && !matches!(p, b'*' | b'_' | b'~' | b'(' | b'[') {
            return None;
        }
    }
    if !contents[i..].starts_with(b"www.") {
        return None;
    }
    let mut link_end = check_domain(&contents[i..], false)?;
    while link_end < contents.len() - i && !is_space(contents[i + link_end]) {
        link_end += 1;
    }
    link_end = autolink_delim(&contents[i..], link_end);
    if link_end == 0 {
        return None;
    }
    let text = String::from_utf8_lossy(&contents[i..i + link_end]).to_string();
    Some((format!("http://{}", text), 0, link_end))
}

fn validate_protocol(protocol: &[u8], contents: &[u8], cursor: usize) -> bool {
    // contents[cursor] is ':'
    if cursor < protocol.len() {
        return false;
    }
    let start = cursor - protocol.len();
    if &contents[start..cursor] != protocol {
        return false;
    }
    if start == 0 {
        return true;
    }
    !contents[start - 1].is_ascii_alphanumeric()
}

fn email_match(contents: &[u8], i: usize) -> Option<(String, usize, usize)> {
    let size = contents.len();
    let mut auto_mailto = true;
    let mut is_xmpp = false;
    let mut rewind = 0;
    while rewind < i {
        let c = contents[i - rewind - 1];
        if c.is_ascii_alphanumeric() || b".+-_".contains(&c) {
            rewind += 1;
            continue;
        }
        if c == b':' {
            if validate_protocol(b"mailto", contents, i - rewind - 1) {
                auto_mailto = false;
                rewind += 1;
                continue;
            }
            if validate_protocol(b"xmpp", contents, i - rewind - 1) {
                auto_mailto = false;
                is_xmpp = true;
                rewind += 1;
                continue;
            }
        }
        break;
    }
    if rewind == 0 {
        return None;
    }
    let mut link_end = 1;
    let mut np = 0;
    while link_end < size - i {
        let c = contents[i + link_end];
        if c.is_ascii_alphanumeric() {
        } else if c == b'@' {
            return None;
        } else if c == b'.' && link_end < size - i - 1 && contents[i + link_end + 1].is_ascii_alphanumeric() {
            np += 1;
        } else if c == b'/' && is_xmpp {
        } else if c != b'-' && c != b'_' {
            break;
        }
        link_end += 1;
    }
    if link_end < 2 || np == 0 || (!contents[i + link_end - 1].is_ascii_alphanumeric() && contents[i + link_end - 1] != b'.') {
        return None;
    }
    link_end = autolink_delim(&contents[i..], link_end);
    if link_end == 0 {
        return None;
    }
    let mut url = if auto_mailto { "mailto:".to_string() } else { String::new() };
    url.push_str(&String::from_utf8_lossy(&contents[i - rewind..i + link_end]));
    Some((url, rewind, link_end))
}
