    if cursor < protocol.len() {
        return false;
    }
    let start = cursor - protocol.len();
    if &contents[start..cursor] != protocol {
        return false;
    }
    if start == 0 {
        return true;
    }
    !contents[start - 1].is_ascii_alphanumeric()
}

fn email_match(contents: &[u8], i: usize) -> Option<(String, usize, usize)> {
    let size = contents.len();
    let mut auto_mailto = true;
    let mut is_xmpp = false;
    let mut rewind = 0;
    while rewind < i {
        let c = contents[i - rewind - 1];
        if c.is_ascii_alphanumeric() || b".+-_".contains(&c) {
            rewind += 1;
            continue;
        }
        if c == b':' {
            if validate_protocol(b"mailto", contents, i - rewind - 1) {
                auto_mailto = false;
                rewind += 1;
                continue;
            }
            if validate_protocol(b"xmpp", contents, i - rewind - 1) {
                auto_mailto = false;
                is_xmpp = true;
                rewind += 1;
                continue;
            }
        }
        break;
    }
    if rewind == 0 {
        return None;
    }
    let mut link_end = 1;
    let mut np = 0;
    while link_end < size - i {
        let c = contents[i + link_end];
        if c.is_ascii_alphanumeric() {
        } else if c == b'@' {
            return None;
        } else if c == b'.' && link_end < size - i - 1 && contents[i + link_end + 1].is_ascii_alphanumeric() {
            np += 1;
        } else if c == b'/' && is_xmpp {
        } else if c != b'-' && c != b'_' {
            break;
        }
        link_end += 1;
    }
    if link_end < 2 || np == 0 || (!contents[i + link_end - 1].is_ascii_alphanumeric() && contents[i + link_end - 1] != b'.') {
        return None;
    }
    link_end = autolink_delim(&contents[i..], link_end);
    if link_end == 0 {
        return None;
    }
    let mut url = if auto_mailto { "mailto:".to_string() } else { String::new() };
    url.push_str(&String::from_utf8_lossy(&contents[i - rewind..i + link_end]));
    Some((url, rewind, link_end))
}
