}

impl Anchorizer {
    pub fn new() -> Self {
        Anchorizer { seen: HashMap::new() }
    }
    pub fn anchorize(&mut self, header: &str) -> String {
        let mut id = header.to_lowercase();
        id = id
            .chars()
            .filter(|c| c.is_alphanumeric() || *c == ' ' || *c == '-' || *c == '_' || is_mark(*c) || is_connector_punct(*c))
            .collect();
        id = id.replace(' ', "-");
        let count = self.seen.entry(id.clone()).or_insert(0);
        let result = if *count == 0 { id.clone() } else { format!("{}-{}", id, count) };
        *count += 1;
        result
    }
}

fn is_mark(c: char) -> bool {
    let cp = c as u32;
    matches!(cp, 0x0300..=0x036F | 0x1AB0..=0x1AFF | 0x1DC0..=0x1DFF | 0x20D0..=0x20FF | 0xFE20..=0xFE2F)
}

fn is_connector_punct(c: char) -> bool {
    matches!(c, '_' | '\u{203F}' | '\u{2040}' | '\u{2054}' | '\u{FE33}' | '\u{FE34}' | '\u{FE4D}' | '\u{FE4E}' | '\u{FE4F}' | '\u{FF3F}')
}

pub struct HtmlFormatter<'a> {
    arena: &'a Arena,
    pub output: String,
    anchorizer: Anchorizer,
    footnote_ix: usize,
    written_footnote_ix: usize,
    plain_depth: usize,
}

pub fn collect_text(arena: &Arena, node: usize, out: &mut String) {
    match &arena.get(node).value {
        NodeValue::Text(t) | NodeValue::Code(t) | NodeValue::ShortCode(t) => out.push_str(t),
        NodeValue::LineBreak | NodeValue::SoftBreak => out.push(' '),
        _ => {
            let mut c = arena.get(node).first_child;
            while let Some(ch) = c {
                collect_text(arena, ch, out);
                c = arena.get(ch).next;
            }
        }
    }
}

impl<'a> HtmlFormatter<'a> {
    pub fn new(arena: &'a Arena) -> Self {
        HtmlFormatter { arena, output: String::new(), anchorizer: Anchorizer::new(), footnote_ix: 0, written_footnote_ix: 0, plain_depth: 0 }
    }

    fn cr(&mut self) {
        if !self.output.is_empty() && !self.output.ends_with('\n') {
            self.output.push('\n');
        }
    }

    pub fn format(&mut self, node: usize) {
        // iterative traversal with enter/exit
        enum Step {
            Enter(usize),
            Exit(usize),
        }
        let mut stack = vec![Step::Enter(node)];
        while let Some(step) = stack.pop() {
            match step {
                Step::Enter(n) => {
                    let descend = self.format_node(n, true);
                    stack.push(Step::Exit(n));
                    if descend {
                        let children = self.arena.children(n);
                        for c in children.into_iter().rev() {
                            stack.push(Step::Enter(c));
                        }
                    }
                }
                Step::Exit(n) => {
                    self.format_node(n, false);
                }
            }
        }
    }

    fn tight_paragraph(&self, node: usize) -> bool {
        let parent = self.arena.get(node).parent;
        let tight = match parent.map(|p| &self.arena.get(p).value) {
            Some(NodeValue::List(nl)) => nl.tight,
            Some(NodeValue::DescriptionTerm) => true,
            _ => false,
        };
        let grand = parent.and_then(|p| self.arena.get(p).parent);
        tight
            || match grand.map(|g| &self.arena.get(g).value) {
                Some(NodeValue::List(nl)) => nl.tight,
                Some(NodeValue::DescriptionItem { tight }) => *tight,
                _ => false,
            }
    }

    fn put_footnote_backref(&mut self, node: usize) -> bool {
        if self.written_footnote_ix >= self.footnote_ix {
            return false;
        }
        self.written_footnote_ix = self.footnote_ix;
        let (name, total) = match &self.arena.get(node).value {
            NodeValue::FootnoteDefinition { name, total_references } => (name.clone(), *total_references),
            _ => return false,
        };
        let mut ref_suffix = String::new();
        let mut superscript = String::new();
        for ref_num in 1..=total.max(1) {
            if ref_num > 1 {
                ref_suffix = format!("-{}", ref_num);
                superscript = format!("<sup class=\"footnote-ref\">{}</sup>", ref_num);
                self.output.push(' ');
            }
            self.output.push_str(&format!(
                "<a href=\"#fnref-{}{}\" class=\"footnote-backref\" data-footnote-backref data-footnote-backref-idx=\"{}{}\" aria-label=\"Back to reference {}{}\">↩{}</a>",
                name, ref_suffix, self.footnote_ix, ref_suffix, self.footnote_ix, ref_suffix, superscript
            ));
        }
        true
    }

    /// Returns whether to descend into children.
    fn format_node(&mut self, node: usize, entering: bool) -> bool {
        let n = self.arena.get(node);
        if self.plain_depth > 0 {
            // plain text mode (image alt)
            if entering {
                match &n.value {
                    NodeValue::Text(t) | NodeValue::Code(t) | NodeValue::ShortCode(t) => escape(&mut self.output, t),
                    NodeValue::LineBreak | NodeValue::SoftBreak => self.output.push(' '),
                    NodeValue::Image { .. } => {
                        self.plain_depth += 1;
                    }
                    _ => {}
                }
            } else if let NodeValue::Image { .. } = &n.value {
                self.plain_depth -= 1;
            }
            return true;
        }
        match &n.value {
            NodeValue::Document => {
                if !entering && self.footnote_ix > 0 {
                    self.output.push_str("</ol>\n</section>\n");
                }
            }
            NodeValue::BlockQuote | NodeValue::MultilineBlockQuote { .. } => {
                self.cr();
                if entering {
                    self.output.push_str("<blockquote>\n");
                } else {
                    self.output.push_str("</blockquote>\n");
                }
            }
            NodeValue::Alert { alert_type, title, .. } => {
                if entering {
                    self.cr();
                    self.output.push_str(&format!("<div class=\"markdown-alert markdown-alert-{}\">\n", alert_type.css_class()));
                    self.output.push_str("<p class=\"markdown-alert-title\">");
                    match title {
                        Some(t) => escape(&mut self.output, t),
                        None => self.output.push_str(alert_type.default_title()),
                    }
                    self.output.push_str("</p>\n");
                } else {
                    self.cr();
                    self.output.push_str("</div>\n");
                }
            }
            NodeValue::List(nl) => {
                if entering {
                    self.cr();
                    if nl.list_type == ListType::Bullet {
                        self.output.push_str("<ul>\n");
                    } else if nl.start == 1 {
                        self.output.push_str("<ol>\n");
                    } else {
                        self.output.push_str(&format!("<ol start=\"{}\">\n", nl.start));
                    }
                } else if nl.list_type == ListType::Bullet {
                    self.output.push_str("</ul>\n");
                } else {
                    self.output.push_str("</ol>\n");
                }
            }
            NodeValue::Item(..) => {
                if entering {
                    self.cr();
                    self.output.push_str("<li>");
                } else {
                    self.output.push_str("</li>\n");
                }
            }
            NodeValue::TaskItem { checked, .. } => {
                if entering {
                    self.cr();
                    self.output.push_str("<li>");
                    self.output.push_str("<input type=\"checkbox\" ");
                    if *checked {
                        self.output.push_str("checked=\"\" ");
                    }
                    self.output.push_str("disabled=\"\" /> ");
                } else {
                    self.output.push_str("</li>\n");
                }
            }
            NodeValue::DescriptionList => {
                if entering {
                    self.cr();
                    self.output.push_str("<dl>\n");
                } else {
                    self.output.push_str("</dl>\n");
                }
            }
            NodeValue::DescriptionItem { .. } => {}
            NodeValue::DescriptionTerm => {
                if entering {
                    self.cr();
                    self.output.push_str("<dt>");
                } else {
                    self.output.push_str("</dt>\n");
                }
            }
            NodeValue::DescriptionDetails => {
                if entering {
                    self.cr();
                    self.output.push_str("<dd>");
                } else {
                    self.output.push_str("</dd>\n");
                }
            }
            NodeValue::Heading { level, .. } => {
                if entering {
                    self.cr();
                    self.output.push_str(&format!("<h{}>", level));
                    let mut text = String::new();
                    collect_text(self.arena, node, &mut text);
                    let id = self.anchorizer.anchorize(&text);
                    self.output.push_str(&format!("<a href=\"#{}\" aria-hidden=\"true\" class=\"anchor\" id=\"{}\"></a>", id, id));
                } else {
                    self.output.push_str(&format!("</h{}>\n", level));
                }
            }
            NodeValue::CodeBlock { info, literal, .. } => {
                if entering {
                    self.cr();
                    self.output.push_str("<pre><code");
                    if !info.is_empty() {
                        let first = info.split(|c: char| c == ' ' || c == '\t').next().unwrap_or("");
                        if !first.is_empty() {
                            self.output.push_str(" class=\"language-");
                            escape(&mut self.output, first);
                            self.output.push('"');
                        }
                    }
                    self.output.push('>');
                    escape(&mut self.output, literal);
                    self.output.push_str("</code></pre>\n");
                }
            }
            NodeValue::HtmlBlock { literal, .. } => {
                if entering {
                    self.cr();
                    self.output.push_str(literal);
                    self.cr();
                }
            }
            NodeValue::ThematicBreak => {
                if entering {
                    self.cr();
                    self.output.push_str("<hr />\n");
                }
            }
            NodeValue::Paragraph => {
                let tight = self.tight_paragraph(node);
                if !tight {
                    if entering {
                        self.cr();
                        self.output.push_str("<p>");
                    } else {
                        let parent = n.parent;
                        let is_last_in_footnote = match parent.map(|p| &self.arena.get(p).value) {
                            Some(NodeValue::FootnoteDefinition { .. }) => n.next.is_none(),
                            _ => false,
                        };
                        if is_last_in_footnote {
                            self.output.push(' ');
                            self.put_footnote_backref(parent.unwrap());
                        }
                        self.output.push_str("</p>\n");
                    }
                }
            }
            NodeValue::Text(t) => {
                if entering {
                    escape(&mut self.output, t);
                }
            }
            NodeValue::ShortCode(e) => {
                if entering {
                    self.output.push_str(e);
                }
            }
            NodeValue::LineBreak => {
                if entering {
                    self.output.push_str("<br />\n");
                }
            }
            NodeValue::SoftBreak => {
                if entering {
                    self.output.push('\n');
                }
            }
            NodeValue::Code(t) => {
                if entering {
                    self.output.push_str("<code>");
                    escape(&mut self.output, t);
                    self.output.push_str("</code>");
                }
            }
            NodeValue::HtmlInline(t) => {
                if entering {
                    self.output.push_str(t);
                }
            }
            NodeValue::Strong => self.output.push_str(if entering { "<strong>" } else { "</strong>" }),
            NodeValue::Emph => self.output.push_str(if entering { "<em>" } else { "</em>" }),
            NodeValue::Strikethrough => self.output.push_str(if entering { "<del>" } else { "</del>" }),
            NodeValue::Underline => self.output.push_str(if entering { "<u>" } else { "</u>" }),
            NodeValue::Spoiler => self.output.push_str(if entering { "<span class=\"spoiler\">" } else { "</span>" }),
            NodeValue::Link { url, title } => {
                if entering {
                    self.output.push_str("<a href=\"");
                    escape_href(&mut self.output, url);
                    if !title.is_empty() {
                        self.output.push_str("\" title=\"");
                        escape(&mut self.output, title);
                    }
                    self.output.push_str("\">");
                } else {
                    self.output.push_str("</a>");
                }
            }
            NodeValue::WikiLink { url } => {
                if entering {
                    self.output.push_str("<a href=\"");
                    escape_href(&mut self.output, url);
                    self.output.push_str("\" data-wikilink=\"true\">");
                } else {
                    self.output.push_str("</a>");
                }
            }
            NodeValue::Image { url, title } => {
                if entering {
                    self.output.push_str("<figure>");
                    self.output.push_str("<img src=\"");
                    escape_href(&mut self.output, url);
                    self.output.push_str("\" alt=\"");
                    self.plain_depth = 1;
                    return true;
                } else {
                    self.plain_depth = 0;
                    if !title.is_empty() {
                        self.output.push_str("\" title=\"");
                        escape(&mut self.output, title);
                    }
                    self.output.push_str("\" />");
                    if !title.is_empty() {
                        self.output.push_str("<figcaption>");
                        escape(&mut self.output, title);
                        self.output.push_str("</figcaption>");
                    }
                    self.output.push_str("</figure>");
                }
            }
            NodeValue::Table { .. } => {
                if entering {
                    self.cr();
                    self.output.push_str("<table>\n");
                } else {
                    if n.first_child != n.last_child {
                        self.cr();
                        self.output.push_str("</tbody>\n");
                    }
                    self.cr();
                    self.output.push_str("</table>\n");
                }
            }
            NodeValue::TableRow { header } => {
                if entering {
                    self.cr();
                    if *header {
                        self.output.push_str("<thead>\n");
                    } else if let Some(prev) = n.prev {
                        if let NodeValue::TableRow { header: true } = self.arena.get(prev).value {
                            self.output.push_str("<tbody>\n");
                        }
                    }
                    self.output.push_str("<tr>");
                } else {
                    self.cr();
                    self.output.push_str("</tr>");
                    if *header {
                        self.cr();
                        self.output.push_str("</thead>");
                    }
                }
            }
            NodeValue::TableCell => {
                let row = n.parent.unwrap();
                let in_header = matches!(self.arena.get(row).value, NodeValue::TableRow { header: true });
                let table = self.arena.get(row).parent.unwrap();
                let alignments = match &self.arena.get(table).value {
                    NodeValue::Table { alignments, .. } => alignments.clone(),
                    _ => Vec::new(),
                };
                if entering {
                    self.cr();
                    self.output.push_str(if in_header { "<th" } else { "<td" });
                    let mut i = 0;
                    let mut c = self.arena.get(row).first_child;
                    while let Some(cc) = c {
                        if cc == node {
                            break;
                        }
                        i += 1;
                        c = self.arena.get(cc).next;
                    }
                    match alignments.get(i) {
                        Some(TableAlignment::Left) => self.output.push_str(" align=\"left\""),
                        Some(TableAlignment::Right) => self.output.push_str(" align=\"right\""),
                        Some(TableAlignment::Center) => self.output.push_str(" align=\"center\""),
                        _ => {}
                    }
                    self.output.push('>');
                } else {
                    self.output.push_str(if in_header { "</th>" } else { "</td>" });
                }
            }
            NodeValue::FootnoteDefinition { name, .. } => {
                if entering {
                    if self.footnote_ix == 0 {
                        self.output.push_str("<section class=\"footnotes\" data-footnotes>\n<ol>\n");
                    }
                    self.footnote_ix += 1;
                    self.output.push_str(&format!("<li id=\"fn-{}\">\n", name));
                } else {
                    if self.put_footnote_backref(node) {
                        self.output.push('\n');
                    }
                    self.output.push_str("</li>\n");
                }
            }
            NodeValue::FootnoteReference { name, ref_num, ix } => {
                if entering {
                    let mut ref_id = format!("fnref-{}", name);
                    if *ref_num > 1 {
                        ref_id = format!("{}-{}", ref_id, ref_num);
                    }
                    self.output.push_str(&format!(
                        "<sup class=\"footnote-ref\"><a href=\"#fn-{}\" id=\"{}\" data-footnote-ref>{}</a></sup>",
                        name, ref_id, ix
                    ));
                }
            }
        }
        true
    }
}
