//! A CommonMark + GFM markdown parser producing comrak-compatible HTML.

pub mod block;
pub mod emoji;
pub mod entities;
pub mod html;
pub mod inline;
pub mod node;
pub mod postprocess;
pub mod scanners;
pub mod strings;
pub mod table;

use node::*;

pub struct Parsed {
    pub arena: Arena,
    pub root: usize,
}

pub fn parse(text: &str) -> Parsed {
    let mut parser = block::Parser::new();
    parser.feed(text);
    parser.finish();
    let block::Parser { mut arena, root, refmap, .. } = parser;
    // inline parsing of leaf blocks
    let nodes = arena.descendants(root);
    for n in nodes {
        let needs_inlines = matches!(arena.get(n).value, NodeValue::Paragraph | NodeValue::Heading { .. } | NodeValue::TableCell);
        if needs_inlines {
            let mut content = std::mem::take(&mut arena.get_mut(n).content);
            strings::rtrim(&mut content);
            let bytes = content.into_bytes();
            let mut ip = inline::InlineParser::new(&bytes, &mut arena, &refmap);
            ip.parse_inlines(n);
        }
    }
    postprocess::process_tasklists(&mut arena, root);
    postprocess::process_footnotes(&mut arena, root);
    postprocess::process_autolinks(&mut arena, root);
    Parsed { arena, root }
}

pub fn to_html(text: &str) -> String {
    let parsed = parse(text);
    let mut f = html::HtmlFormatter::new(&parsed.arena);
    f.format(parsed.root);
    f.output
}
