//! Template parser.

use super::ast::*;
use std::collections::HashMap;

#[derive(Debug)]
pub struct ParseError(pub String);

#[derive(Debug, Clone)]
enum Tok {
    Text(String),
    Expr(String, bool, bool),    // content, trim_left, trim_right
    Tag(String, bool, bool),
    Comment(bool, bool),
}

fn tokenize(src: &str) -> Result<Vec<Tok>, ParseError> {
    let mut toks = Vec::new();
    let b = src.as_bytes();
    let mut i = 0;
    let mut text_start = 0;
    while i < b.len() {
        if b[i] == b'{' && i + 1 < b.len() && (b[i + 1] == b'{' || b[i + 1] == b'%' || b[i + 1] == b'#') {
            let kind = b[i + 1];
            if text_start < i {
                toks.push(Tok::Text(src[text_start..i].to_string()));
            }
            let mut j = i + 2;
            let trim_left = j < b.len() && b[j] == b'-';
            if trim_left {
                j += 1;
            }
            // raw block special case handled by parser; find closing
            let close: &[u8] = match kind {
                b'{' => b"}}",
                b'%' => b"%}",
                _ => b"#}",
            };
            let start = j;
            let mut end = None;
            if kind == b'#' {
                // comments: find #} (allow nested? no)
                let mut k = j;
                while k + 1 < b.len() {
                    if b[k] == b'#' && b[k + 1] == b'}' {
                        end = Some(k);
                        break;
                    }
                    k += 1;
                }
            } else {
                let mut k = j;
                let mut in_str: Option<u8> = None;
                while k + 1 < b.len() {
                    let c = b[k];
                    if let Some(q) = in_str {
                        if c == b'\\' {
                            k += 2;
                            continue;
                        }
                        if c == q {
                            in_str = None;
                        }
                        k += 1;
                        continue;
                    }
                    if c == b'"' || c == b'\'' || c == b'`' {
                        in_str = Some(c);
                        k += 1;
                        continue;
                    }
                    if c == close[0] && b[k + 1] == close[1] {
                        end = Some(k);
                        break;
                    }
                    k += 1;
                }
            }
            let end = match end {
                Some(e) => e,
                None => return Err(ParseError(format!("Unterminated tag starting at byte {}", i))),
            };
            let mut content_end = end;
            let trim_right = content_end > start && b[content_end - 1] == b'-';
            if trim_right {
                content_end -= 1;
            }
            let content = src[start..content_end].to_string();
            match kind {
                b'{' => toks.push(Tok::Expr(content, trim_left, trim_right)),
                b'%' => toks.push(Tok::Tag(content, trim_left, trim_right)),
                _ => toks.push(Tok::Comment(trim_left, trim_right)),
            }
            i = end + 2;
            text_start = i;
        } else {
            i += 1;
        }
    }
    if text_start < b.len() {
        toks.push(Tok::Text(src[text_start..].to_string()));
    }
    // apply whitespace trimming
    let mut out: Vec<Tok> = Vec::new();
    for t in toks.into_iter() {
        match &t {
            Tok::Expr(_, tl, _) | Tok::Tag(_, tl, _) | Tok::Comment(tl, _) if *tl => {
                if let Some(Tok::Text(prev)) = out.last_mut() {
                    let trimmed = prev.trim_end().to_string();
                    *prev = trimmed;
                }
            }
            _ => {}
        }
        let trim_right = match &t {
            Tok::Expr(_, _, tr) | Tok::Tag(_, _, tr) | Tok::Comment(_, tr) => *tr,
            _ => false,
        };
        out.push(t);
        if trim_right {
            // mark: next text should be trimmed at start; we handle by pushing a marker
            out.push(Tok::Text(String::from("\u{0}TRIM")));
        }
    }
    // resolve TRIM markers
    let mut res: Vec<Tok> = Vec::new();
    let mut trim_next = false;
    for t in out.into_iter() {
        match t {
            Tok::Text(s) if s == "\u{0}TRIM" => {
                trim_next = true;
            }
            Tok::Text(s) => {
                let s = if trim_next { s.trim_start().to_string() } else { s };
                trim_next = false;
                if !s.is_empty() {
                    res.push(Tok::Text(s));
                }
            }
            other => {
                trim_next = false;
                res.push(other);
            }
        }
    }
    Ok(res)
}

pub fn parse_template(name: &str, src: &str) -> Result<Template, ParseError> {
    let toks = tokenize(src)?;
    let mut p = Parser { toks, pos: 0, blocks: HashMap::new(), macros: HashMap::new(), parent: None, imports: Vec::new() };
    let nodes = p.parse_nodes(&[])?;
    Ok(Template { name: name.to_string(), source: src.to_string(), nodes, parent: p.parent, blocks: p.blocks, macros: p.macros, imports: p.imports })
}

struct Parser {
    toks: Vec<Tok>,
    pos: usize,
    blocks: HashMap<String, Vec<Node>>,
    macros: HashMap<String, (Vec<(String, Option<Expr>)>, Vec<Node>)>,
    parent: Option<String>,
    imports: Vec<(String, String)>,
}

fn tag_name(content: &str) -> (&str, &str) {
    let c = content.trim();
    let end = c.find(|ch: char| ch.is_whitespace()).unwrap_or(c.len());
    (&c[..end], c[end..].trim())
}

impl Parser {
    /// Parse nodes until one of the `end_tags` is found (not consumed). Returns nodes.
    fn parse_nodes(&mut self, end_tags: &[&str]) -> Result<Vec<Node>, ParseError> {
        let mut nodes = Vec::new();
        while self.pos < self.toks.len() {
            let tok = self.toks[self.pos].clone();
            match tok {
                Tok::Text(s) => {
                    nodes.push(Node::Text(s));
                    self.pos += 1;
                }
                Tok::Comment(..) => {
                    self.pos += 1;
                }
                Tok::Expr(content, ..) => {
                    let e = parse_expression(&content)?;
                    nodes.push(Node::Expr(e));
                    self.pos += 1;
                }
                Tok::Tag(content, ..) => {
                    let (name, rest) = tag_name(&content);
                    if end_tags.contains(&name) {
                        return Ok(nodes);
                    }
                    self.pos += 1;
                    match name {
                        "extends" => {
                            let f = parse_string_literal(rest)?;
                            self.parent = Some(f);
                        }
                        "set" | "set_global" => {
                            let (k, v) = split_once_trim(rest, '=').ok_or_else(|| ParseError(format!("Invalid set tag: {}", content)))?;
                            nodes.push(Node::Set { key: k.to_string(), value: parse_expression(v)?, global: name == "set_global" });
                        }
                        "if" | "elif" if name == "if" => {
                            let mut conds = Vec::new();
                            let mut cond_expr = parse_expression(rest)?;
                            loop {
                                let body = self.parse_nodes(&["elif", "else", "endif"])?;
                                conds.push((cond_expr.clone(), body));
                                let t = self.toks.get(self.pos).cloned().ok_or_else(|| ParseError("Unclosed if".into()))?;
                                self.pos += 1;
                                if let Tok::Tag(c, ..) = t {
                                    let (n, r) = tag_name(&c);
                                    match n {
                                        "elif" => {
                                            cond_expr = parse_expression(r)?;
                                            continue;
                                        }
                                        "else" => {
                                            let else_body = self.parse_nodes(&["endif"])?;
                                            self.pos += 1;
                                            nodes.push(Node::If { conds, else_body: Some(else_body) });
                                            break;
                                        }
                                        _ => {
                                            nodes.push(Node::If { conds, else_body: None });
                                            break;
                                        }
                                    }
                                }
                            }
                        }
                        "for" => {
                            let (vars, container) = split_once_word(rest, "in").ok_or_else(|| ParseError(format!("Invalid for tag: {}", content)))?;
                            let (key, value) = match vars.split_once(',') {
                                Some((k, v)) => (Some(k.trim().to_string()), v.trim().to_string()),
                                None => (None, vars.trim().to_string()),
                            };
                            let container = parse_expression(container)?;
                            let body = self.parse_nodes(&["else", "endfor"])?;
                            let t = self.toks.get(self.pos).cloned().ok_or_else(|| ParseError("Unclosed for".into()))?;
                            self.pos += 1;
                            let mut empty_body = None;
                            if let Tok::Tag(c, ..) = t {
                                let (n, _) = tag_name(&c);
                                if n == "else" {
                                    empty_body = Some(self.parse_nodes(&["endfor"])?);
                                    self.pos += 1;
                                }
                            }
                            nodes.push(Node::For { key, value, container, body, empty_body });
                        }
                        "block" => {
                            let bname = rest.trim().to_string();
                            let body = self.parse_nodes(&["endblock"])?;
                            self.pos += 1;
                            self.blocks.insert(bname.clone(), body.clone());
                            nodes.push(Node::Block { name: bname, body });
                        }
                        "include" => {
                            let mut r = rest.trim();
                            let mut ignore_missing = false;
                            if r.ends_with("ignore missing") {
                                ignore_missing = true;
                                r = r[..r.len() - "ignore missing".len()].trim();
                            }
                            let files = if r.starts_with('[') {
                                match parse_expression(r)? {
                                    Expr::Array(items) => items
                                        .into_iter()
                                        .map(|e| match e {
                                            Expr::Str(s) => Ok(s),
                                            _ => Err(ParseError("include expects strings".into())),
                                        })
                                        .collect::<Result<Vec<_>, _>>()?,
                                    _ => return Err(ParseError("include expects array".into())),
                                }
                            } else {
                                vec![parse_string_literal(r)?]
                            };
                            nodes.push(Node::Include { files, ignore_missing });
                        }
                        "raw" => {
                            // collect raw text until endraw
                            let mut raw = String::new();
                            while self.pos < self.toks.len() {
                                match &self.toks[self.pos] {
                                    Tok::Tag(c, ..) if tag_name(c).0 == "endraw" => {
                                        break;
                                    }
                                    Tok::Text(s) => raw.push_str(s),
                                    Tok::Expr(c, ..) => raw.push_str(&format!("{{{{{}}}}}", c)),
                                    Tok::Tag(c, ..) => raw.push_str(&format!("{{%{}%}}", c)),
                                    Tok::Comment(..) => {}
                                }
                                self.pos += 1;
                            }
                            self.pos += 1;
                            nodes.push(Node::Raw(raw));
                        }
                        "break" => nodes.push(Node::Break),
                        "continue" => nodes.push(Node::Continue),
                        "filter" => {
                            let f = parse_filter_call(rest)?;
                            let body = self.parse_nodes(&["endfilter"])?;
                            self.pos += 1;
                            nodes.push(Node::FilterSection { filter: f, body });
                        }
                        "macro" => {
                            let (mname, args) = parse_macro_signature(rest)?;
                            let body = self.parse_nodes(&["endmacro"])?;
                            self.pos += 1;
                            self.macros.insert(mname.clone(), (args.clone(), body.clone()));
                            nodes.push(Node::MacroDef { name: mname, args, body });
                        }
                        "import" => {
                            let (file, ns) = split_once_word(rest, "as").ok_or_else(|| ParseError(format!("Invalid import: {}", content)))?;
                            let file = parse_string_literal(file)?;
                            let ns = ns.trim().to_string();
                            self.imports.push((file.clone(), ns.clone()));
                            nodes.push(Node::Import { file, namespace: ns });
                        }
                        _ => return Err(ParseError(format!("Unknown tag `{}`", name))),
                    }
                }
            }
        }
        if end_tags.is_empty() {
            Ok(nodes)
        } else {
            Err(ParseError(format!("Expected one of {:?} but reached end of template", end_tags)))
        }
    }
}

fn split_once_trim(s: &str, c: char) -> Option<(&str, &str)> {
    s.split_once(c).map(|(a, b)| (a.trim(), b.trim()))
}

fn split_once_word<'a>(s: &'a str, word: &str) -> Option<(&'a str, &'a str)> {
    // find " word " as a whole word
    let b = s.as_bytes();
    let wb = word.as_bytes();
    let mut i = 0;
    while i + wb.len() <= b.len() {
        if &b[i..i + wb.len()] == wb {
            let before_ok = i == 0 || b[i - 1].is_ascii_whitespace();
            let after_ok = i + wb.len() == b.len() || b[i + wb.len()].is_ascii_whitespace();
            if before_ok && after_ok && i > 0 {
                return Some((s[..i].trim(), s[i + wb.len()..].trim()));
            }
        }
        i += 1;
    }
    None
}

fn parse_string_literal(s: &str) -> Result<String, ParseError> {
    match parse_expression(s.trim())? {
        Expr::Str(st) => Ok(st),
        _ => Err(ParseError(format!("Expected string literal, got `{}`", s))),
    }
}

fn parse_macro_signature(s: &str) -> Result<(String, Vec<(String, Option<Expr>)>), ParseError> {
    let s = s.trim();
    let open = s.find('(').ok_or_else(|| ParseError("Invalid macro".into()))?;
    let name = s[..open].trim().to_string();
    let close = s.rfind(')').ok_or_else(|| ParseError("Invalid macro".into()))?;
    let inner = &s[open + 1..close];
    let mut args = Vec::new();
    for part in split_top_level(inner, ',') {
        let part = part.trim();
        if part.is_empty() {
            continue;
        }
        match part.split_once('=') {
            Some((k, v)) => args.push((k.trim().to_string(), Some(parse_expression(v.trim())?))),
            None => args.push((part.to_string(), None)),
        }
    }
    Ok((name, args))
}

fn parse_filter_call(s: &str) -> Result<FilterCall, ParseError> {
    let s = s.trim();
    match s.find('(') {
        Some(open) => {
            let name = s[..open].trim().to_string();
            let close = s.rfind(')').ok_or_else(|| ParseError("Invalid filter call".into()))?;
            let args = parse_kwargs(&s[open + 1..close])?;
            Ok(FilterCall { name, args })
        }
        None => Ok(FilterCall { name: s.to_string(), args: vec![] }),
    }
}

/// Splits at top-level occurrences of `sep` (not inside strings/brackets/parens).
pub fn split_top_level(s: &str, sep: char) -> Vec<String> {
    let mut parts = Vec::new();
    let mut depth = 0i32;
    let mut in_str: Option<char> = None;
    let mut cur = String::new();
    let mut chars = s.chars().peekable();
    while let Some(c) = chars.next() {
        if let Some(q) = in_str {
            cur.push(c);
            if c == '\\' {
                if let Some(n) = chars.next() {
                    cur.push(n);
                }
                continue;
            }
            if c == q {
                in_str = None;
            }
            continue;
        }
        match c {
            '"' | '\'' | '`' => {
                in_str = Some(c);
                cur.push(c);
            }
            '(' | '[' | '{' => {
                depth += 1;
                cur.push(c);
            }
            ')' | ']' | '}' => {
                depth -= 1;
                cur.push(c);
            }
            _ if c == sep && depth == 0 => {
                parts.push(std::mem::take(&mut cur));
            }
            _ => cur.push(c),
        }
    }
    parts.push(cur);
    parts
}

fn parse_kwargs(s: &str) -> Result<Vec<(String, Expr)>, ParseError> {
    let mut args = Vec::new();
    for part in split_top_level(s, ',') {
        let part = part.trim();
        if part.is_empty() {
            continue;
        }
        let (k, v) = part.split_once('=').ok_or_else(|| ParseError(format!("Invalid keyword argument `{}`", part)))?;
        args.push((k.trim().to_string(), parse_expression(v.trim())?));
    }
    Ok(args)
}

// ---------------- Expression parsing -----------------

#[derive(Debug, Clone, PartialEq)]
enum ETok {
    Ident(String),
    Str(String),
    Int(i64),
    Float(f64),
    Op(String),
    LParen,
    RParen,
    LBracket,
    RBracket,
    Comma,
    Pipe,
    Dot,
    Tilde,
    Eq,
    DoubleColon,
}

fn lex_expr(s: &str) -> Result<Vec<ETok>, ParseError> {
    let mut toks = Vec::new();
    let chars: Vec<char> = s.chars().collect();
    let mut i = 0;
    while i < chars.len() {
        let c = chars[i];
        if c.is_whitespace() {
            i += 1;
            continue;
        }
        if c == '"' || c == '\'' || c == '`' {
            let q = c;
            i += 1;
            let mut st = String::new();
            while i < chars.len() && chars[i] != q {
                if chars[i] == '\\' && i + 1 < chars.len() {
                    let n = chars[i + 1];
                    match n {
                        'n' => st.push('\n'),
                        't' => st.push('\t'),
                        'r' => st.push('\r'),
                        '\\' => st.push('\\'),
                        '"' => st.push('"'),
                        '\'' => st.push('\''),
                        _ => {
                            st.push('\\');
                            st.push(n);
                        }
                    }
                    i += 2;
                    continue;
                }
                st.push(chars[i]);
                i += 1;
            }
            if i >= chars.len() {
                return Err(ParseError(format!("Unterminated string in expression `{}`", s)));
            }
            i += 1;
            toks.push(ETok::Str(st));
            continue;
        }
        if c.is_ascii_digit() || (c == '-' && i + 1 < chars.len() && chars[i + 1].is_ascii_digit() && matches!(toks.last(), None | Some(ETok::Op(_)) | Some(ETok::LParen) | Some(ETok::Comma) | Some(ETok::Eq) | Some(ETok::LBracket) | Some(ETok::Tilde))) {
            let start = i;
            i += 1;
            while i < chars.len() && (chars[i].is_ascii_digit() || chars[i] == '.') {
                // avoid consuming a trailing dot followed by non digit
                if chars[i] == '.' && !(i + 1 < chars.len() && chars[i + 1].is_ascii_digit()) {
                    break;
                }
                i += 1;
            }
            let num: String = chars[start..i].iter().collect();
            if num.contains('.') {
                toks.push(ETok::Float(num.parse().map_err(|_| ParseError(format!("Bad float {}", num)))?));
            } else {
                toks.push(ETok::Int(num.parse().map_err(|_| ParseError(format!("Bad int {}", num)))?));
            }
            continue;
        }
        if c.is_alphabetic() || c == '_' {
            let start = i;
            while i < chars.len() && (chars[i].is_alphanumeric() || chars[i] == '_') {
                i += 1;
            }
            let id: String = chars[start..i].iter().collect();
            toks.push(ETok::Ident(id));
            continue;
        }
        match c {
            '(' => toks.push(ETok::LParen),
            ')' => toks.push(ETok::RParen),
            '[' => toks.push(ETok::LBracket),
            ']' => toks.push(ETok::RBracket),
            ',' => toks.push(ETok::Comma),
            '|' => toks.push(ETok::Pipe),
            '.' => toks.push(ETok::Dot),
            '~' => toks.push(ETok::Tilde),
            ':' if i + 1 < chars.len() && chars[i + 1] == ':' => {
                toks.push(ETok::DoubleColon);
                i += 1;
            }
            '=' if i + 1 < chars.len() && chars[i + 1] == '=' => {
                toks.push(ETok::Op("==".into()));
                i += 1;
            }
            '=' => toks.push(ETok::Eq),
            '!' if i + 1 < chars.len() && chars[i + 1] == '=' => {
                toks.push(ETok::Op("!=".into()));
                i += 1;
            }
            '>' | '<' => {
                if i + 1 < chars.len() && chars[i + 1] == '=' {
                    toks.push(ETok::Op(format!("{}=", c)));
                    i += 1;
                } else {
                    toks.push(ETok::Op(c.to_string()));
                }
            }
            '+' | '-' | '*' | '/' | '%' => toks.push(ETok::Op(c.to_string())),
            _ => return Err(ParseError(format!("Unexpected character `{}` in expression `{}`", c, s))),
        }
        i += 1;
    }
    Ok(toks)
}

pub fn parse_expression(s: &str) -> Result<Expr, ParseError> {
    let toks = lex_expr(s)?;
    let mut p = ExprParser { toks, pos: 0 };
    let e = p.parse_logic()?;
    if p.pos < p.toks.len() {
        return Err(ParseError(format!("Unexpected token {:?} in expression `{}`", p.toks[p.pos], s)));
    }
    Ok(e)
}

struct ExprParser {
    toks: Vec<ETok>,
    pos: usize,
}

impl ExprParser {
    fn peek(&self) -> Option<&ETok> {
        self.toks.get(self.pos)
    }
    fn next(&mut self) -> Option<ETok> {
        let t = self.toks.get(self.pos).cloned();
        self.pos += 1;
        t
    }
    fn peek_ident(&self, s: &str) -> bool {
        matches!(self.peek(), Some(ETok::Ident(x)) if x == s)
    }
    fn expect(&mut self, t: ETok) -> Result<(), ParseError> {
        match self.next() {
            Some(x) if x == t => Ok(()),
            other => Err(ParseError(format!("Expected {:?}, got {:?}", t, other))),
        }
    }

    // logic: or
    fn parse_logic(&mut self) -> Result<Expr, ParseError> {
        let mut lhs = self.parse_and()?;
        while self.peek_ident("or") {
            self.next();
            let rhs = self.parse_and()?;
            lhs = Expr::Logic(Box::new(lhs), LogicOp::Or, Box::new(rhs));
        }
        Ok(lhs)
    }
    fn parse_and(&mut self) -> Result<Expr, ParseError> {
        let mut lhs = self.parse_not()?;
        while self.peek_ident("and") {
            self.next();
            let rhs = self.parse_not()?;
            lhs = Expr::Logic(Box::new(lhs), LogicOp::And, Box::new(rhs));
        }
        Ok(lhs)
    }
    fn parse_not(&mut self) -> Result<Expr, ParseError> {
        if self.peek_ident("not") {
            self.next();
            let e = self.parse_not()?;
            return Ok(Expr::Not(Box::new(e)));
        }
        self.parse_comparison()
    }
    fn parse_comparison(&mut self) -> Result<Expr, ParseError> {
        let lhs = self.parse_in_or_test()?;
        if let Some(ETok::Op(op)) = self.peek().cloned() {
            let cmp = match op.as_str() {
                "==" => Some(CmpOp::Eq),
                "!=" => Some(CmpOp::Ne),
                ">" => Some(CmpOp::Gt),
                "<" => Some(CmpOp::Lt),
                ">=" => Some(CmpOp::Ge),
                "<=" => Some(CmpOp::Le),
                _ => None,
            };
            if let Some(cmp) = cmp {
                self.next();
                let rhs = self.parse_in_or_test()?;
                return Ok(Expr::Comparison(Box::new(lhs), cmp, Box::new(rhs)));
            }
        }
        Ok(lhs)
    }
    fn parse_in_or_test(&mut self) -> Result<Expr, ParseError> {
        let lhs = self.parse_concat()?;
        // `is [not] test(args)`
        if self.peek_ident("is") {
            self.next();
            let mut negated = false;
            if self.peek_ident("not") {
                self.next();
                negated = true;
            }
            let name = match self.next() {
                Some(ETok::Ident(n)) => n,
                other => return Err(ParseError(format!("Expected test name, got {:?}", other))),
            };
            let mut args = Vec::new();
            if let Some(ETok::LParen) = self.peek() {
                self.next();
                loop {
                    if let Some(ETok::RParen) = self.peek() {
                        self.next();
                        break;
                    }
                    args.push(self.parse_logic()?);
                    match self.peek() {
                        Some(ETok::Comma) => {
                            self.next();
                        }
                        Some(ETok::RParen) => {
                            self.next();
                            break;
                        }
                        other => return Err(ParseError(format!("Unexpected {:?} in test args", other))),
                    }
                }
            }
            return Ok(Expr::Test { expr: Box::new(lhs), name, args, negated });
        }
        // `[not] in`
        let mut negated = false;
        let save = self.pos;
        if self.peek_ident("not") {
            self.next();
            negated = true;
        }
        if self.peek_ident("in") {
            self.next();
            let rhs = self.parse_concat()?;
            return Ok(Expr::In { lhs: Box::new(lhs), rhs: Box::new(rhs), negated });
        }
        self.pos = save;
        Ok(lhs)
    }
    fn parse_concat(&mut self) -> Result<Expr, ParseError> {
        let first = self.parse_math()?;
        if let Some(ETok::Tilde) = self.peek() {
            let mut parts = vec![first];
            while let Some(ETok::Tilde) = self.peek() {
                self.next();
                parts.push(self.parse_math()?);
            }
            let concat = Expr::Concat(parts);
            // filters after concat
            let filters = self.parse_filters()?;
            if filters.is_empty() {
                return Ok(concat);
            }
            return Ok(Expr::Filtered(Box::new(concat), filters));
        }
        Ok(first)
    }
    fn parse_filters(&mut self) -> Result<Vec<FilterCall>, ParseError> {
        let mut filters = Vec::new();
        while let Some(ETok::Pipe) = self.peek() {
            self.next();
            let name = match self.next() {
                Some(ETok::Ident(n)) => n,
                other => return Err(ParseError(format!("Expected filter name, got {:?}", other))),
            };
            let mut args = Vec::new();
            if let Some(ETok::LParen) = self.peek() {
                self.next();
                args = self.parse_kwargs_inner()?;
            }
            filters.push(FilterCall { name, args });
        }
        Ok(filters)
    }
    fn parse_kwargs_inner(&mut self) -> Result<Vec<(String, Expr)>, ParseError> {
        let mut args = Vec::new();
        loop {
            if let Some(ETok::RParen) = self.peek() {
                self.next();
                break;
            }
            let name = match self.next() {
                Some(ETok::Ident(n)) => n,
                other => return Err(ParseError(format!("Expected argument name, got {:?}", other))),
            };
            self.expect(ETok::Eq)?;
            let value = self.parse_logic()?;
            args.push((name, value));
            match self.peek() {
                Some(ETok::Comma) => {
                    self.next();
                }
                Some(ETok::RParen) => {
                    self.next();
                    break;
                }
                other => return Err(ParseError(format!("Unexpected {:?} in arguments", other))),
            }
        }
        Ok(args)
    }
    // math: + -
    fn parse_math(&mut self) -> Result<Expr, ParseError> {
        let mut lhs = self.parse_term()?;
        loop {
            match self.peek() {
                Some(ETok::Op(op)) if op == "+" || op == "-" => {
                    let op = if op == "+" { MathOp::Add } else { MathOp::Sub };
                    self.next();
                    let rhs = self.parse_term()?;
                    lhs = Expr::Math(Box::new(lhs), op, Box::new(rhs));
                }
                _ => break,
            }
        }
        // filters bind to the math expression
        let filters = self.parse_filters()?;
        if filters.is_empty() {
            Ok(lhs)
        } else {
            Ok(Expr::Filtered(Box::new(lhs), filters))
        }
    }
    fn parse_term(&mut self) -> Result<Expr, ParseError> {
        let mut lhs = self.parse_unary()?;
        loop {
            match self.peek() {
                Some(ETok::Op(op)) if op == "*" || op == "/" || op == "%" => {
                    let op = match op.as_str() {
                        "*" => MathOp::Mul,
                        "/" => MathOp::Div,
                        _ => MathOp::Mod,
                    };
                    self.next();
                    let rhs = self.parse_unary()?;
                    lhs = Expr::Math(Box::new(lhs), op, Box::new(rhs));
                }
                _ => break,
            }
        }
        Ok(lhs)
    }
    fn parse_unary(&mut self) -> Result<Expr, ParseError> {
        if let Some(ETok::Op(op)) = self.peek() {
            if op == "-" {
                self.next();
                let e = self.parse_unary()?;
                return Ok(Expr::Math(Box::new(Expr::Int(0)), MathOp::Sub, Box::new(e)));
            }
        }
        self.parse_primary()
    }
    fn parse_primary(&mut self) -> Result<Expr, ParseError> {
        match self.next() {
            Some(ETok::Str(s)) => Ok(Expr::Str(s)),
            Some(ETok::Int(i)) => Ok(Expr::Int(i)),
            Some(ETok::Float(f)) => Ok(Expr::Float(f)),
            Some(ETok::LParen) => {
                let e = self.parse_logic()?;
                self.expect(ETok::RParen)?;
                Ok(e)
            }
            Some(ETok::LBracket) => {
                let mut items = Vec::new();
                loop {
                    if let Some(ETok::RBracket) = self.peek() {
                        self.next();
                        break;
                    }
                    items.push(self.parse_logic()?);
                    match self.peek() {
                        Some(ETok::Comma) => {
                            self.next();
                        }
                        Some(ETok::RBracket) => {
                            self.next();
                            break;
                        }
                        other => return Err(ParseError(format!("Unexpected {:?} in array", other))),
                    }
                }
                Ok(Expr::Array(items))
            }
            Some(ETok::Ident(id)) => {
                match id.as_str() {
                    "true" | "True" => return Ok(Expr::Bool(true)),
                    "false" | "False" => return Ok(Expr::Bool(false)),
                    _ => {}
                }
                // macro call ns::name(...)
                if let Some(ETok::DoubleColon) = self.peek() {
                    self.next();
                    let name = match self.next() {
                        Some(ETok::Ident(n)) => n,
                        other => return Err(ParseError(format!("Expected macro name, got {:?}", other))),
                    };
                    self.expect(ETok::LParen)?;
                    let args = self.parse_kwargs_inner()?;
                    return Ok(Expr::MacroCall { namespace: id, name, args });
                }
                // function call
                if let Some(ETok::LParen) = self.peek() {
                    self.next();
                    let args = self.parse_kwargs_inner()?;
                    return Ok(Expr::FunctionCall { name: id, args });
                }
                // dotted / bracket ident
                let mut segs = vec![Segment::Name(id)];
                loop {
                    match self.peek() {
                        Some(ETok::Dot) => {
                            self.next();
                            match self.next() {
                                Some(ETok::Ident(n)) => segs.push(Segment::Name(n)),
                                Some(ETok::Int(i)) => segs.push(Segment::Name(i.to_string())),
                                Some(ETok::Float(f)) => {
                                    // e.g. item.0.1 lexed as float "0.1"
                                    let s = format!("{}", f);
                                    for part in s.split('.') {
                                        segs.push(Segment::Name(part.to_string()));
                                    }
                                }
                                other => return Err(ParseError(format!("Expected identifier after `.`, got {:?}", other))),
                            }
                        }
                        Some(ETok::LBracket) => {
                            self.next();
                            let idx = self.parse_logic()?;
                            self.expect(ETok::RBracket)?;
                            segs.push(Segment::Index(Box::new(idx)));
                        }
                        _ => break,
                    }
                }
                Ok(Expr::Ident(segs))
            }
            other => Err(ParseError(format!("Unexpected token {:?} in expression", other))),
        }
    }
}
