//! Template rendering.

use super::ast::*;
use super::parser::{parse_template, ParseError};
use serde_json::{Map, Value};
use std::collections::HashMap;

#[derive(Debug)]
pub struct Error {
    pub msg: String,
    pub source: Option<Box<Error>>,
}

impl Error {
    pub fn msg(s: impl Into<String>) -> Error {
        Error { msg: s.into(), source: None }
    }
    pub fn chain(s: impl Into<String>, source: Error) -> Error {
        Error { msg: s.into(), source: Some(Box::new(source)) }
    }
    /// Debug-like rendering similar to tera's Error Debug output.
    pub fn debug_string(&self) -> String {
        self.debug_indent(0)
    }
    fn debug_indent(&self, level: usize) -> String {
        let pad = "    ".repeat(level);
        let mut s = String::new();
        s.push_str("Error {\n");
        s.push_str(&format!("{}    kind: Msg(\n{}        {:?},\n{}    ),\n", pad, pad, self.msg, pad));
        match &self.source {
            Some(src) => {
                s.push_str(&format!("{}    source: Some(\n{}        {},\n{}    ),\n", pad, pad, src.debug_indent(level + 2), pad));
            }
            None => s.push_str(&format!("{}    source: None,\n", pad)),
        }
        s.push_str(&format!("{}}}", pad));
        s
    }
    pub fn innermost(&self) -> &Error {
        match &self.source {
            Some(s) => s.innermost(),
            None => self,
        }
    }
}

impl From<ParseError> for Error {
    fn from(e: ParseError) -> Error {
        Error::msg(e.0)
    }
}

pub type Result<T> = std::result::Result<T, Error>;

pub type FilterFn = dyn Fn(&Value, &HashMap<String, Value>) -> Result<Value> + Send + Sync;
pub type FunctionFn = dyn Fn(&HashMap<String, Value>) -> Result<Value> + Send + Sync;
pub type TestFn = dyn Fn(Option<&Value>, &[Value]) -> Result<bool> + Send + Sync;

pub struct Tera {
    pub templates: HashMap<String, Template>,
    pub filters: HashMap<String, Box<FilterFn>>,
    pub functions: HashMap<String, Box<FunctionFn>>,
    pub tests: HashMap<String, Box<TestFn>>,
}

#[derive(Clone)]
pub struct Context {
    pub data: Map<String, Value>,
}

impl Context {
    pub fn new() -> Context {
        Context { data: Map::new() }
    }
    pub fn insert<T: serde::Serialize>(&mut self, key: &str, val: &T) {
        self.data.insert(key.to_string(), serde_json::to_value(val).unwrap_or(Value::Null));
    }
    pub fn insert_value(&mut self, key: &str, val: Value) {
        self.data.insert(key.to_string(), val);
    }
    pub fn remove(&mut self, key: &str) {
        self.data.remove(key);
    }
    pub fn get(&self, key: &str) -> Option<&Value> {
        self.data.get(key)
    }
}

struct ForLoopState {
    vars: Map<String, Value>,
}

enum Flow {
    Normal,
    Break,
    Continue,
}

struct Renderer<'a> {
    tera: &'a Tera,
    /// the template whose render was requested (for blocks lookup chain)
    chain: Vec<&'a Template>,
    globals: Map<String, Value>,
    loops: Vec<ForLoopState>,
    /// stack of (block name, level) for super()
    block_stack: Vec<(String, usize)>,
    macro_namespaces: HashMap<String, String>,
    macro_frames: Vec<Map<String, Value>>,
    current_template: String,
}

impl Tera {
    pub fn new() -> Tera {
        let mut t = Tera { templates: HashMap::new(), filters: HashMap::new(), functions: HashMap::new(), tests: HashMap::new() };
        super::builtins::register(&mut t);
        t
    }

    pub fn add_raw_template(&mut self, name: &str, source: &str) -> Result<()> {
        let tpl = parse_template(name, source).map_err(|e| Error::msg(format!("Failed to parse '{}': {}", name, e.0)))?;
        self.templates.insert(name.to_string(), tpl);
        Ok(())
    }

    pub fn register_filter<F>(&mut self, name: &str, f: F)
    where
        F: Fn(&Value, &HashMap<String, Value>) -> Result<Value> + Send + Sync + 'static,
    {
        self.filters.insert(name.to_string(), Box::new(f));
    }
    pub fn register_function<F>(&mut self, name: &str, f: F)
    where
        F: Fn(&HashMap<String, Value>) -> Result<Value> + Send + Sync + 'static,
    {
        self.functions.insert(name.to_string(), Box::new(f));
    }
    pub fn register_tester<F>(&mut self, name: &str, f: F)
    where
        F: Fn(Option<&Value>, &[Value]) -> Result<bool> + Send + Sync + 'static,
    {
        self.tests.insert(name.to_string(), Box::new(f));
    }

    pub fn get_template_names(&self) -> Vec<String> {
        self.templates.keys().cloned().collect()
    }

    pub fn render(&self, name: &str, ctx: &Context) -> Result<String> {
        let tpl = self.templates.get(name).ok_or_else(|| Error::msg(format!("Template '{}' not found", name)))?;
        // build inheritance chain: [most-derived, ..., root]
        let mut chain: Vec<&Template> = vec![tpl];
        let mut cur = tpl;
        let mut guard = 0;
        while let Some(p) = &cur.parent {
            let pt = self.templates.get(p).ok_or_else(|| Error::msg(format!("Template '{}' not found", p)))?;
            chain.push(pt);
            cur = pt;
            guard += 1;
            if guard > 50 {
                return Err(Error::msg("Inheritance chain too deep"));
            }
        }
        let mut r = Renderer {
            tera: self,
            chain,
            globals: ctx.data.clone(),
            loops: Vec::new(),
            block_stack: Vec::new(),
            macro_namespaces: HashMap::new(),
            macro_frames: Vec::new(),
            current_template: name.to_string(),
        };
        r.register_imports(tpl);
        let root = *r.chain.last().unwrap();
        let mut out = String::new();
        r.render_nodes(&root.nodes, &mut out).map_err(|e| Error::chain(format!("Failed to render '{}'", name), e))?;
        Ok(out)
    }

    pub fn render_str(&self, source: &str, ctx: &Context) -> Result<String> {
        let tpl = parse_template("__render_str__", source)?;
        let mut r = Renderer {
            tera: self,
            chain: vec![&tpl],
            globals: ctx.data.clone(),
            loops: Vec::new(),
            block_stack: Vec::new(),
            macro_namespaces: HashMap::new(),
            macro_frames: Vec::new(),
            current_template: "__render_str__".to_string(),
        };
        let mut out = String::new();
        r.register_imports(&tpl);
        r.render_nodes(&tpl.nodes, &mut out)?;
        Ok(out)
    }
}

pub fn is_truthy(v: &Value) -> bool {
    match v {
        Value::Null => false,
        Value::Bool(b) => *b,
        Value::Number(n) => {
            if let Some(i) = n.as_i64() {
                i != 0
            } else if let Some(f) = n.as_f64() {
                f != 0.0
            } else {
                true
            }
        }
        Value::String(s) => !s.is_empty(),
        Value::Array(a) => !a.is_empty(),
        Value::Object(o) => !o.is_empty(),
    }
}

pub fn render_value(v: &Value) -> String {
    match v {
        Value::Null => String::new(),
        Value::String(s) => s.clone(),
        Value::Bool(b) => b.to_string(),
        Value::Number(n) => n.to_string(),
        Value::Array(_) | Value::Object(_) => v.to_string(),
    }
}

fn num_to_f64(v: &Value) -> Option<f64> {
    match v {
        Value::Number(n) => n.as_f64(),
        _ => None,
    }
}

impl<'a> Renderer<'a> {
    fn register_imports(&mut self, tpl: &Template) {
        for (file, ns) in &tpl.imports {
            self.macro_namespaces.insert(ns.clone(), file.clone());
        }
        // also imports of parents
        for t in self.chain.iter() {
            for (file, ns) in &t.imports {
                self.macro_namespaces.entry(ns.clone()).or_insert(file.clone());
            }
        }
    }

    fn lookup_var(&self, name: &str) -> Option<Value> {
        if let Some(f) = self.macro_frames.last() {
            if let Some(v) = f.get(name) {
                return Some(v.clone());
            }
            // macros don't see outer scope (except globals? tera: no)
        }
        for l in self.loops.iter().rev() {
            if let Some(v) = l.vars.get(name) {
                return Some(v.clone());
            }
        }
        self.globals.get(name).cloned()
    }

    fn set_var(&mut self, name: &str, value: Value, global: bool) {
        if let Some(f) = self.macro_frames.last_mut() {
            f.insert(name.to_string(), value);
            return;
        }
        if !global {
            if let Some(l) = self.loops.last_mut() {
                l.vars.insert(name.to_string(), value);
                return;
            }
        }
        self.globals.insert(name.to_string(), value);
    }

    fn ident_string(segs: &[Segment]) -> String {
        let mut s = String::new();
        for (i, seg) in segs.iter().enumerate() {
            match seg {
                Segment::Name(n) => {
                    if i > 0 {
                        s.push('.');
                    }
                    s.push_str(n);
                }
                Segment::Index(e) => {
                    s.push('[');
                    s.push_str(&expr_to_string(e));
                    s.push(']');
                }
            }
        }
        s
    }

    /// Evaluates an identifier path. Returns Ok(None) if undefined.
    fn eval_ident(&mut self, segs: &[Segment]) -> Result<Option<Value>> {
        let first = match &segs[0] {
            Segment::Name(n) => n,
            _ => return Err(Error::msg("Invalid identifier")),
        };
        let mut cur = match self.lookup_var(first) {
            Some(v) => v,
            None => return Ok(None),
        };
        for seg in &segs[1..] {
            let next = match seg {
                Segment::Name(n) => match &cur {
                    Value::Object(o) => o.get(n).cloned(),
                    Value::Array(a) => n.parse::<usize>().ok().and_then(|i| a.get(i).cloned()),
                    _ => None,
                },
                Segment::Index(e) => {
                    let idx = self.eval_expr(e)?;
                    match (&cur, &idx) {
                        (Value::Object(o), Value::String(k)) => o.get(k).cloned(),
                        (Value::Array(a), Value::Number(n)) => n.as_u64().and_then(|i| a.get(i as usize).cloned()),
                        (Value::Object(o), Value::Number(n)) => o.get(&n.to_string()).cloned(),
                        _ => None,
                    }
                }
            };
            match next {
                Some(v) => cur = v,
                None => return Ok(None),
            }
        }
        Ok(Some(cur))
    }

    fn eval_expr(&mut self, e: &Expr) -> Result<Value> {
        match e {
            Expr::Str(s) => Ok(Value::String(s.clone())),
            Expr::Int(i) => Ok(Value::from(*i)),
            Expr::Float(f) => Ok(Value::from(*f)),
            Expr::Bool(b) => Ok(Value::Bool(*b)),
            Expr::Array(items) => {
                let mut out = Vec::new();
                for i in items {
                    out.push(self.eval_expr(i)?);
                }
                Ok(Value::Array(out))
            }
            Expr::Ident(segs) => match self.eval_ident(segs)? {
                Some(v) => Ok(v),
                None => {
                    let name = Self::ident_string(segs);
                    let evaluated = self.evaluated_ident(segs)?;
                    if evaluated != name {
                        Err(Error::msg(format!(
                            "Variable `{}` not found in context while rendering '{}': the evaluated version was `{}`. Maybe the index is out of bounds?",
                            name, self.current_template, evaluated
                        )))
                    } else {
                        Err(Error::msg(format!("Variable `{}` not found in context while rendering '{}'", name, self.current_template)))
                    }
                }
            },
            Expr::Math(l, op, r) => {
                let lv = self.eval_expr(l)?;
                let rv = self.eval_expr(r)?;
                math(&lv, *op, &rv)
            }
            Expr::Logic(l, op, r) => {
                let lv = self.eval_truthy(l)?;
                match op {
                    LogicOp::And => {
                        if !lv {
                            return Ok(Value::Bool(false));
                        }
                        Ok(Value::Bool(self.eval_truthy(r)?))
                    }
                    LogicOp::Or => {
                        if lv {
                            return Ok(Value::Bool(true));
                        }
                        Ok(Value::Bool(self.eval_truthy(r)?))
                    }
                }
            }
            Expr::Not(inner) => Ok(Value::Bool(!self.eval_truthy(inner)?)),
            Expr::Comparison(l, op, r) => {
                let lv = self.eval_expr(l)?;
                let rv = self.eval_expr(r)?;
                Ok(Value::Bool(compare(&lv, *op, &rv)?))
            }
            Expr::Concat(parts) => {
                let mut s = String::new();
                for p in parts {
                    let v = self.eval_expr(p)?;
                    s.push_str(&render_value(&v));
                }
                Ok(Value::String(s))
            }
            Expr::In { lhs, rhs, negated } => {
                let l = self.eval_expr(lhs)?;
                let r = match self.eval_expr(rhs) {
                    Ok(v) => v,
                    Err(e) => return Err(e),
                };
                let found = match &r {
                    Value::Array(a) => a.contains(&l),
                    Value::String(s) => match &l {
                        Value::String(ls) => s.contains(ls.as_str()),
                        other => s.contains(&render_value(other)),
                    },
                    Value::Object(o) => match &l {
                        Value::String(ls) => o.contains_key(ls),
                        _ => false,
                    },
                    _ => return Err(Error::msg("`in` operator requires an array, string or object on the right side")),
                };
                Ok(Value::Bool(if *negated { !found } else { found }))
            }
            Expr::Test { expr, name, args, negated } => {
                let v = match &**expr {
                    Expr::Ident(segs) => self.eval_ident(segs)?,
                    other => Some(self.eval_expr(other)?),
                };
                let mut argv = Vec::new();
                for a in args {
                    argv.push(self.eval_expr(a)?);
                }
                let t = self.tera.tests.get(name).ok_or_else(|| Error::msg(format!("Tester `{}` not found", name)))?;
                let r = t(v.as_ref(), &argv)?;
                Ok(Value::Bool(if *negated { !r } else { r }))
            }
            Expr::FunctionCall { name, args } => {
                let mut argmap = HashMap::new();
                for (k, v) in args {
                    argmap.insert(k.clone(), self.eval_expr(v)?);
                }
                if name == "super" {
                    return Err(Error::msg("super() used outside of block output"));
                }
                let f = self.tera.functions.get(name).ok_or_else(|| Error::msg(format!("Function `{}` not found", name)))?;
                f(&argmap)
            }
            Expr::MacroCall { namespace, name, args } => {
                let mut out = String::new();
                self.render_macro(namespace, name, args, &mut out)?;
                Ok(Value::String(out))
            }
            Expr::Filtered(inner, filters) => {
                // special-case `default` filter on undefined ident
                let mut val = match &**inner {
                    Expr::Ident(segs) => match self.eval_ident(segs)? {
                        Some(v) => v,
                        None => {
                            if filters.first().map(|f| f.name == "default").unwrap_or(false) {
                                Value::Null
                            } else {
                                return self.eval_expr(inner);
                            }
                        }
                    },
                    other => self.eval_expr(other)?,
                };
                for (i, f) in filters.iter().enumerate() {
                    let mut argmap = HashMap::new();
                    for (k, v) in &f.args {
                        argmap.insert(k.clone(), self.eval_expr(v)?);
                    }
                    if f.name == "default" && i == 0 {
                        if let Expr::Ident(segs) = &**inner {
                            if self.eval_ident(segs)?.is_none() {
                                val = argmap.get("value").cloned().unwrap_or(Value::Null);
                                continue;
                            }
                        }
                    }
                    let filter = self.tera.filters.get(&f.name).ok_or_else(|| Error::msg(format!("Filter `{}` not found", f.name)))?;
                    val = filter(&val, &argmap).map_err(|e| Error::chain(format!("Filter call `{}` failed", f.name), e))?;
                }
                Ok(val)
            }
        }
    }

    fn evaluated_ident(&mut self, segs: &[Segment]) -> Result<String> {
        let mut s = String::new();
        for (i, seg) in segs.iter().enumerate() {
            match seg {
                Segment::Name(n) => {
                    if i > 0 {
                        s.push('.');
                    }
                    s.push_str(n);
                }
                Segment::Index(e) => {
                    let v = self.eval_expr(e)?;
                    match v {
                        Value::String(st) => {
                            s.push('.');
                            s.push_str(&format!("{:?}", st));
                        }
                        other => {
                            s.push('.');
                            s.push_str(&render_value(&other));
                        }
                    }
                }
            }
        }
        Ok(s)
    }

    fn eval_truthy(&mut self, e: &Expr) -> Result<bool> {
        match e {
            Expr::Ident(segs) => Ok(match self.eval_ident(segs)? {
                Some(v) => is_truthy(&v),
                None => false,
            }),
            Expr::Filtered(inner, _) => {
                if let Expr::Ident(segs) = &**inner {
                    if self.eval_ident(segs)?.is_none() {
                        // tera: filtered undefined in condition -> error unless default
                        return Ok(is_truthy(&self.eval_expr(e)?));
                    }
                }
                Ok(is_truthy(&self.eval_expr(e)?))
            }
            _ => Ok(is_truthy(&self.eval_expr(e)?)),
        }
    }

    fn render_nodes(&mut self, nodes: &[Node], out: &mut String) -> Result<Flow> {
        for n in nodes {
            match self.render_node(n, out)? {
                Flow::Normal => {}
                other => return Ok(other),
            }
        }
        Ok(Flow::Normal)
    }

    fn find_block(&self, name: &str, start_level: usize) -> Option<(Vec<Node>, usize)> {
        // search from most-derived (index 0) upward starting at start_level
        for (i, t) in self.chain.iter().enumerate().skip(start_level) {
            if let Some(b) = t.blocks.get(name) {
                return Some((b.clone(), i));
            }
        }
        None
    }

    fn render_node(&mut self, node: &Node, out: &mut String) -> Result<Flow> {
        match node {
            Node::Text(s) | Node::Raw(s) => out.push_str(s),
            Node::Expr(e) => {
                if let Expr::FunctionCall { name, .. } = e {
                    if name == "super" {
                        return self.render_super(out);
                    }
                }
                let v = self.eval_expr(e)?;
                out.push_str(&render_value(&v));
            }
            Node::Set { key, value, global } => {
                let v = self.eval_expr(value)?;
                self.set_var(key, v, *global);
            }
            Node::If { conds, else_body } => {
                for (c, body) in conds {
                    if self.eval_truthy(c)? {
                        return self.render_nodes(body, out);
                    }
                }
                if let Some(b) = else_body {
                    return self.render_nodes(b, out);
                }
            }
            Node::For { key, value, container, body, empty_body } => {
                let cv = self.eval_expr(container)?;
                let items: Vec<(Value, Value)> = match &cv {
                    Value::Array(a) => a.iter().enumerate().map(|(i, v)| (Value::from(i), v.clone())).collect(),
                    Value::Object(o) => o.iter().map(|(k, v)| (Value::String(k.clone()), v.clone())).collect(),
                    Value::String(s) => s.chars().enumerate().map(|(i, c)| (Value::from(i), Value::String(c.to_string()))).collect(),
                    Value::Null => return Err(Error::msg(format!("Tried to iterate on a container (`{}`) that has a unsupported type", expr_to_string(container)))),
                    _ => return Err(Error::msg(format!("Tried to iterate on a container (`{}`) that has a unsupported type", expr_to_string(container)))),
                };
                if key.is_some() && !matches!(cv, Value::Object(_)) {
                    return Err(Error::msg(format!("Tried to iterate using key value on variable `{}`, but it isn't an object/map", expr_to_string(container))));
                }
                if items.is_empty() {
                    if let Some(eb) = empty_body {
                        return self.render_nodes(eb, out);
                    }
                    return Ok(Flow::Normal);
                }
                let len = items.len();
                for (i, (k, v)) in items.into_iter().enumerate() {
                    let mut vars = Map::new();
                    if let Some(kn) = key {
                        vars.insert(kn.clone(), k);
                    }
                    vars.insert(value.clone(), v);
                    let mut lp = Map::new();
                    lp.insert("index".into(), Value::from(i + 1));
                    lp.insert("index0".into(), Value::from(i));
                    lp.insert("first".into(), Value::Bool(i == 0));
                    lp.insert("last".into(), Value::Bool(i + 1 == len));
                    vars.insert("loop".into(), Value::Object(lp));
                    self.loops.push(ForLoopState { vars });
                    let flow = self.render_nodes(body, out);
                    self.loops.pop();
                    match flow? {
                        Flow::Break => break,
                        _ => {}
                    }
                }
            }
            Node::Block { name, .. } => {
                // render the most-derived definition of this block
                match self.find_block(name, 0) {
                    Some((body, level)) => {
                        self.block_stack.push((name.clone(), level));
                        let r = self.render_nodes(&body, out);
                        self.block_stack.pop();
                        r?;
                    }
                    None => {}
                }
            }
            Node::Super => return self.render_super(out),
            Node::Include { files, ignore_missing } => {
                let mut found = false;
                for f in files {
                    if let Some(tpl) = self.tera.templates.get(f) {
                        found = true;
                        let saved = std::mem::replace(&mut self.current_template, f.clone());
                        let saved_chain = std::mem::replace(&mut self.chain, vec![tpl]);
                        let saved_blocks = std::mem::take(&mut self.block_stack);
                        for (file, ns) in &tpl.imports {
                            self.macro_namespaces.insert(ns.clone(), file.clone());
                        }
                        let r = self.render_nodes(&tpl.nodes, out);
                        self.chain = saved_chain;
                        self.block_stack = saved_blocks;
                        self.current_template = saved;
                        r.map_err(|e| Error::chain(format!("Failed to render '{}'", f), e))?;
                        break;
                    }
                }
                if !found && !ignore_missing {
                    return Err(Error::msg(format!("Template '{}' not found", files.join(", "))));
                }
            }
            Node::Break => return Ok(Flow::Break),
            Node::Continue => return Ok(Flow::Continue),
            Node::FilterSection { filter, body } => {
                let mut inner = String::new();
                self.render_nodes(body, &mut inner)?;
                let mut argmap = HashMap::new();
                for (k, v) in &filter.args {
                    argmap.insert(k.clone(), self.eval_expr(v)?);
                }
                let f = self.tera.filters.get(&filter.name).ok_or_else(|| Error::msg(format!("Filter `{}` not found", filter.name)))?;
                let v = f(&Value::String(inner), &argmap)?;
                out.push_str(&render_value(&v));
            }
            Node::MacroDef { .. } => {}
            Node::Import { file, namespace } => {
                self.macro_namespaces.insert(namespace.clone(), file.clone());
            }
        }
        Ok(Flow::Normal)
    }

    fn render_super(&mut self, out: &mut String) -> Result<Flow> {
        let (name, level) = match self.block_stack.last() {
            Some(x) => x.clone(),
            None => return Err(Error::msg("super() called outside of a block")),
        };
        match self.find_block(&name, level + 1) {
            Some((body, lvl)) => {
                self.block_stack.push((name, lvl));
                let r = self.render_nodes(&body, out);
                self.block_stack.pop();
                r
            }
            None => Err(Error::msg(format!("Tried to use super() in the top level block `{}`", name))),
        }
    }

    fn render_macro(&mut self, namespace: &str, name: &str, args: &[(String, Expr)], out: &mut String) -> Result<()> {
        let file = match self.macro_namespaces.get(namespace) {
            Some(f) => f.clone(),
            None => {
                if namespace == "self" {
                    self.current_template.clone()
                } else {
                    return Err(Error::msg(format!("Macro namespace `{}` was not found", namespace)));
                }
            }
        };
        let tpl = self.tera.templates.get(&file).ok_or_else(|| Error::msg(format!("Template '{}' not found", file)))?;
        let (params, body) = tpl.macros.get(name).ok_or_else(|| Error::msg(format!("Macro `{}::{}` not found", namespace, name)))?.clone();
        let mut frame = Map::new();
        for (pname, default) in &params {
            let provided = args.iter().find(|(k, _)| k == pname);
            let v = match provided {
                Some((_, e)) => self.eval_expr(e)?,
                None => match default {
                    Some(d) => self.eval_expr(d)?,
                    None => return Err(Error::msg(format!("Macro `{}` is missing the argument `{}`", name, pname))),
                },
            };
            frame.insert(pname.clone(), v);
        }
        self.macro_frames.push(frame);
        let saved_loops = std::mem::take(&mut self.loops);
        let r = self.render_nodes(&body, out);
        self.loops = saved_loops;
        self.macro_frames.pop();
        r.map(|_| ())
    }
}

pub fn expr_to_string(e: &Expr) -> String {
    match e {
        Expr::Str(s) => format!("\"{}\"", s),
        Expr::Int(i) => i.to_string(),
        Expr::Float(f) => f.to_string(),
        Expr::Bool(b) => b.to_string(),
        Expr::Ident(segs) => Renderer::ident_string(segs),
        Expr::Filtered(inner, filters) => {
            let mut s = expr_to_string(inner);
            for f in filters {
                s.push_str(" | ");
                s.push_str(&f.name);
            }
            s
        }
        Expr::FunctionCall { name, .. } => format!("{}()", name),
        _ => "<expr>".to_string(),
    }
}

fn math(l: &Value, op: MathOp, r: &Value) -> Result<Value> {
    let (li, ri) = (l.as_i64(), r.as_i64());
    if let (Some(a), Some(b)) = (li, ri) {
        return Ok(match op {
            MathOp::Add => Value::from(a + b),
            MathOp::Sub => Value::from(a - b),
            MathOp::Mul => Value::from(a * b),
            MathOp::Div => {
                if b == 0 {
                    return Err(Error::msg("Division by zero"));
                }
                Value::from(a as f64 / b as f64)
            }
            MathOp::Mod => {
                if b == 0 {
                    return Err(Error::msg("Modulo by zero"));
                }
                Value::from(a % b)
            }
        });
    }
    let (a, b) = match (num_to_f64(l), num_to_f64(r)) {
        (Some(a), Some(b)) => (a, b),
        _ => return Err(Error::msg(format!("Math operation on non-numbers: {} and {}", render_value(l), render_value(r)))),
    };
    Ok(match op {
        MathOp::Add => Value::from(a + b),
        MathOp::Sub => Value::from(a - b),
        MathOp::Mul => Value::from(a * b),
        MathOp::Div => {
            if b == 0.0 {
                return Err(Error::msg("Division by zero"));
            }
            Value::from(a / b)
        }
        MathOp::Mod => Value::from(a % b),
    })
}

fn compare(l: &Value, op: CmpOp, r: &Value) -> Result<bool> {
    if let (Some(a), Some(b)) = (num_to_f64(l), num_to_f64(r)) {
        return Ok(match op {
            CmpOp::Eq => a == b,
            CmpOp::Ne => a != b,
            CmpOp::Gt => a > b,
            CmpOp::Lt => a < b,
            CmpOp::Ge => a >= b,
            CmpOp::Le => a <= b,
        });
    }
    match op {
        CmpOp::Eq => Ok(l == r),
        CmpOp::Ne => Ok(l != r),
        _ => {
            if let (Value::String(a), Value::String(b)) = (l, r) {
                return Ok(match op {
                    CmpOp::Gt => a > b,
                    CmpOp::Lt => a < b,
                    CmpOp::Ge => a >= b,
                    CmpOp::Le => a <= b,
                    _ => unreachable!(),
                });
            }
            Err(Error::msg("Comparison requires numbers or strings"))
        }
    }
}
