{"command":"cat > /workspace/src/tera/builtins.rs <<'EOF'
//! Built-in filters, functions and tests (tera compatible subset).

use super::render::{is_truthy, render_value, Error, Result, Tera};
use serde_json::{Map, Value};
use std::collections::HashMap;

fn arg<'a>(args: &'a HashMap<String, Value>, name: &str) -> Option<&'a Value> {
    args.get(name)
}

fn arg_str(args: &HashMap<String, Value>, name: &str, filter: &str) -> Result<Option<String>> {
    match args.get(name) {
        None => Ok(None),
        Some(Value::String(s)) => Ok(Some(s.clone())),
        Some(other) => Err(Error::msg(format!(
            "Filter `{}` received an incorrect type for arg `{}`: got `{}` but expected String",
            filter, name, other
        ))),
    }
}

fn expect_string(v: &Value, filter: &str) -> Result<String> {
    match v {
        Value::String(s) => Ok(s.clone()),
        other => Err(Error::msg(format!(
            "Filter `{}` was called on an incorrect value: got `{}` but expected a String",
            filter, other
        ))),
    }
}

fn expect_array(v: &Value, filter: &str) -> Result<Vec<Value>> {
    match v {
        Value::Array(a) => Ok(a.clone()),
        other => Err(Error::msg(format!(
            "Filter `{}` was called on an incorrect value: got `{}` but expected an Array",
            filter, other
        ))),
    }
}

fn expect_f64(v: &Value, filter: &str) -> Result<f64> {
    match v {
        Value::Number(n) => n.as_f64().ok_or_else(|| Error::msg(format!("Filter `{}` received a bad number", filter))),
        other => Err(Error::msg(format!(
            "Filter `{}` was called on an incorrect value: got `{}` but expected a Number",
            filter, other
        ))),
    }
}

fn num_value(f: f64) -> Value {
    if f.fract() == 0.0 && f.abs() < 9.0e15 {
        Value::from(f as i64)
    } else {
        Value::from(f)
    }
}

fn float_value(f: f64) -> Value {
    serde_json::Number::from_f64(f).map(Value::Number).unwrap_or(Value::Null)
}

pub fn slugify(s: &str) -> String {
    let mut out = String::new();
    let mut prev_dash = true;
    let mut push = |c: char, out: &mut String, prev_dash: &mut bool| {
        if c.is_ascii_alphanumeric() {
            out.push(c.to_ascii_lowercase());
            *prev_dash = false;
        } else if !*prev_dash {
            out.push('-');
            *prev_dash = true;
        }
    };
    for c in s.chars() {
        if c.is_ascii() {
            push(c, &mut out, &mut prev_dash);
        } else {
            let t = super::deunicode::deunicode_char(c);
            for tc in t.chars() {
                push(tc, &mut out, &mut prev_dash);
            }
        }
    }
    while out.ends_with('-') {
        out.pop();
    }
    out
}

pub fn striptags(s: &str) -> String {
    // remove comments and tags
    let mut out = String::new();
    let b = s.as_bytes();
    let mut i = 0;
    while i < b.len() {
        if b[i] == b'<' {
            if b[i..].starts_with(b"<!--") {
                if let Some(end) = find_sub(&b[i + 4..], b"-->") {
                    i = i + 4 + end + 3;
                    continue;
                }
            }
            if let Some(end) = b[i + 1..].iter().position(|&c| c == b'>') {
                i = i + 1 + end + 1;
                continue;
            }
        }
        // copy one char
        let ch_len = utf8_len(b[i]);
        out.push_str(&s[i..i + ch_len]);
        i += ch_len;
    }
    out
}

fn utf8_len(first: u8) -> usize {
    if first < 0x80 {
        1
    } else if first >> 5 == 0b110 {
        2
    } else if first >> 4 == 0b1110 {
        3
    } else {
        4
    }
}

fn find_sub(hay: &[u8], needle: &[u8]) -> Option<usize> {
    if needle.len() > hay.len() {
        return None;
    }
    (0..=hay.len() - needle.len()).find(|&i| &hay[i..i + needle.len()] == needle)
}

pub fn escape_html(s: &str) -> String {
    let mut out = String::with_capacity(s.len());
    for c in s.chars() {
        match c {
            '&' => out.push_str("&amp;"),
            '<' => out.push_str("&lt;"),
            '>' => out.push_str("&gt;"),
            '"' => out.push_str("&quot;"),
            '\'' => out.push_str("&#x27;"),
            '/' => out.push_str("&#x2F;"),
            _ => out.push(c),
        }
    }
    out
}

fn urlencode(s: &str, strict: bool) -> String {
    let mut out = String::new();
    for &b in s.as_bytes() {
        let keep = b.is_ascii_alphanumeric() || b == b'-' || b == b'_' || b == b'.' || b == b'~' || (!strict && b == b'/');
        if keep {
            out.push(b as char);
        } else {
            out.push_str(&format!("%{:02X}", b));
        }
    }
    out
}

fn value_cmp(a: &Value, b: &Value) -> std::cmp::Ordering {
    use std::cmp::Ordering;
    match (a, b) {
        (Value::Number(x), Value::Number(y)) => x.as_f64().unwrap_or(0.0).partial_cmp(&y.as_f64().unwrap_or(0.0)).unwrap_or(Ordering::Equal),
        (Value::String(x), Value::String(y)) => x.cmp(y),
        (Value::Bool(x), Value::Bool(y)) => x.cmp(y),
        (Value::Array(x), Value::Array(y)) => {
            for (i, j) in x.iter().zip(y.iter()) {
                let o = value_cmp(i, j);
                if o != Ordering::Equal {
                    return o;
                }
            }
            x.len().cmp(&y.len())
        }
        _ => Ordering::Equal,
    }
}

pub fn get_attribute<'a>(v: &'a Value, attr: &str) -> Option<&'a Value> {
    let mut cur = v;
    for part in attr.split('.') {
        cur = match cur {
            Value::Object(o) => o.get(part)?,
            Value::Array(a) => a.get(part.parse::<usize>().ok()?)?,
            _ => return None,
        };
    }
    Some(cur)
}

pub fn parse_datetime(v: &Value) -> Result<chrono::DateTime<chrono::FixedOffset>> {
    use chrono::{DateTime, FixedOffset, NaiveDate, NaiveDateTime, TimeZone, Utc};
    match v {
        Value::Number(n) => {
            let ts = n.as_i64().ok_or_else(|| Error::msg("Filter `date` received a bad timestamp"))?;
            let dt = DateTime::<Utc>::from_timestamp(ts, 0).ok_or_else(|| Error::msg("Filter `date` received an invalid timestamp"))?;
            Ok(dt.fixed_offset())
        }
        Value::String(s) => {
            if s.contains('T') {
                if let Ok(dt) = DateTime::parse_from_rfc3339(s) {
                    return Ok(dt);
                }
                if let Ok(ndt) = NaiveDateTime::parse_from_str(s, "%Y-%m-%dT%H:%M:%S") {
                    return Ok(Utc.from_utc_datetime(&ndt).fixed_offset());
                }
                if let Ok(ndt) = NaiveDateTime::parse_from_str(s, "%Y-%m-%dT%H:%M:%S%.f") {
                    return Ok(Utc.from_utc_datetime(&ndt).fixed_offset());
                }
                Err(Error::msg(format!("Error parsing `{:?}` as rfc3339 date or naive datetime", s)))
            } else {
                match NaiveDate::parse_from_str(s, "%Y-%m-%d") {
                    Ok(d) => {
                        let ndt = d.and_hms_opt(0, 0, 0).unwrap();
                        Ok(FixedOffset::east_opt(0).unwrap().from_utc_datetime(&ndt))
                    }
                    Err(_) => Err(Error::msg(format!("Error parsing `{:?}` as YYYY-MM-DD date", s))),
                }
            }
        }
        other => Err(Error::msg(format!(
            "Filter `date` was called on an incorrect value: got `{}` but expected a String or Number",
            other
        ))),
    }
}

pub fn format_date(dt: &chrono::DateTime<chrono::FixedOffset>, fmt: &str) -> String {
    // chrono's format may panic on invalid specifiers when displayed; guard it.
    let items = chrono::format::StrftimeItems::new(fmt);
    let mut out = String::new();
    use std::fmt::Write;
    let formatted = dt.format_with_items(items);
    if write!(out, "{}", formatted).is_err() {
        return String::new();
    }
    out
}

pub fn register(t: &mut Tera) {
    // ---------------- filters ----------------
    t.register_filter("safe", |v, _| Ok(v.clone()));
    t.register_filter("as_str", |v, _| Ok(Value::String(render_value(v))));
    t.register_filter("length", |v, _| match v {
        Value::Array(a) => Ok(Value::from(a.len())),
        Value::Object(o) => Ok(Value::from(o.len())),
        Value::String(s) => Ok(Value::from(s.chars().count())),
        _ => Err(Error::msg("Filter `length` was used on a value that isn't an array, an object, or a string.")),
    });
    t.register_filter("lower", |v, _| Ok(Value::String(expect_string(v, "lower")?.to_lowercase())));
    t.register_filter("upper", |v, _| Ok(Value::String(expect_string(v, "upper")?.to_uppercase())));
    t.register_filter("trim", |v, _| Ok(Value::String(expect_string(v, "trim")?.trim().to_string())));
    t.register_filter("trim_start", |v, _| Ok(Value::String(expect_string(v, "trim_start")?.trim_start().to_string())));
    t.register_filter("trim_end", |v, _| Ok(Value::String(expect_string(v, "trim_end")?.trim_end().to_string())));
    t.register_filter("trim_start_matches", |v, a| {
        let s = expect_string(v, "trim_start_matches")?;
        let pat = arg_str(a, "pat", "trim_start_matches")?.ok_or_else(|| Error::msg("Filter `trim_start_matches` expected an arg called `pat`"))?;
        if pat.is_empty() {
            return Ok(Value::String(s));
        }
        Ok(Value::String(s.trim_start_matches(pat.as_str()).to_string()))
    });
    t.register_filter("trim_end_matches", |v, a| {
        let s = expect_string(v, "trim_end_matches")?;
        let pat = arg_str(a, "pat", "trim_end_matches")?.ok_or_else(|| Error::msg("Filter `trim_end_matches` expected an arg called `pat`"))?;
        if pat.is_empty() {
            return Ok(Value::String(s));
        }
        Ok(Value::String(s.trim_end_matches(pat.as_str()).to_string()))
    });
    t.register_filter("truncate", |v, a| {
        let s = expect_string(v, "truncate")?;
        let length = match arg(a, "length") {
            Some(Value::Number(n)) => n.as_u64().unwrap_or(255) as usize,
            _ => 255,
        };
        let end = arg_str(a, "end", "truncate")?.unwrap_or_else(|| "…".to_string());
        let chars: Vec<char> = s.chars().collect();
        if chars.len() <= length {
            return Ok(Value::String(s));
        }
        let mut out: String = chars[..length].iter().collect();
        out.push_str(&end);
        Ok(Value::String(out))
    });
    t.register_filter("striptags", |v, _| Ok(Value::String(striptags(&expect_string(v, "striptags")?))));
    t.register_filter("slugify", |v, _| Ok(Value::String(slugify(&expect_string(v, "slugify")?))));
    t.register_filter("capitalize", |v, _| {
        let s = expect_string(v, "capitalize")?;
        let mut c = s.chars();
        Ok(Value::String(match c.next() {
            Some(f) => f.to_uppercase().collect::<String>() + &c.as_str().to_lowercase(),
            None => String::new(),
        }))
    });
    t.register_filter("title", |v, _| {
        let s = expect_string(v, "title")?;
        let mut out = String::new();
        let mut in_word = false;
        for c in s.chars() {
            let is_word = c.is_alphanumeric() || c == '_' || c == '\'';
            if is_word {
                if !in_word {
                    out.extend(c.to_uppercase());
                    in_word = true;
                } else {
                    out.extend(c.to_lowercase());
                }
            } else {
                in_word = false;
                out.push(c);
            }
        }
        Ok(Value::String(out))
    });
    t.register_filter("wordcount", |v, _| Ok(Value::from(expect_string(v, "wordcount")?.split_whitespace().count())));
    t.register_filter("replace", |v, a| {
        let s = expect_string(v, "replace")?;
        let from = arg_str(a, "from", "replace")?.ok_or_else(|| Error::msg("Filter `replace` expected an arg called `from`"))?;
        let to = arg_str(a, "to", "replace")?.ok_or_else(|| Error::msg("Filter `replace` expected an arg called `to`"))?;
        Ok(Value::String(s.replace(&from, &to)))
    });
    t.register_filter("addslashes", |v, _| {
        let s = expect_string(v, "addslashes")?;
        Ok(Value::String(s.replace('\\', "\\\\").replace('"', "\\\"").replace('\'', "\\'")))
    });
    t.register_filter("linebreaksbr", |v, _| {
        let s = expect_string(v, "linebreaksbr")?;
        Ok(Value::String(s.replace("\r\n", "<br>").replace('\n', "<br>")))
    });
    t.register_filter("spaceless", |v, _| {
        let s = expect_string(v, "spaceless")?;
        let re = regex::Regex::new(r">\s+<").unwrap();
        Ok(Value::String(re.replace_all(&s, "><").to_string()))
    });
    t.register_filter("indent", |v, a| {
        let s = expect_string(v, "indent")?;
        let prefix = arg_str(a, "prefix", "indent")?.unwrap_or_else(|| "    ".to_string());
        let first = arg(a, "first").map(is_truthy).unwrap_or(false);
        let blank = arg(a, "blank").map(is_truthy).unwrap_or(false);
        let mut out = String::new();
        for (i, line) in s.split('\n').enumerate() {
            if i > 0 {
                out.push('\n');
            }
            if (i == 0 && !first) || (line.trim().is_empty() && !blank) {
                out.push_str(line);
            } else {
                out.push_str(&prefix);
                out.push_str(line);
            }
        }
        Ok(Value::String(out))
    });
    t.register_filter("escape", |v, _| Ok(Value::String(escape_html(&expect_string(v, "escape")?))));
    t.register_filter("escape_xml", |v, _| {
        let s = expect_string(v, "escape_xml")?;
        let mut out = String::new();
        for c in s.chars() {
            match c {
                '&' => out.push_str("&amp;"),
                '<' => out.push_str("&lt;"),
                '>' => out.push_str("&gt;"),
                '"' => out.push_str("&quot;"),
                '\'' => out.push_str("&apos;"),
                _ => out.push(c),
            }
        }
        Ok(Value::String(out))
    });
    t.register_filter("urlencode", |v, _| Ok(Value::String(urlencode(&expect_string(v, "urlencode")?, false))));
    t.register_filter("urlencode_strict", |v, _| Ok(Value::String(urlencode(&expect_string(v, "urlencode_strict")?, true))));
    t.register_filter("split", |v, a| {
        let s = expect_string(v, "split")?;
        let pat = arg_str(a, "pat", "split")?.ok_or_else(|| Error::msg("Filter `split` expected an arg called `pat`"))?;
        Ok(Value::Array(s.split(pat.as_str()).map(|p| Value::String(p.to_string())).collect()))
    });
    t.register_filter("join", |v, a| {
        let arr = expect_array(v, "join")?;
        let sep = arg_str(a, "sep", "join")?.unwrap_or_default();
        Ok(Value::String(arr.iter().map(render_value).collect::<Vec<_>>().join(&sep)))
    });
    t.register_filter("first", |v, _| Ok(expect_array(v, "first")?.first().cloned().unwrap_or(Value::Null)));
    t.register_filter("last", |v, _| Ok(expect_array(v, "last")?.last().cloned().unwrap_or(Value::Null)));
    t.register_filter("nth", |v, a| {
        let arr = expect_array(v, "nth")?;
        let n = match arg(a, "n") {
            Some(Value::Number(n)) => n.as_u64().unwrap_or(0) as usize,
            _ => return Err(Error::msg("Filter `nth` expected an arg called `n`")),
        };
        Ok(arr.get(n).cloned().unwrap_or(Value::Null))
    });
    t.register_filter("reverse", |v, _| match v {
        Value::Array(a) => Ok(Value::Array(a.iter().rev().cloned().collect())),
        Value::String(s) => Ok(Value::String(s.chars().rev().collect())),
        _ => Err(Error::msg("Filter `reverse` received an incorrect type: expected an array or a string")),
    });
    t.register_filter("sort", |v, a| {
        let mut arr = expect_array(v, "sort")?;
        let attr = arg_str(a, "attribute", "sort")?;
        match attr {
            Some(attr) => arr.sort_by(|x, y| {
                let xa = get_attribute(x, &attr).cloned().unwrap_or(Value::Null);
                let ya = get_attribute(y, &attr).cloned().unwrap_or(Value::Null);
                value_cmp(&xa, &ya)
            }),
            None => arr.sort_by(value_cmp),
        }
        Ok(Value::Array(arr))
    });
    t.register_filter("unique", |v, a| {
        let arr = expect_array(v, "unique")?;
        let attr = arg_str(a, "attribute", "unique")?;
        let case_sensitive = arg(a, "case_sensitive").map(is_truthy).unwrap_or(false);
        let mut seen: Vec<Value> = Vec::new();
        let mut out = Vec::new();
        for item in arr {
            let key = match &attr {
                Some(at) => get_attribute(&item, at).cloned().unwrap_or(Value::Null),
                None => item.clone(),
            };
            let key = match (&key, case_sensitive) {
                (Value::String(s), false) => Value::String(s.to_lowercase()),
                _ => key,
            };
            if !seen.contains(&key) {
                seen.push(key);
                out.push(item);
            }
        }
        Ok(Value::Array(out))
    });
    t.register_filter("slice", |v, a| {
        let arr = expect_array(v, "slice")?;
        let len = arr.len() as i64;
        let norm = |x: i64| -> usize {
            let i = if x < 0 { len + x } else { x };
            i.clamp(0, len) as usize
        };
        let start = match arg(a, "start") {
            Some(Value::Number(n)) => norm(n.as_i64().unwrap_or(0)),
            _ => 0,
        };
        let end = match arg(a, "end") {
            Some(Value::Number(n)) => norm(n.as_i64().unwrap_or(len)),
            _ => len as usize,
        };
        if start >= end {
            return Ok(Value::Array(vec![]));
        }
        Ok(Value::Array(arr[start..end].to_vec()))
    });
    t.register_filter("concat", |v, a| {
        let mut arr = expect_array(v, "concat")?;
        match arg(a, "with") {
            Some(Value::Array(w)) => arr.extend(w.iter().cloned()),
            Some(other) => arr.push(other.clone()),
            None => return Err(Error::msg("Filter `concat` expected an arg called `with`")),
        }
        Ok(Value::Array(arr))
    });
    t.register_filter("map", |v, a| {
        let arr = expect_array(v, "map")?;
        let attr = arg_str(a, "attribute", "map")?.ok_or_else(|| Error::msg("Filter `map` expected an arg called `attribute`"))?;
        Ok(Value::Array(arr.iter().filter_map(|i| get_attribute(i, &attr).cloned()).collect()))
    });
    t.register_filter("filter", |v, a| {
        let arr = expect_array(v, "filter")?;
        let attr = arg_str(a, "attribute", "filter")?.ok_or_else(|| Error::msg("Filter `filter` expected an arg called `attribute`"))?;
        let value = arg(a, "value").cloned();
        Ok(Value::Array(
            arr.into_iter()
                .filter(|i| {
                    let got = get_attribute(i, &attr);
                    match &value {
                        Some(val) => got == Some(val),
                        None => got.map(|g| g.is_null()).unwrap_or(true),
                    }
                })
                .collect(),
        ))
    });
    t.register_filter("group_by", |v, a| {
        let arr = expect_array(v, "group_by")?;
        let attr = arg_str(a, "attribute", "group_by")?.ok_or_else(|| Error::msg("Filter `group_by` expected an arg called `attribute`"))?;
        let mut groups: Map<String, Value> = Map::new();
        for item in arr {
            if let Some(k) = get_attribute(&item, &attr) {
                let key = match k {
                    Value::String(s) => s.clone(),
                    other => render_value(other),
                };
                groups.entry(key).or_insert_with(|| Value::Array(vec![])).as_array_mut().unwrap().push(item.clone());
            }
        }
        Ok(Value::Object(groups))
    });
    t.register_filter("get", |v, a| {
        let key = arg_str(a, "key", "get")?.ok_or_else(|| Error::msg("Filter `get` expected an arg called `key`"))?;
        match v {
            Value::Object(o) => match o.get(&key) {
                Some(x) => Ok(x.clone()),
                None => match arg(a, "default") {
                    Some(d) => Ok(d.clone()),
                    None => Err(Error::msg(format!("Filter `get` tried to get key `{}` but it wasn't found", key))),
                },
            },
            _ => Err(Error::msg("Filter `get` was used on a value that isn't an object")),
        }
    });
    t.register_filter("json_encode", |v, a| {
        let pretty = arg(a, "pretty").map(is_truthy).unwrap_or(false);
        let s = if pretty { serde_json::to_string_pretty(v) } else { serde_json::to_string(v) }.map_err(|e| Error::msg(e.to_string()))?;
        Ok(Value::String(s))
    });
    t.register_filter("abs", |v, _| match v {
        Value::Number(n) => {
            if let Some(i) = n.as_i64() {
                Ok(Value::from(i.abs()))
            } else {
                Ok(float_value(n.as_f64().unwrap_or(0.0).abs()))
            }
        }
        _ => Err(Error::msg("Filter `abs` was used on a value that isn't a number")),
    });
    t.register_filter("round", |v, a| {
        let num = expect_f64(v, "round")?;
        let method = arg_str(a, "method", "round")?.unwrap_or_else(|| "common".to_string());
        let precision = match arg(a, "precision") {
            Some(Value::Number(n)) => n.as_i64().unwrap_or(0) as i32,
            _ => 0,
        };
        let multiplier = if precision == 0 { 1.0 } else { 10f64.powi(precision) };
        let r = match method.as_str() {
            "common" => (multiplier * num).round() / multiplier,
            "ceil" => (multiplier * num).ceil() / multiplier,
            "floor" => (multiplier * num).floor() / multiplier,
            _ => return Err(Error::msg(format!("Filter `round` received an incorrect value for arg `method`: got `{}`, only common, ceil and floor are allowed", method))),
        };
        Ok(float_value(r))
    });
    t.register_filter("int", |v, a| {
        let default = match arg(a, "default") {
            Some(Value::Number(n)) => n.as_i64().unwrap_or(0),
            _ => 0,
        };
        let base = match arg(a, "base") {
            Some(Value::Number(n)) => n.as_u64().unwrap_or(10) as u32,
            _ => 10,
        };
        match v {
            Value::Number(n) => Ok(Value::from(n.as_i64().unwrap_or_else(|| n.as_f64().unwrap_or(0.0) as i64))),
            Value::String(s) => {
                let s = s.trim();
                let s2 = if base == 16 { s.trim_start_matches("0x").trim_start_matches("0X") } else if base == 2 { s.trim_start_matches("0b") } else if base == 8 { s.trim_start_matches("0o") } else { s };
                match i64::from_str_radix(s2, base) {
                    Ok(i) => Ok(Value::from(i)),
                    Err(_) => match s.parse::<f64>() {
                        Ok(f) => Ok(Value::from(f as i64)),
                        Err(_) => Ok(Value::from(default)),
                    },
                }
            }
            _ => Err(Error::msg("Filter `int` received an unexpected type")),
        }
    });
    t.register_filter("float", |v, a| {
        let default = arg(a, "default").and_then(|d| d.as_f64()).unwrap_or(0.0);
        match v {
            Value::Number(n) => Ok(float_value(n.as_f64().unwrap_or(0.0))),
            Value::String(s) => Ok(float_value(s.trim().parse::<f64>().unwrap_or(default))),
            _ => Err(Error::msg("Filter `float` received an unexpected type")),
        }
    });
    t.register_filter("filesizeformat", |v, _| {
        let n = expect_f64(v, "filesizeformat")?;
        let units = ["B", "kB", "MB", "GB", "TB", "PB", "EB"];
        let mut size = n;
        let mut i = 0;
        while size >= 1024.0 && i < units.len() - 1 {
            size /= 1024.0;
            i += 1;
        }
        let s = if size.fract() == 0.0 { format!("{}", size as i64) } else { format!("{:.2}", size) };
        Ok(Value::String(format!("{} {}", s, units[i])))
    });
    t.register_filter("pluralize", |v, a| {
        let n = expect_f64(v, "pluralize")?;
        let singular = arg_str(a, "singular", "pluralize")?.unwrap_or_default();
        let plural = arg_str(a, "plural", "pluralize")?.unwrap_or_else(|| "s".to_string());
        Ok(Value::String(if (n - 1.0).abs() < f64::EPSILON { singular } else { plural }))
    });
    t.register_filter("default", |v, a| {
        let d = arg(a, "value").cloned().ok_or_else(|| Error::msg("Filter `default` expected an arg called `value`"))?;
        Ok(if is_truthy(v) { v.clone() } else { d })
    });
    t.register_filter("date", |v, a| {
        let fmt = arg_str(a, "format", "date")?.unwrap_or_else(|| "%Y-%m-%d".to_string());
        let dt = parse_datetime(v)?;
        Ok(Value::String(format_date(&dt, &fmt)))
    });

    // ---------------- functions ----------------
    t.register_function("range", |a| {
        let start = a.get("start").and_then(|v| v.as_i64()).unwrap_or(0);
        let end = a.get("end").and_then(|v| v.as_i64()).ok_or_else(|| Error::msg("Function `range` was called without a `end` argument"))?;
        let step = a.get("step_by").and_then(|v| v.as_i64()).unwrap_or(1);
        if start > end {
            return Err(Error::msg("Function `range` was called with a `start` argument greater than the `end` one"));
        }
        let mut out = Vec::new();
        let mut i = start;
        while i < end {
            out.push(Value::from(i));
            i += step.max(1);
        }
        Ok(Value::Array(out))
    });
    t.register_function("now", |a| {
        let timestamp = a.get("timestamp").map(is_truthy).unwrap_or(false);
        let utc = a.get("utc").map(is_truthy).unwrap_or(false);
        let now = chrono::Utc::now();
        if timestamp {
            return Ok(Value::from(now.timestamp()));
        }
        if utc {
            Ok(Value::String(now.to_rfc3339()))
        } else {
            Ok(Value::String(chrono::Local::now().to_rfc3339()))
        }
    });
    t.register_function("throw", |a| {
        let msg = a.get("message").map(render_value).unwrap_or_default();
        Err(Error::msg(msg))
    });
    t.register_function("get_random", |a| {
        let start = a.get("start").and_then(|v| v.as_i64()).unwrap_or(0);
        let end = a.get("end").and_then(|v| v.as_i64()).ok_or_else(|| Error::msg("Function `get_random` was called without a `end` argument"))?;
        let nanos = std::time::SystemTime::now().duration_since(std::time::UNIX_EPOCH).map(|d| d.subsec_nanos() as i64).unwrap_or(0);
        let range = (end - start).max(1);
        Ok(Value::from(start + nanos % range))
    });
    t.register_function("get_env", |a| {
        let name = a.get("name").and_then(|v| v.as_str()).ok_or_else(|| Error::msg("Function `get_env` was called without a `name` argument"))?;
        match std::env::var(name) {
            Ok(v) => Ok(Value::String(v)),
            Err(_) => match a.get("default") {
                Some(d) => Ok(d.clone()),
                None => Err(Error::msg(format!("Environment variable `{}` not found", name))),
            },
        }
    });

    // ---------------- tests ----------------
    t.register_tester("defined", |v, _| Ok(v.is_some()));
    t.register_tester("undefined", |v, _| Ok(v.is_none()));
    t.register_tester("string", |v, _| Ok(matches!(v, Some(Value::String(_)))));
    t.register_tester("number", |v, _| Ok(matches!(v, Some(Value::Number(_)))));
    t.register_tester("object", |v, _| Ok(matches!(v, Some(Value::Object(_)))));
    t.register_tester("iterable", |v, _| Ok(matches!(v, Some(Value::Array(_)) | Some(Value::Object(_)))));
    t.register_tester("odd", |v, _| Ok(v.and_then(|x| x.as_i64()).map(|i| i % 2 != 0).unwrap_or(false)));
    t.register_tester("even", |v, _| Ok(v.and_then(|x| x.as_i64()).map(|i| i % 2 == 0).unwrap_or(false)));
    t.register_tester("divisibleby", |v, args| {
        let n = v.and_then(|x| x.as_i64()).ok_or_else(|| Error::msg("Tester `divisibleby` was called on an undefined variable"))?;
        let d = args.first().and_then(|x| x.as_i64()).ok_or_else(|| Error::msg("Tester `divisibleby` expects a number argument"))?;
        Ok(d != 0 && n % d == 0)
    });
    t.register_tester("starting_with", |v, args| {
        let s = match v {
            Some(Value::String(s)) => s,
            _ => return Err(Error::msg("Tester `starting_with` was called on an undefined variable")),
        };
        let p = args.first().and_then(|x| x.as_str()).ok_or_else(|| Error::msg("Tester `starting_with` expects a string argument"))?;
        Ok(s.starts_with(p))
    });
    t.register_tester("ending_with", |v, args| {
        let s = match v {
            Some(Value::String(s)) => s,
            _ => return Err(Error::msg("Tester `ending_with` was called on an undefined variable")),
        };
        let p = args.first().and_then(|x| x.as_str()).ok_or_else(|| Error::msg("Tester `ending_with` expects a string argument"))?;
        Ok(s.ends_with(p))
    });
    t.register_tester("containing", |v, args| {
        let needle = args.first().ok_or_else(|| Error::msg("Tester `containing` expects an argument"))?;
        match v {
            Some(Value::String(s)) => Ok(match needle {
                Value::String(n) => s.contains(n.as_str()),
                _ => false,
            }),
            Some(Value::Array(a)) => Ok(a.contains(needle)),
            Some(Value::Object(o)) => Ok(match needle {
                Value::String(n) => o.contains_key(n),
                _ => false,
            }),
            _ => Err(Error::msg("Tester `containing` was called on an undefined variable")),
        }
    });
    t.register_tester("matching", |v, args| {
        let s = match v {
            Some(Value::String(s)) => s,
            _ => return Err(Error::msg("Tester `matching` was called on an undefined variable")),
        };
