    out.push_str(&format!("default_author: {}\n", yaml_scalar(&m.default_author)));
    out.push_str(&format!("authors_title: {}\n", yaml_scalar(&m.authors_title)));
    out.push_str(&format!("enable_search: {}\n", m.enable_search));
