impl CliOverrides {
    pub fn apply(&self, m: &mut Marmite) {
        if let Some(v) = &self.name {
            m.name = v.clone();
        }
        if let Some(v) = &self.tagline {
            m.tagline = v.clone();
        }
        if let Some(v) = &self.url {
            m.url = v.clone();
        }
        if let Some(v) = self.https {
            m.https = Some(v);
        }
        if let Some(v) = &self.footer {
            m.footer = v.clone();
        }
        if let Some(v) = &self.language {
            m.language = v.clone();
        }
        if let Some(v) = self.pagination {
            m.pagination = v;
        }
        if let Some(v) = self.enable_search {
            m.enable_search = v;
        }
        if let Some(v) = self.enable_related_content {
            m.enable_related_content = v;
        }
        if let Some(v) = &self.content_path {
            m.content_path = v.clone();
        }
        if let Some(v) = &self.templates_path {
            m.templates_path = v.clone();
        }
        if let Some(v) = &self.static_path {
            m.static_path = v.clone();
        }
        if let Some(v) = &self.media_path {
            m.media_path = v.clone();
        }
        if let Some(v) = &self.default_date_format {
            m.default_date_format = v.clone();
        }
        if let Some(v) = &self.colorscheme {
            let mut extra = match m.extra.take() {
                Some(serde_json::Value::Object(o)) => o,
                _ => serde_json::Map::new(),
            };
            extra.insert("colorscheme".into(), serde_json::Value::String(v.clone()));
            m.extra = Some(serde_json::Value::Object(extra));
        }
        if let Some(v) = self.toc {
            m.toc = v;
        }
        if let Some(v) = self.json_feed {
            m.json_feed = v;
        }
        if let Some(v) = self.show_next_prev_links {
            m.show_next_prev_links = v;
        }
        if let Some(v) = self.publish_md {
            m.publish_md = v;
        }
        if let Some(v) = &self.source_repository {
            m.source_repository = Some(v.clone());
        }
        if let Some(v) = &self.image_provider {
            m.image_provider = Some(v.clone());
