/// Serialize a string scalar roughly like serde_yaml does.
pub fn yaml_scalar(s: &str) -> String {
    match serde_yaml::to_string(&s) {
        Ok(y) => y.trim_end_matches('\n').to_string(),
        Err(_) => format!("'{}'", s),
    }
}

