    TEMPLATES.iter().find(|f| f.name == name).and_then(|f| std::str::from_utf8(f.data).ok())
}

/// Writes the embedded static files into `static_dir`, logging each file.
pub fn generate_static(static_dir: &std::path::Path) {
    for f in STATIC {
        let dest = static_dir.join(f.name);
        if let Some(parent) = dest.parent() {
            let _ = std::fs::create_dir_all(parent);
        }
        match std::fs::write(&dest, f.data) {
            Ok(_) => log::info!("Generated {}", dest.display()),
            Err(e) => log::error!("Failed to write {}: {}", dest.display(), e),
        }
    }
}
