{"command":"cat > /workspace/src/site.rs <<'EOF'
//! Site generation.

use crate::config::{CliOverrides, Marmite};
use crate::content::{self, Content, Fragments};
use crate::tera::{Context, Tera};
use indexmap::IndexMap;
use serde::Serialize;
use serde_json::Value;
use std::collections::HashMap;
use std::path::{Path, PathBuf};
use std::sync::{Arc, Mutex};

#[derive(Debug, Clone, Serialize)]
pub struct GroupedContent {
    pub kind: String,
    pub map: IndexMap<String, Vec<Content>>,
}

impl GroupedContent {
    fn new(kind: &str) -> Self {
        GroupedContent { kind: kind.to_string(), map: IndexMap::new() }
    }
    fn insert(&mut self, key: &str, c: &Content) {
        self.map.entry(key.to_string()).or_default().push(c.clone());
    }
    /// Sorted entries: archive by name desc, others by count desc then name asc.
    pub fn sorted(&self) -> Vec<(String, Vec<Content>)> {
        let mut entries: Vec<(String, Vec<Content>)> = self.map.iter().map(|(k, v)| (k.clone(), v.clone())).collect();
        if self.kind == "Archive" {
            entries.sort_by(|a, b| b.0.cmp(&a.0));
        } else {
            entries.sort_by(|a, b| b.1.len().cmp(&a.1.len()).then_with(|| a.0.cmp(&b.0)));
        }
        entries
    }
}

#[derive(Debug, Clone, Serialize, Default)]
pub struct GeneratedUrls {
    pub posts: Vec<String>,
    pub pages: Vec<String>,
    pub tags: Vec<String>,
    pub authors: Vec<String>,
    pub series: Vec<String>,
    pub streams: Vec<String>,
    pub archives: Vec<String>,
    pub feeds: Vec<String>,
    pub pagination: Vec<String>,
    pub file_mappings: Vec<String>,
    pub misc: Vec<String>,
}

#[derive(Debug, Clone, Serialize)]
pub struct SiteData {
    pub site: Marmite,
    pub posts: Vec<Content>,
    pub pages: Vec<Content>,
    pub tag: GroupedContent,
    pub archive: GroupedContent,
    pub author: GroupedContent,
    pub stream: GroupedContent,
    pub series: GroupedContent,
    pub latest_timestamp: Option<i64>,
    pub config_path: String,
    pub force_render: bool,
    pub generated_urls: GeneratedUrls,
    pub galleries: IndexMap<String, Value>,
}

pub struct BuildOptions {
    pub input: PathBuf,
    pub output: PathBuf,
    pub config_path: PathBuf,
    pub overrides: CliOverrides,
    pub force: bool,
    pub cli_theme: Option<String>,
}

pub fn load_config(config_path: &Path, overrides: &CliOverrides) -> Marmite {
    let mut config = match std::fs::read_to_string(config_path) {
        Ok(s) => match serde_yaml::from_str::<Marmite>(&s) {
            Ok(c) => {
                log::info!("Config loaded from: {}", config_path.display());
                c
            }
            Err(e) => {
                log::error!("Failed to parse config file {}: {}", config_path.display(), e);
                std::process::exit(1);
            }
        },
        Err(e) => {
            log::info!("Unable to read '{}', assuming defaults.: {:?}", config_path.display(), e);
            log::info!("Config loaded from: defaults");
            Marmite::default()
        }
    };
    overrides.apply(&mut config);
    config
}

fn display_path(p: &Path) -> String {
    p.to_string_lossy().to_string()
}

fn join_display(base: &Path, rel: &str) -> String {
    display_path(&base.join(rel))
}

/// Returns the content directory: `input/content_path` if it exists, otherwise `input`.
pub fn content_dir(input: &Path, config: &Marmite) -> PathBuf {
    let c = input.join(&config.content_path);
    if c.is_dir() {
        c
    } else {
        input.to_path_buf()
    }
}

fn read_fragment(dir: &Path, name: &str) -> Option<String> {
    std::fs::read_to_string(dir.join(name)).ok()
}

pub struct Site {
    pub data: SiteData,
    pub tera: Tera,
    pub input: PathBuf,
    pub output: PathBuf,
    pub content_dir: PathBuf,
    pub fragments_dir: PathBuf,
    pub start_time: std::time::Instant,
    pub build_timestamp: i64,
    pub generated_at: chrono::DateTime<chrono::Utc>,
}

fn protocol_url(url: &str, https: Option<bool>) -> String {
    if url.contains("://") {
        url.to_string()
    } else if https == Some(true) {
        format!("https://{}", url)
    } else {
        format!("http://{}", url)
    }
}

pub fn url_for(config: &Marmite, path: &str, abs: bool) -> String {
    if path.starts_with("http://") || path.starts_with("https://") {
        return path.to_string();
    }
    let path = path.trim_start_matches('/');
    let base = if abs {
        config.url.trim_end_matches('/').to_string()
    } else {
        // path component of the url
        let u = config.url.trim_end_matches('/');
        let without_scheme = match u.find("://") {
            Some(i) => &u[i + 3..],
            None => u,
        };
        match without_scheme.find('/') {
            Some(i) => without_scheme[i..].to_string(),
            None => String::new(),
        }
    };
    format!("{}/{}", base, path)
}

pub fn build(opts: BuildOptions) -> Result<Site, i32> {
    let start = std::time::Instant::now();
    let generated_at = chrono::Utc::now();
    let build_timestamp = generated_at.timestamp();
    let mut config = load_config(&opts.config_path, &opts.overrides);
    if let Some(t) = &opts.cli_theme {
        config.theme = Some(t.clone());
    }
    let input = opts.input.clone();
    let output = opts.output.clone();
    let content_dir = content_dir(&input, &config);
    let fragments_dir = input.join(&config.content_path);

    // galleries
    let gallery_dir = content_dir.join(&config.media_path).join(&config.gallery_path);
    log::info!("Processing galleries from: {}", gallery_dir.display());
    if !gallery_dir.is_dir() {
        log::info!("Gallery directory does not exist: {}", gallery_dir.display());
    }

    if let Err(e) = std::fs::create_dir_all(&output) {
        log::error!("Unable to create output directory {}: {}", output.display(), e);
        return Err(1);
    }

    // previous build timestamp
    let previous_timestamp: Option<i64> = std::fs::read_to_string(output.join("marmite.json"))
        .ok()
        .and_then(|s| serde_json::from_str::<Value>(&s).ok())
        .and_then(|v| v.get("timestamp").and_then(|t| t.as_i64()));

    // static files
    let static_out = output.join("static");
    let theme_dir = config.theme.as_ref().map(|t| input.join(t));
    let input_static = match &theme_dir {
        Some(td) if td.join(&config.static_path).is_dir() => Some(td.join(&config.static_path)),
        _ => {
            let s = input.join(&config.static_path);
            if s.is_dir() {
                Some(s)
            } else {
                None
            }
        }
    };
    match &input_static {
        Some(s) => {
            copy_dir_recursive(s, &static_out);
            log::info!("Copied '{}' to '{}/'", s.display(), output.display());
        }
        None => {
            crate::embedded::generate_static(&static_out);
        }
    }
    // media
    let media_in = content_dir.join(&config.media_path);
    if media_in.is_dir() {
        copy_dir_recursive(&media_in, &output.join(&config.media_path));
        log::info!("Copied '{}' to '{}/'", media_in.display(), output.display());
    }
    // custom files
    for name in ["custom.css", "custom.js"] {
        let src = if input.join(name).is_file() { input.join(name) } else { static_out.join(name) };
        let dest = static_out.join(name);
        if src.is_file() {
            if src != dest {
                let _ = std::fs::copy(&src, &dest);
            } else {
                // copying a file onto itself truncates it (matches original behaviour)
                let _ = std::fs::write(&dest, b"");
            }
            log::info!("Copied {} to {}", src.display(), dest.display());
        }
    }
    {
        let src = if input.join("favicon.ico").is_file() { input.join("favicon.ico") } else { static_out.join("favicon.ico") };
        let dest = static_out.join("favicon.ico");
        if src.is_file() {
            if src != dest {
                let _ = std::fs::copy(&src, &dest);
            } else {
                let _ = std::fs::write(&dest, b"");
            }
            log::info!("Copied {} to {}", src.display(), dest.display());
        }
    }
    {
        let src = if input.join("robots.txt").is_file() { input.join("robots.txt") } else { static_out.join("robots.txt") };
        let dest = output.join("robots.txt");
        if src.is_file() {
            let _ = std::fs::copy(&src, &dest);
            log::info!("Copied {} to {}", src.display(), dest.display());
        }
    }
    // file mappings
    let mut file_mapping_urls = Vec::new();
    for fm in &config.file_mapping {
        let src = input.join(&fm.source);
        let dest = output.join(&fm.dest);
        if src.is_file() {
            if let Some(p) = dest.parent() {
                let _ = std::fs::create_dir_all(p);
            }
            if std::fs::copy(&src, &dest).is_ok() {
                log::info!("Copied {} to {}", src.display(), dest.display());
                file_mapping_urls.push(fm.dest.clone());
            }
        } else if src.is_dir() {
            copy_dir_recursive(&src, &dest);
            log::info!("Copied '{}' to '{}'", src.display(), dest.display());
            file_mapping_urls.push(fm.dest.clone());
        }
    }

    // fragments
    let fragments = Fragments {
        markdown_header: read_fragment(&fragments_dir, "_markdown_header.md").unwrap_or_default(),
        markdown_footer: read_fragment(&fragments_dir, "_markdown_footer.md").unwrap_or_default(),
        references: read_fragment(&fragments_dir, "_references.md").unwrap_or_default(),
    };

    // collect content
    let mut files: Vec<PathBuf> = Vec::new();
    for entry in walkdir::WalkDir::new(&content_dir).sort_by_file_name().into_iter().filter_map(|e| e.ok()) {
        let p = entry.path();
        if !p.is_file() {
            continue;
        }
        if p.extension().map(|e| e == "md").unwrap_or(false) {
            let name = p.file_name().map(|n| n.to_string_lossy().to_string()).unwrap_or_default();
            if name.starts_with('_') {
                continue;
            }
            files.push(p.to_path_buf());
        }
    }
    let mut posts: Vec<Content> = Vec::new();
    let mut pages: Vec<Content> = Vec::new();
    for f in &files {
        let raw = match std::fs::read_to_string(f) {
            Ok(r) => r,
            Err(e) => {
                log::error!("Failed to read {}: {}", f.display(), e);
                continue;
            }
        };
        match content::build_content(f, &raw, &config, &fragments, &display_path(f)) {
            Ok(c) => {
                if c.date.is_some() {
                    posts.push(c);
                } else {
                    pages.push(c);
                }
            }
            Err(e) => {
                if e.starts_with("ERROR: Invalid date format") {
                    log::error!(target: "marmite::content", "{}", e);
                    return Err(1);
                }
                log::error!("Failed to process content: {:?}", e);
            }
        }
    }
    // sort posts: pinned first, then date desc (stable)
    posts.sort_by(|a, b| b.date.cmp(&a.date));
    posts.sort_by(|a, b| b.pinned.cmp(&a.pinned));

    // groups
    let mut tag = GroupedContent::new("Tag");
    let mut archive = GroupedContent::new("Archive");
    let mut author = GroupedContent::new("Author");
    let mut stream = GroupedContent::new("Stream");
    let mut series = GroupedContent::new("Series");
    for p in &posts {
        for t in &p.tags {
            tag.insert(t, p);
            let s = content::slugify(t);
            if s != *t {
                tag.insert(&s, p);
            }
        }
        if let Some(d) = p.date {
            archive.insert(&d.format("%Y").to_string(), p);
        }
        for a in &p.authors {
            author.insert(a, p);
        }
        if let Some(s) = &p.stream {
            stream.insert(s, p);
        }
        if let Some(s) = &p.series {
            series.insert(s, p);
        }
    }
    // series items sorted ascending by date
    for (_, items) in series.map.iter_mut() {
        items.sort_by(|a, b| a.date.cmp(&b.date));
    }

    // back links
    let all_slugs: Vec<String> = posts.iter().chain(pages.iter()).map(|c| c.slug.clone()).collect();
    let mut backlinks: HashMap<String, Vec<Content>> = HashMap::new();
    for c in posts.iter().chain(pages.iter()) {
        if let Some(links) = &c.links_to {
            let mut seen = std::collections::HashSet::new();
            for l in links {
                if all_slugs.contains(l) && seen.insert(l.clone()) {
                    backlinks.entry(l.clone()).or_default().push(c.clone());
                }
            }
        }
    }
    for c in posts.iter_mut().chain(pages.iter_mut()) {
        if let Some(b) = backlinks.get(&c.slug) {
            c.back_links = b.clone();
        }
    }
    // next / previous within stream
    {
        let snapshot = posts.clone();
        for c in posts.iter_mut() {
            let same: Vec<&Content> = snapshot.iter().filter(|o| o.stream == c.stream).collect();
            if let Some(idx) = same.iter().position(|o| o.slug == c.slug) {
                if idx > 0 {
                    c.next = Some(Box::new(same[idx - 1].clone()));
                }
                if idx + 1 < same.len() {
                    c.previous = Some(Box::new(same[idx + 1].clone()));
                }
            }
        }
    }
    // propagate back_links/next/prev into the groups
    let by_slug: HashMap<String, Content> = posts.iter().chain(pages.iter()).map(|c| (c.slug.clone(), c.clone())).collect();
    for g in [&mut tag, &mut archive, &mut author, &mut stream, &mut series] {
        for (_, items) in g.map.iter_mut() {
            for it in items.iter_mut() {
                if let Some(full) = by_slug.get(&it.slug) {
                    it.back_links = full.back_links.clone();
                    it.next = full.next.clone();
                    it.previous = full.previous.clone();
                }
            }
        }
    }

    // templates
    let mut tera = Tera::new();
    for t in crate::embedded::TEMPLATES {
        let src = std::str::from_utf8(t.data).unwrap_or("");
        if let Err(e) = tera.add_raw_template(t.name, src) {
            log::error!("Failed to load embedded template {}: {}", t.name, e.msg);
        }
    }
    for s in crate::embedded::SHORTCODES {
        let src = std::str::from_utf8(s.data).unwrap_or("");
        let _ = tera.add_raw_template(&format!("shortcodes/{}", s.name), src);
    }
    let templates_dir = match &theme_dir {
        Some(td) if td.join(&config.templates_path).is_dir() => Some(td.join(&config.templates_path)),
        _ => {
            let t = input.join(&config.templates_path);
            if t.is_dir() {
                Some(t)
            } else {
                None
            }
        }
    };
    let mut templates_newest: Option<i64> = None;
    if let Some(td) = &templates_dir {
        for entry in walkdir::WalkDir::new(td).sort_by_file_name().into_iter().filter_map(|e| e.ok()) {
            let p = entry.path();
            if !p.is_file() {
                continue;
            }
            if let Ok(m) = std::fs::metadata(p).and_then(|m| m.modified()) {
                if let Ok(d) = m.duration_since(std::time::UNIX_EPOCH) {
                    let t = d.as_secs() as i64;
                    templates_newest = Some(templates_newest.map_or(t, |n| n.max(t)));
                }
            }
            let rel = p.strip_prefix(td).unwrap_or(p).to_string_lossy().replace('\\', "/");
            let src = match std::fs::read_to_string(p) {
                Ok(s) => s,
                Err(_) => continue,
            };
            if let Err(_e) = tera.add_raw_template(&rel, &src) {
                log::error!("Failed to load template {}: Failed to parse '{}'", rel, rel);
            }
        }
    }
    // custom shortcodes dir
    let shortcodes_dir = input.join("shortcodes");
    if shortcodes_dir.is_dir() {
        for entry in walkdir::WalkDir::new(&shortcodes_dir).sort_by_file_name().into_iter().filter_map(|e| e.ok()) {
            let p = entry.path();
            if p.is_file() {
                let name = p.file_stem().map(|s| s.to_string_lossy().to_string()).unwrap_or_default();
                if let Ok(src) = std::fs::read_to_string(p) {
                    let _ = tera.add_raw_template(&format!("shortcodes/{}", name), &src);
                }
            }
        }
    } else {
        log::debug!(target: "marmite::shortcodes", "No shortcodes directory found at {}", shortcodes_dir.display());
    }

    let force_render = opts.force
        || previous_timestamp.is_none()
        || templates_newest.map(|t| Some(t) > previous_timestamp).unwrap_or(false);

    let data = SiteData {
        site: config,
        posts,
        pages,
        tag,
        archive,
        author,
        stream,
        series,
        latest_timestamp: previous_timestamp,
        config_path: display_path(&opts.config_path),
        force_render,
        generated_urls: GeneratedUrls { file_mappings: file_mapping_urls, ..Default::default() },
        galleries: IndexMap::new(),
    };

    let mut site = Site { data, tera, input, output, content_dir, fragments_dir, start_time: start, build_timestamp, generated_at };
    site.register_functions();
    log::debug!("Global Context site: {:?}", site.data.site);
    Ok(site)
}

fn copy_dir_recursive(src: &Path, dest: &Path) {
    let _ = std::fs::create_dir_all(dest);
    if let Ok(rd) = std::fs::read_dir(src) {
        for e in rd.filter_map(|e| e.ok()) {
            let p = e.path();
            let d = dest.join(e.file_name());
            if p.is_dir() {
                copy_dir_recursive(&p, &d);
            } else {
                let _ = std::fs::copy(&p, &d);
            }
        }
    }
}

impl Site {
    fn register_functions(&mut self) {
        let config = Arc::new(self.data.site.clone());
        let c1 = config.clone();
        self.tera.register_function("url_for", move |args| {
            let path = args.get("path").map(crate::tera::render::render_value).unwrap_or_default();
            let abs = args.get("abs").map(crate::tera::render::is_truthy).unwrap_or(false);
            Ok(Value::String(url_for(&c1, &path, abs)))
        });
        let c2 = config.clone();
        self.tera.register_function("stream_display_name", move |args| {
            let s = args.get("stream").map(crate::tera::render::render_value).unwrap_or_default();
            Ok(Value::String(c2.stream_display_name(&s)))
        });
        let c3 = config.clone();
        self.tera.register_function("series_display_name", move |args| {
            let s = args.get("series").map(crate::tera::render::render_value).unwrap_or_default();
            Ok(Value::String(c3.series_display_name(&s)))
        });
        let c4 = config.clone();
        self.tera.register_function("source_link", move |args| {
            let content = args.get("content").ok_or_else(|| crate::tera::Error::msg("Missing `content` argument"))?;
            let source_path = content
                .get("source_path")
                .and_then(|v| v.as_str())
                .ok_or_else(|| crate::tera::Error::msg("Missing `source_path` in content"))?;
            let filename = Path::new(source_path).file_name().map(|f| f.to_string_lossy().to_string()).unwrap_or_default();
            if let Some(repo) = &c4.source_repository {
                return Ok(Value::String(format!("{}/{}", repo.trim_end_matches('/'), filename)));
            }
            if c4.publish_md {
                return Ok(Value::String(format!("./{}", filename)));
            }
            Ok(Value::String(String::new()))
        });
        let groups: Arc<Mutex<HashMap<String, Value>>> = Arc::new(Mutex::new(HashMap::new()));
        {
            let mut g = groups.lock().unwrap();
            for (name, grp) in [("tag", &self.data.tag), ("archive", &self.data.archive), ("author", &self.data.author), ("stream", &self.data.stream), ("series", &self.data.series)] {
                let entries: Vec<Value> = grp.sorted().into_iter().map(|(k, v)| Value::Array(vec![Value::String(k), serde_json::to_value(v).unwrap_or(Value::Null)])).collect();
                g.insert(name.to_string(), Value::Array(entries));
            }
        }
        self.tera.register_function("group", move |args| {
            let kind = args.get("kind").map(crate::tera::render::render_value).unwrap_or_default();
            let g = groups.lock().unwrap();
            match g.get(&kind) {
                Some(v) => Ok(v.clone()),
                None => Err(crate::tera::Error::msg(format!("Invalid group kind: {}", kind))),
            }
        });
        let c5 = config.clone();
        self.tera.register_filter("default_date_format", move |v, _| {
            let dt = crate::tera::builtins::parse_datetime(v)?;
            Ok(Value::String(crate::tera::builtins::format_date(&dt, &c5.default_date_format)))
        });
        self.tera.register_filter("remove_draft", |v, _| match v {
            Value::Array(a) => Ok(Value::Array(
                a.iter().filter(|c| c.get("stream").and_then(|s| s.as_str()) != Some("draft")).cloned().collect(),
            )),
            _ => Ok(v.clone()),
        });
    }

    fn base_context(&self) -> Context {
        let mut ctx = Context::new();
        ctx.insert("site", &self.data.site);
        ctx.insert("site_data", &self.data);
        ctx.insert("menu", &self.data.site.menu);
        ctx.insert("language", &self.data.site.language);
        let fragments = serde_json::json!({
            "markdown_header": read_fragment(&self.fragments_dir, "_markdown_header.md").unwrap_or_default(),
            "markdown_footer": read_fragment(&self.fragments_dir, "_markdown_footer.md").unwrap_or_default(),
            "references": read_fragment(&self.fragments_dir, "_references.md").unwrap_or_default(),
        });
        ctx.insert_value("markdown_fragments", fragments);
        ctx
    }

    fn render_fragment(&self, name: &str, ctx: &Context) -> Option<String> {
        let raw = read_fragment(&self.fragments_dir, &format!("_{}.md", name))?;
        let rendered = match self.tera.render_str(&raw, ctx) {
            Ok(r) => r,
            Err(e) => {
                log::error!("Failed to render fragment {}: {}", name, e.innermost().msg);
                raw
            }
        };
        let html = crate::markdown::to_html(&rendered);
        let html = content::fix_internal_links(&html);
        log::debug!("{} fragment {}", name, html);
        Some(html)
    }

    fn add_fragments(&self, ctx: &mut Context) {
        let base = ctx.clone();
        for name in ["announce", "hero", "sidebar", "header", "footer", "comments", "htmlhead", "htmltail"] {
            if let Some(html) = self.render_fragment(name, &base) {
                ctx.insert_value(name, Value::String(html));
            }
        }
    }

    fn write_file(&self, name: &str, data: &str) -> bool {
        let path = self.output.join(name);
        if let Some(p) = path.parent() {
            let _ = std::fs::create_dir_all(p);
        }
        match std::fs::write(&path, data) {
            Ok(_) => true,
            Err(e) => {
                log::error!("Failed to write {}: {}", path.display(), e);
                false
            }
        }
    }

    fn render_template(&self, template: &str, ctx: &Context, filename: &str) -> Result<String, ()> {
        match self.tera.render(template, ctx) {
            Ok(mut html) => {
                html = self.process_shortcodes(&html, ctx, filename);
                html = self.resolve_wikilinks(&html, filename);
                Ok(html)
            }
            Err(e) => {
                log::error!("Error rendering template `{}` -> {}: {}", template, filename, e.debug_string());
                log::error!("Failed to render templates: {:?}", e.msg);
                Err(())
            }
        }
    }

    fn resolve_wikilinks(&self, html: &str, filename: &str) -> String {
        log::debug!("Processing wikilinks for {}", filename);
        let re = regex::Regex::new(r#"<a href="([^"]*)" data-wikilink="true">([^<]*)</a>"#).unwrap();
        re.replace_all(html, |caps: &regex::Captures| {
            let href = &caps[1];
            let text = &caps[2];
            let lower = text.to_lowercase();
            let found = self.data.posts.iter().chain(self.data.pages.iter()).find(|c| c.title.to_lowercase() == lower);
            match found {
                Some(c) if !href.is_empty() => format!("<a href=\"{}.html\" data-wikilink=\"true\">{}</a>", c.slug, text),
                _ => caps[0].to_string(),
            }
        })
        .to_string()
    }

    fn process_shortcodes(&self, html: &str, ctx: &Context, filename: &str) -> String {
        if !self.data.site.enable_shortcodes {
            return html.to_string();
        }
        let pattern = self.data.site.shortcode_pattern.clone().unwrap_or_else(|| r"<!-- \.(\w+)(?:\s+([^-][\s\S]*?))?\s*-->".to_string());
        let re = match regex::Regex::new(&pattern) {
            Ok(r) => r,
            Err(_) => return html.to_string(),
        };
        if !re.is_match(html) {
            log::debug!("No shortcode processor available for {}", filename);
            return html.to_string();
        }
        re.replace_all(html, |caps: &regex::Captures| {
            let name = caps.get(1).map(|m| m.as_str()).unwrap_or("");
            let params = caps.get(2).map(|m| m.as_str()).unwrap_or("");
            match self.render_shortcode(name, params, ctx) {
                Ok(s) => s,
                Err(e) => {
                    log::warn!(target: "marmite::shortcodes", "Shortcode '{}' failed to render: {}", name, e);
                    format!(
                        "<div class=\"shortcode-error\" style=\"border: 2px solid red; padding: 10px; margin: 10px 0; background-color: #ffeeee; color: #cc0000;\">\n                        <strong>Shortcode Error:</strong> {}</div>",
                        e.replace('&', "&amp;").replace('<', "&lt;").replace('>', "&gt;").replace('"', "&quot;").replace('\'', "&#39;")
                    )
                }
            }
        })
        .to_string()
    }

    fn render_shortcode(&self, name: &str, params: &str, ctx: &Context) -> Result<String, String> {
        let tpl = format!("shortcodes/{}", name);
        if !self.tera.templates.contains_key(&tpl) {
            return Err(format!("Shortcode '{}' not found", name));
        }
        let mut sctx = ctx.clone();
        // parse params key=value (quoted values allowed)
        let re = regex::Regex::new(r#"(\w+)=("([^"]*)"|'([^']*)'|(\S+))"#).unwrap();
        for c in re.captures_iter(params) {
            let k = c[1].to_string();
            let v = c.get(3).or(c.get(4)).or(c.get(5)).map(|m| m.as_str().to_string()).unwrap_or_default();
            let val = match v.parse::<i64>() {
                Ok(i) => Value::from(i),
                Err(_) => Value::String(v),
            };
            sctx.insert_value(&k, val);
        }
        let rendered = self.tera.render(&tpl, &sctx).map_err(|e| format!("Failed to render shortcode '{}': {}", name, e.msg))?;
        // markdown inside shortcode output is rendered to html
        if name == "socials" {
            return Ok(crate::markdown::to_html(&rendered));
        }
        Ok(rendered)
    }

    pub fn generate(&mut self) -> Result<(), i32> {
        let mut ctx = self.base_context();
        self.add_fragments(&mut ctx);
        let mut ok = true;

        // streams -> list pages + feeds
        let stream_entries: Vec<(String, Vec<Content>)> = self.data.stream.sorted();
        for (name, items) in &stream_entries {
            let (file_base, title) = if name == "index" {
                ("index".to_string(), String::new())
            } else {
                (name.clone(), self.data.site.streams_content_title.replace("$stream", name))
            };
            ok &= self.render_list(&ctx, &file_base, &title, items, None, "streams");
            self.render_feeds(&file_base, items, &self.data.site.name.clone());
        }
        if !stream_entries.iter().any(|(n, _)| n == "index") {
            ok &= self.render_list(&ctx, "index", "", &[], None, "streams");
        }
        // group pages
        for (kind, title, file) in [
            ("tag", self.data.site.tags_title.clone(), "tags.html"),
            ("archive", self.data.site.archives_title.clone(), "archive.html"),
            ("author", self.data.site.authors_title.clone(), "authors.html"),
            ("stream", self.data.site.streams_title.clone(), "streams.html"),
            ("series", self.data.site.series_title.clone(), "series.html"),
        ] {
            let mut gctx = ctx.clone();
            gctx.insert_value("title", Value::String(title));
            gctx.insert_value("kind", Value::String(kind.to_string()));
            gctx.insert_value("current_page", Value::String(file.to_string()));
            if let Ok(html) = self.render_template("group.html", &gctx, file) {
                if self.write_file(file, &html) {
                    log::info!("Generated {}", join_display(&self.output, file));
                }
            } else {
                ok = false;
            }
            match kind {
                "tag" => self.data.generated_urls.tags.push(file.into()),
                "archive" => self.data.generated_urls.archives.push(file.into()),
                "author" => self.data.generated_urls.authors.push(file.into()),
                "stream" => self.data.generated_urls.streams.push(file.into()),
                _ => self.data.generated_urls.series.push(file.into()),
            }
        }
        // tags
        for (name, items) in self.data.tag.sorted() {
            let slug = content::slugify(&name);
            if slug != name && self.data.tag.map.contains_key(&slug) {
                // the slug variant is rendered from its own entry
                continue;
            }
            let title = self.data.site.tags_content_title.replace("$tag", &name);
            ok &= self.render_list(&ctx, &format!("tag-{}", slug), &title, &items, None, "tags");
            self.render_feeds(&format!("tag-{}", slug), &items, &self.data.site.name.clone());
        }
        // archives
        for (year, items) in self.data.archive.sorted() {
            let title = self.data.site.archives_content_title.replace("$year", &year);
            ok &= self.render_list(&ctx, &format!("archive-{}", year), &title, &items, None, "archives");
            self.render_feeds(&format!("archive-{}", year), &items, &self.data.site.name.clone());
        }
        // authors
        for (name, items) in self.data.author.sorted() {
            let slug = content::slugify(&name);
            let author_value = match self.data.site.authors.get(&name) {
                Some(a) => serde_json::to_value(a).unwrap_or(Value::Null),
                None => serde_json::json!({"name": name, "avatar": "static/avatar-placeholder.png", "bio": null, "links": null}),
            };
            let title = author_value.get("name").and_then(|v| v.as_str()).unwrap_or(&name).to_string();
            ok &= self.render_list(&ctx, &format!("author-{}", slug), &title, &items, Some(author_value), "authors");
            self.render_feeds(&format!("author-{}", slug), &items, &self.data.site.name.clone());
        }
        // series
        for (name, items) in self.data.series.sorted() {
            let slug = content::slugify(&name);
            let title = self.data.site.series_content_title.replace("$series", &name);
            ok &= self.render_list(&ctx, &format!("series-{}", slug), &title, &items, None, "series");
            self.render_feeds(&format!("series-{}", slug), &items, &self.data.site.name.clone());
        }
        // pages list
        let pages = self.data.pages.clone();
        ok &= self.render_list(&ctx, "pages", &self.data.site.pages_title.clone(), &pages, None, "pages");

        // 404
        {
            let (title, html) = match read_fragment(&self.fragments_dir, "_404.md") {
                Some(raw) => {
                    let (t, body) = split_title(&raw);
                    (t, crate::markdown::to_html(&body))
                }
                None => ("Page not found".to_string(), "Page not found :/".to_string()),
            };
            let c = Content {
                title: title.clone(),
                description: None,
                slug: "404".into(),
                html,
                tags: vec![],
                date: None,
                extra: None,
                links_to: None,
                back_links: vec![],
                card_image: None,
                banner_image: None,
                authors: vec![],
                stream: None,
                series: None,
                pinned: false,
                toc: None,
                modified_time: None,
                comments: None,
                next: None,
                previous: None,
                source_path: None,
            };
            ok &= self.render_content_page(&ctx, &c, "404.html", true);
        }

        // contents
        let all: Vec<Content> = self.data.posts.iter().chain(self.data.pages.iter()).cloned().collect();
        for c in &all {
            let file = format!("{}.html", c.slug);
            let needs = self.data.force_render || c.modified_time.map(|m| Some(m) > self.data.latest_timestamp).unwrap_or(true);
            if c.date.is_some() {
                self.data.generated_urls.posts.push(file.clone());
            } else {
                self.data.generated_urls.pages.insert(0, file.clone());
            }
            if needs {
                log::debug!("{} context: {:?}", c.slug, format!("title: {},date: {:?},tags: {:?}", c.title, c.date, c.tags));
                if !self.render_content_page(&ctx, c, &file, false) {
                    ok = false;
                    break;
                }
            }
            if self.data.site.publish_md {
                if let Some(sp) = &c.source_path {
                    let src = Path::new(sp);
                    let rel = src.strip_prefix(&self.content_dir).unwrap_or(src);
                    let dest = self.output.join(rel);
                    if let Some(p) = dest.parent() {
                        let _ = std::fs::create_dir_all(p);
                    }
                    let _ = std::fs::copy(src, &dest);
                }
            }
        }
        // fix pages order in generated urls: pages first then "pages.html"
        {
            let mut p: Vec<String> = self.data.pages.iter().map(|c| format!("{}.html", c.slug)).collect();
            let rest: Vec<String> = self.data.generated_urls.pages.iter().filter(|u| !u.ends_with(".html") || !p.contains(u)).cloned().collect();
            p.extend(rest);
            self.data.generated_urls.pages = p;
        }

        if self.data.site.enable_search {
            self.generate_search_index();
        }
        self.data.generated_urls.misc.push("index.html".into());
        if self.data.site.build_sitemap {
            self.generate_sitemap();
        }
        if self.data.site.publish_urls_json {
            self.generate_urls_json();
        }
        self.generate_build_info();
        log::info!("Site generated at: {}/", self.output.display());
        if ok {
            Ok(())
        } else {
            Ok(())
        }
    }

    fn render_content_page(&self, base: &Context, c: &Content, file: &str, _is_404: bool) -> bool {
        let mut cctx = base.clone();
        cctx.insert("content", c);
        cctx.insert_value("title", Value::String(c.title.clone()));
        cctx.insert_value("current_page", Value::String(file.to_string()));
        match self.render_template("content.html", &cctx, file) {
            Ok(html) => {
                if self.write_file(file, &html) {
                    log::info!("Generated {}", join_display(&self.output, file));
                }
                true
            }
            Err(_) => false,
        }
    }

    fn render_list(&mut self, base: &Context, file_base: &str, title: &str, items: &[Content], author: Option<Value>, category: &str) -> bool {
        let per_page = self.data.site.pagination.max(1);
        let total = items.len();
        let total_pages = if total == 0 { 1 } else { (total + per_page - 1) / per_page };
        let mut ok = true;
        // main page (page 1) and numbered pages
        let mut targets: Vec<(String, usize, String)> = vec![(format!("{}.html", file_base), 1, title.to_string())];
        if total > 0 {
            for n in 1..=total_pages {
                let t = if title.is_empty() { format!("Page - {}", n) } else { format!("{} - {}", title, n) };
                targets.push((format!("{}-{}.html", file_base, n), n, t));
            }
        }
        for (file, page_num, page_title) in &targets {
            let start = (page_num - 1) * per_page;
            let end = std::cmp::min(start + per_page, total);
            let slice: Vec<Content> = if start < total { items[start..end].to_vec() } else { vec![] };
            let mut ctx = base.clone();
            ctx.insert("content_list", &slice);
            ctx.insert_value("title", Value::String(page_title.clone()));
            ctx.insert_value("current_page", Value::String(file.clone()));
            ctx.insert_value("total_pages", Value::from(total_pages));
            ctx.insert_value("per_page", Value::from(per_page));
            ctx.insert_value("total_content", Value::from(total));
            ctx.insert_value("current_page_number", Value::from(*page_num));
            if *page_num > 1 {
                ctx.insert_value("previous_page", Value::String(format!("{}-{}.html", file_base, page_num - 1)));
            }
            if *page_num < total_pages {
                ctx.insert_value("next_page", Value::String(format!("{}-{}.html", file_base, page_num + 1)));
            }
            if let Some(a) = &author {
                ctx.insert_value("author", a.clone());
            }
            log::debug!(
                "List Context for {}: {:?} - Pagination({:?})",
                file,
                slice.iter().map(|c| format!("title:{}, slug:{}", c.title, c.slug)).collect::<Vec<_>>(),
                vec![
                    format!("total_pages:{}", total_pages),
                    format!("per_page:{}", per_page),
                    format!("total_content:{}", total),
                    format!("current_page:{:?}", file),
                    format!("current_page_number:{}", page_num),
                ]
            );
            match self.render_template("list.html", &ctx, file) {
                Ok(html) => {
                    if self.write_file(file, &html) {
                        log::info!("Generated {}", join_display(&self.output, file));
                    }
                }
                Err(_) => ok = false,
            }
            let is_main = file == &format!("{}.html", file_base);
            if is_main {
                match category {
                    "streams" => {
                        if file_base != "index" {
                            self.data.generated_urls.streams.insert(0, file.clone());
                        }
                    }
                    "tags" => self.data.generated_urls.tags.insert(self.data.generated_urls.tags.len().saturating_sub(1), file.clone()),
                    "archives" => self.data.generated_urls.archives.insert(self.data.generated_urls.archives.len().saturating_sub(1), file.clone()),
                    "authors" => self.data.generated_urls.authors.insert(self.data.generated_urls.authors.len().saturating_sub(1), file.clone()),
                    "series" => self.data.generated_urls.series.insert(self.data.generated_urls.series.len().saturating_sub(1), file.clone()),
                    "pages" => self.data.generated_urls.pages.push(file.clone()),
                    _ => {}
                }
            } else {
                self.data.generated_urls.pagination.push(file.clone());
            }
        }
        ok
    }

    fn render_feeds(&mut self, file_base: &str, items: &[Content], _title: &str) {
        if items.is_empty() {
            return;
        }
        let rss_name = format!("{}.rss", file_base);
        let rss = crate::feed::rss(&self.data.site, file_base, items, self.generated_at);
        if self.write_file(&rss_name, &rss) {
            log::info!(target: "marmite::feed", "Generated {}", join_display(&self.output, &rss_name));
        }
        self.data.generated_urls.feeds.push(rss_name);
        if self.data.site.json_feed {
            let json_name = format!("{}.json", file_base);
            let json = crate::feed::json_feed(&self.data.site, file_base, items);
            if self.write_file(&json_name, &json) {
                log::info!(target: "marmite::feed", "Generated {}", join_display(&self.output, &json_name));
            }
            self.data.generated_urls.feeds.push(json_name);
        }
    }

    fn generate_search_index(&self) {
        #[derive(Serialize)]
        struct Entry {
            title: String,
            description: Option<String>,
            tags: Vec<String>,
            slug: String,
            html: String,
        }
        let entries: Vec<Entry> = self
            .data
            .posts
            .iter()
            .chain(self.data.pages.iter())
            .map(|c| Entry {
                title: c.title.clone(),
                description: c.description.clone(),
                tags: c.tags.clone(),
                slug: c.slug.clone(),
                html: crate::tera::builtins::striptags(&c.html).split_whitespace().collect::<Vec<_>>().join(" "),
            })
            .collect();
        let json = serde_json::to_string(&entries).unwrap_or_default();
        if self.write_file("static/search_index.json", &json) {
            log::info!("Generated search_index.json");
        }
    }

    fn all_urls(&self) -> Vec<String> {
        let g = &self.data.generated_urls;
        let mut out = Vec::new();
        for list in [&g.posts, &g.pages, &g.tags, &g.authors, &g.series, &g.streams, &g.archives, &g.feeds, &g.pagination, &g.file_mappings, &g.misc] {
            for u in list {
                out.push(url_for(&self.data.site, u, true));
            }
        }
        out
    }

    fn generate_sitemap(&self) {
        let urls = self.all_urls();
        let mut ctx = Context::new();
        ctx.insert("sitemap_urls", &urls);
        match self.tera.render("sitemap.xml", &ctx) {
            Ok(xml) => {
                if self.write_file("sitemap.xml", &xml) {
                    log::info!("Generated sitemap.xml with {} URLs", urls.len());
                }
            }
            Err(e) => log::error!("Failed to render sitemap: {}", e.msg),
        }
    }

    fn generate_urls_json(&self) {
        let g = &self.data.generated_urls;
        let conv = |v: &Vec<String>| -> Vec<String> { v.iter().map(|u| url_for(&self.data.site, u, true)).collect() };
        let mut obj = serde_json::Map::new();
        let cats = [
            ("posts", &g.posts),
            ("pages", &g.pages),
            ("tags", &g.tags),
            ("authors", &g.authors),
            ("series", &g.series),
            ("streams", &g.streams),
            ("archives", &g.archives),
            ("feeds", &g.feeds),
            ("pagination", &g.pagination),
            ("file_mappings", &g.file_mappings),
            ("misc", &g.misc),
        ];
        let mut summary = serde_json::Map::new();
        let mut total = 0;
        for (k, v) in cats.iter() {
            obj.insert(k.to_string(), serde_json::to_value(conv(v)).unwrap());
            summary.insert(k.to_string(), Value::from(v.len()));
            total += v.len();
        }
        summary.insert("total".into(), Value::from(total));
        summary.insert(
            "meta".into(),
            serde_json::json!({"url": self.data.site.url, "absolute_urls": !self.data.site.url.is_empty()}),
        );
        obj.insert("summary".into(), Value::Object(summary));
        let json = serde_json::to_string_pretty(&Value::Object(obj)).unwrap_or_default();
        if self.write_file("urls.json", &json) {
            log::info!("Generated urls.json");
        }
    }

    pub fn show_urls(&self) -> String {
        let g = &self.data.generated_urls;
        let conv = |v: &Vec<String>| -> Vec<String> { v.iter().map(|u| url_for(&self.data.site, u, true)).collect() };
        let mut obj = serde_json::Map::new();
        let cats = [
            ("posts", &g.posts),
            ("pages", &g.pages),
            ("tags", &g.tags),
            ("authors", &g.authors),
            ("series", &g.series),
            ("streams", &g.streams),
            ("archives", &g.archives),
            ("feeds", &g.feeds),
            ("pagination", &g.pagination),
            ("file_mappings", &g.file_mappings),
            ("misc", &g.misc),
        ];
        let mut summary = serde_json::Map::new();
        let mut total = 0;
        for (k, v) in cats.iter() {
            obj.insert(k.to_string(), serde_json::to_value(conv(v)).unwrap());
            summary.insert(k.to_string(), Value::from(v.len()));
            total += v.len();
        }
        summary.insert("total".into(), Value::from(total));
        summary.insert("meta".into(), serde_json::json!({"url": self.data.site.url, "absolute_urls": !self.data.site.url.is_empty()}));
        obj.insert("summary".into(), Value::Object(summary));
        serde_json::to_string_pretty(&Value::Object(obj)).unwrap_or_default()
    }

    fn generate_build_info(&self) {
        let elapsed = self.start_time.elapsed().as_secs_f64();
        let info = serde_json::json!({
            "marmite_version": "0.2.7",
            "posts": self.data.posts.len(),
            "pages": self.data.pages.len(),
            "generated_at": self.generated_at.to_string(),
            "timestamp": self.build_timestamp,
            "elapsed_time": elapsed,
            "config": self.data.site,
        });
        let json = serde_json::to_string_pretty(&info).unwrap_or_default();
        if self.write_file("marmite.json", &json) {
            log::info!("Generated build info at marmite.json");
        }
    }
}

/// Splits the first non-empty line as title (for `_404.md`).
fn split_title(raw: &str) -> (String, String) {
    let (fm, body) = match content::parse_front_matter(raw) {
        Ok(x) => x,
        Err(_) => return ("Page not found".into(), raw.to_string()),
    };
    if let Some(t) = fm.get_str("title") {
        return (t, body);
    }
    let mut lines: Vec<&str> = body.split('\n').collect();
    for i in 0..lines.len() {
        if !lines[i].trim().is_empty() {
            let title = lines[i].trim().trim_start_matches('#').trim().to_string();
            lines.remove(i);
            return (title, lines.join("\n"));
        }
    }
    (String::new(), body)
}
