    }
    out
}

fn base_url(site: &Marmite) -> String {
    let url = site.url.trim_end_matches('/');
    if url.contains("://") {
        url.to_string()
    } else if site.https == Some(true) {
        format!("https://{}", url)
    } else {
        format!("http://{}", url)
    }
}

fn rfc2822_gmt(dt: &chrono::NaiveDateTime) -> String {
    dt.format("%a, %d %b %Y %H:%M:%S GMT").to_string()
}

pub fn rss(site: &Marmite, name: &str, items: &[Content], now: DateTime<Utc>) -> String {
    let base = base_url(site);
    let mut out = String::new();
    out.push_str("<?xml version=\"1.0\" encoding=\"utf-8\"?>");
    out.push_str("<rss version=\"2.0\" xmlns:content=\"http://purl.org/rss/1.0/modules/content/\"><channel>");
    out.push_str(&format!("<title>{}</title>", xml_escape(&site.name)));
    out.push_str(&format!("<link>{}</link>", xml_escape(&base)));
    out.push_str(&format!("<description>{}</description>", xml_escape(&site.tagline)));
    if let Some(d) = items.first().and_then(|c| c.date) {
        out.push_str(&format!("<pubDate>{}</pubDate>", rfc2822_gmt(&d)));
    }
    out.push_str(&format!("<lastBuildDate>{}</lastBuildDate>", now.format("%a, %d %b %Y %H:%M:%S GMT")));
    out.push_str("<generator>marmite</generator>");
    for c in items.iter().take(15) {
        let link = format!("{}/{}.html", base, c.slug);
        out.push_str("<item>");
        out.push_str(&format!("<title>{}</title>", xml_escape(&c.title)));
        out.push_str(&format!("<link>{}</link>", xml_escape(&link)));
        if let Some(d) = &c.description {
            out.push_str(&format!("<description><![CDATA[{}]]></description>", d));
        }
        for a in &c.authors {
            out.push_str(&format!("<author>{}</author>", xml_escape(a)));
        }
        for t in &c.tags {
            out.push_str(&format!("<category>{}</category>", xml_escape(t)));
        }
        out.push_str(&format!("<guid>{}</guid>", xml_escape(&link)));
        if let Some(d) = c.date {
            out.push_str(&format!("<pubDate>{}</pubDate>", rfc2822_gmt(&d)));
        }
        out.push_str(&format!("<source url=\"{}\">{}</source>", xml_escape(&base), xml_escape(name)));
        out.push_str(&format!("<content:encoded><![CDATA[{}]]></content:encoded>", c.html));
        out.push_str("</item>");
    }
    out.push_str("</channel></rss>");
    out
}

pub fn json_feed(site: &Marmite, name: &str, items: &[Content]) -> String {
    let base = base_url(site);
    let items_json: Vec<serde_json::Value> = items
        .iter()
        .take(15)
        .map(|c| {
            let link = format!("{}/{}.html", base, c.slug);
            let authors: Vec<serde_json::Value> = c
                .authors
                .iter()
                .map(|a| match site.authors.get(a) {
                    Some(author) => serde_json::json!({
                        "name": author.name,
                        "url": format!("{}/author-{}.html", base, crate::content::slugify(a)),
                        "avatar": author.avatar.clone().map(|av| crate::site::url_for(site, &av, true)).unwrap_or_default(),
                    }),
                    None => serde_json::json!({"name": a, "url": "", "avatar": ""}),
                })
                .collect();
            serde_json::json!({
                "id": link,
                "url": link,
                "title": c.title,
                "content_html": c.html,
                "summary": c.description.clone().unwrap_or_default(),
                "date_published": c.date.map(|d| d.format("%Y-%m-%dT%H:%M:%S-00:00").to_string()).unwrap_or_default(),
                "image": c.card_image.clone().map(|i| crate::site::url_for(site, &i, true)).unwrap_or_default(),
                "authors": authors,
                "tags": c.tags,
                "language": site.language,
            })
        })
        .collect();
    let feed = serde_json::json!({
        "version": "https://jsonfeed.org/version/1",
        "title": site.name,
        "home_page_url": base,
        "feed_url": format!("{}/{}.json", base, name),
        "description": site.tagline,
        "items": items_json,
    });
    serde_json::to_string_pretty(&feed).unwrap_or_default()
}
