//! --init-templates, --start-theme and --set-theme implementations.

use std::path::Path;

pub fn init_templates(input: &Path) {
    let dir = input.join("templates");
    if let Err(e) = std::fs::create_dir_all(&dir) {
        log::error!("Failed to create templates directory: {}", e);
        return;
    }
    for t in crate::embedded::TEMPLATES {
        let dest = dir.join(t.name);
        match std::fs::write(&dest, t.data) {
            Ok(_) => log::info!("Generated {}", dest.display()),
            Err(e) => log::error!("Failed to write {}: {}", dest.display(), e),
        }
    }
}

pub fn start_theme(input: &Path, name: &str) {
    let dir = input.join(name);
    if dir.exists() {
        log::error!("Theme directory '{}' already exists", dir.display());
        return;
    }
    for t in crate::embedded::THEME_TEMPLATE {
        let dest = dir.join(t.name);
        if let Some(p) = dest.parent() {
            let _ = std::fs::create_dir_all(p);
        }
        match std::fs::write(&dest, t.data) {
            Ok(_) => log::info!("Generated {}", dest.display()),
            Err(e) => log::error!("Failed to write {}: {}", dest.display(), e),
        }
    }
    log::info!("Theme '{}' created successfully at {}", name, dir.display());
    log::info!("To use this theme, add 'theme: {}' to your marmite.yaml config file", name);
}

fn copy_dir(src: &Path, dest: &Path) -> std::io::Result<()> {
    std::fs::create_dir_all(dest)?;
    for e in std::fs::read_dir(src)? {
        let e = e?;
        let p = e.path();
        let d = dest.join(e.file_name());
        if p.is_dir() {
            copy_dir(&p, &d)?;
        } else {
            std::fs::copy(&p, &d)?;
        }
    }
    Ok(())
}

pub fn set_theme(input: &Path, config_path: &Path, source: &str) {
    let theme_name;
    let src = Path::new(source);
    if source.starts_with("http://") || source.starts_with("https://") {
        log::error!("Failed to download theme from '{}': network access is not available", source);
        return;
    } else if src.is_dir() {
        theme_name = src.file_name().map(|f| f.to_string_lossy().to_string()).unwrap_or_else(|| "theme".to_string());
        let dest = input.join(&theme_name);
        if dest.exists() && dest.canonicalize().ok() == src.canonicalize().ok() {
            // same dir, nothing to copy
        } else if let Err(e) = copy_dir(src, &dest) {
            log::error!("Failed to copy theme: {}", e);
            return;
        }
        log::info!("Theme '{}' installed at {}", theme_name, dest.display());
    } else {
        log::error!("Theme source '{}' not found", source);
        return;
    }
    // update config
    let mut content = std::fs::read_to_string(config_path).unwrap_or_default();
    let re = regex::Regex::new(r"(?m)^theme:.*$").unwrap();
    if re.is_match(&content) {
        content = re.replace(&content, format!("theme: {}", theme_name)).to_string();
    } else {
        if !content.is_empty() && !content.ends_with('\n') {
            content.push('\n');
        }
        content.push_str(&format!("theme: {}\n", theme_name));
    }
    match std::fs::write(config_path, content) {
        Ok(_) => log::info!("Config updated with theme '{}'", theme_name),
        Err(e) => log::error!("Failed to update config: {}", e),
    }
}
