use std::io::{BufRead, BufReader, Read, Write};
use std::net::{TcpListener, TcpStream};
use std::path::{Path, PathBuf};

fn http_date() -> String {
    chrono::Utc::now().format("%a, %d %b %Y %H:%M:%S GMT").to_string()
}

fn handle(mut stream: TcpStream, root: &Path) {
    let mut reader = BufReader::new(match stream.try_clone() {
        Ok(s) => s,
        Err(_) => return,
    });
    let mut request_line = String::new();
    if reader.read_line(&mut request_line).is_err() {
        return;
    }
    // consume headers
    loop {
        let mut line = String::new();
        match reader.read_line(&mut line) {
            Ok(0) => break,
            Ok(_) => {
                if line == "\r\n" || line == "\n" {
                    break;
                }
            }
            Err(_) => break,
        }
    }
    let parts: Vec<&str> = request_line.split_whitespace().collect();
    if parts.len() < 2 {
        return;
    }
    let method = parts[0];
    let raw_path = parts[1];
    let version = parts.get(2).copied().unwrap_or("HTTP/1.1");
    let path = raw_path.split('?').next().unwrap_or("/");
    let mut rel = path.trim_start_matches('/').to_string();
    if rel.is_empty() || rel.ends_with('/') {
        rel.push_str("index.html");
    }
    let rel = percent_decode(&rel);
    let mut file: PathBuf = root.join(&rel);
    let mut status = 200;
    if !file.is_file() {
        status = 404;
        file = root.join("404.html");
    }
    let body = std::fs::read(&file).unwrap_or_default();
    let log_line = format!("\"{} {} {}\" {} -", method, rel, version, status);
    if status == 200 {
        log::info!("{}", log_line);
    } else {
        log::error!("{}", log_line);
    }
    let header = format!(
        "HTTP/1.1 200 OK\r\nServer: tiny-http (Rust)\r\nDate: {}\r\nContent-Length: {}\r\n\r\n",
        http_date(),
        body.len()
    );
    let _ = stream.write_all(header.as_bytes());
    let _ = stream.write_all(&body);
    let _ = stream.flush();
}

fn percent_decode(s: &str) -> String {
    let b = s.as_bytes();
    let mut out = Vec::new();
    let mut i = 0;
    while i < b.len() {
        if b[i] == b'%' && i + 2 < b.len() + 0 && i + 2 <= b.len() - 1 {
            if let Ok(v) = u8::from_str_radix(&s[i + 1..i + 3], 16) {
                out.push(v);
                i += 3;
                continue;
            }
        }
        out.push(b[i]);
        i += 1;
    }
    String::from_utf8_lossy(&out).to_string()
}

pub fn serve(root: PathBuf, bind: &str) {
    let listener = match TcpListener::bind(bind) {
        Ok(l) => l,
        Err(e) => {
            log::error!("Failed to bind server to {}: {}", bind, e);
            std::process::exit(1);
        }
    };
    log::info!("Server started at http://{}/ - Type ^C to stop.", bind);
    for stream in listener.incoming() {
        match stream {
            Ok(s) => {
                let root = root.clone();
                std::thread::spawn(move || handle(s, &root));
            }
            Err(e) => log::error!("Connection failed: {}", e),
        }
    }
    let _ = Read::read(&mut std::io::empty(), &mut []);
}
