    let verbosity = matches.get_count("verbose");
    setup_logging(verbosity);

    let input = PathBuf::from(matches.get_one::<String>("input_folder").unwrap());
    let output = match matches.get_one::<String>("output_folder") {
        Some(o) => PathBuf::from(o),
        None => input.join("site"),
    };
    let config_file = matches.get_one::<String>("config").cloned().unwrap_or_else(|| "marmite.yaml".to_string());
    let config_path = input.join(&config_file);

    let overrides = config::CliOverrides {
        name: matches.get_one::<String>("name").cloned(),
        tagline: matches.get_one::<String>("tagline").cloned(),
        url: matches.get_one::<String>("url").cloned(),
        https: get_bool(&matches, "https"),
        footer: matches.get_one::<String>("footer").cloned(),
        language: matches.get_one::<String>("language").cloned(),
        pagination: matches.get_one::<usize>("pagination").copied(),
        enable_search: get_bool(&matches, "enable_search"),
        enable_related_content: get_bool(&matches, "enable_related_content"),
        content_path: matches.get_one::<String>("content_path").cloned(),
        templates_path: matches.get_one::<String>("templates_path").cloned(),
        static_path: matches.get_one::<String>("static_path").cloned(),
        media_path: matches.get_one::<String>("media_path").cloned(),
        default_date_format: matches.get_one::<String>("default_date_format").cloned(),
        colorscheme: matches.get_one::<String>("colorscheme").cloned(),
        toc: get_bool(&matches, "toc"),
        json_feed: get_bool(&matches, "json_feed"),
        show_next_prev_links: get_bool(&matches, "show_next_prev_links"),
        publish_md: get_bool(&matches, "publish_md"),
        source_repository: matches.get_one::<String>("source_repository").cloned(),
        image_provider: matches.get_one::<String>("image_provider").cloned(),
        theme: matches.get_one::<String>("theme").cloned(),
        build_sitemap: get_bool(&matches, "build_sitemap"),
        publish_urls_json: get_bool(&matches, "publish_urls_json"),
        enable_shortcodes: get_bool(&matches, "enable_shortcodes"),
        shortcode_pattern: matches.get_one::<String>("shortcode_pattern").cloned(),
        skip_image_resize: get_bool(&matches, "skip_image_resize"),
    };

    if matches.get_flag("init_site") {
        init_site(&input, &config_path, &overrides);
        return;
    }
    if matches.get_flag("generate_config") {
        config::generate_config(&config_path, &overrides);
        return;
    }
    if matches.get_flag("init_templates") {
        templates::init_templates(&input);
        return;
    }
    if let Some(name) = matches.get_one::<String>("start_theme") {
        templates::start_theme(&input, name);
        return;
    }
    if let Some(src) = matches.get_one::<String>("set_theme") {
        templates::set_theme(&input, &config_path, src);
        return;
    }
    if let Some(title) = matches.get_one::<String>("new") {
        new_content(&input, &config_path, &overrides, title, matches.get_flag("page"), matches.get_one::<String>("tags").cloned(), matches.get_flag("edit"));
        return;
    }

    if !input.exists() {
        log::error!("Input folder does not exist: {:?}", input);
        std::process::exit(1);
    }

    if matches.get_flag("shortcodes") {
        let cfg = site::load_config(&config_path, &overrides);
        print_shortcodes(&cfg);
        return;
    }

    let force = matches.get_flag("force");
    let run = |force: bool| -> Result<site::Site, i32> {
        let opts = site::BuildOptions {
            input: input.clone(),
            output: output.clone(),
            config_path: config_path.clone(),
            overrides: overrides.clone(),
            force,
            cli_theme: None,
        };
        let mut s = site::build(opts)?;
        s.generate()?;
        Ok(s)
    };

    if matches.get_flag("show_urls") {
        match run(force) {
            Ok(s) => println!("{}", s.show_urls()),
            Err(code) => std::process::exit(code),
        }
        return;
    }

    if let Err(code) = run(force) {
        std::process::exit(code);
    }

    let serve = matches.get_flag("serve");
    let watch = matches.get_flag("watch");
    let bind = matches.get_one::<String>("bind").cloned().unwrap_or_else(|| "0.0.0.0:8000".to_string());

    if watch {
        let input_w = input.clone();
        let output_w = output.clone();
        let config_w = config_path.clone();
        let overrides_w = overrides.clone();
        std::thread::spawn(move || {
            log::info!("Watching for changes in: {}", input_w.display());
            let mut last = snapshot(&input_w, &output_w);
            loop {
                std::thread::sleep(std::time::Duration::from_millis(1000));
                let cur = snapshot(&input_w, &output_w);
                if cur != last {
                    last = cur;
                    log::info!("Change detected, rebuilding site...");
                    let opts = site::BuildOptions {
                        input: input_w.clone(),
                        output: output_w.clone(),
                        config_path: config_w.clone(),
                        overrides: overrides_w.clone(),
                        force: false,
                        cli_theme: None,
                    };
                    if let Ok(mut s) = site::build(opts) {
                        let _ = s.generate();
                    }
                }
            }
        });
        if !serve {
            loop {
                std::thread::sleep(std::time::Duration::from_secs(3600));
            }
        }
    }
    if serve {
        log::info!("Starting built-in HTTP server...");
        server::serve(output, &bind);
    }
}

fn snapshot(input: &std::path::Path, output: &std::path::Path) -> Vec<(PathBuf, u64, i64)> {
    let mut out = Vec::new();
    for e in walkdir::WalkDir::new(input).into_iter().filter_entry(|e| !e.path().starts_with(output)).filter_map(|e| e.ok()) {
        if e.path().is_file() {
            let m = std::fs::metadata(e.path()).ok();
            let size = m.as_ref().map(|m| m.len()).unwrap_or(0);
            let mtime = m
                .and_then(|m| m.modified().ok())
                .and_then(|t| t.duration_since(std::time::UNIX_EPOCH).ok())
                .map(|d| d.as_secs() as i64)
                .unwrap_or(0);
            out.push((e.path().to_path_buf(), size, mtime));
        }
    }
    out.sort();
    out
}

fn init_site(input: &std::path::Path, config_path: &std::path::Path, overrides: &config::CliOverrides) {
    let content = input.join("content");
    if let Err(e) = std::fs::create_dir_all(content.join("media")) {
        log::error!(target: "marmite::site", "Failed to create content directory: {}", e);
        return;
    }
    let today = chrono::Local::now().format("%Y-%m-%d").to_string();
    let welcome = content.join(format!("{}-welcome.md", today));
    let _ = std::fs::write(&welcome, embedded::SAMPLE_WELCOME);
    for f in embedded::SAMPLE_CONTENT {
        let _ = std::fs::write(content.join(f.name), f.data);
    }
    let _ = std::fs::write(input.join("custom.css"), embedded::SAMPLE_CUSTOM_CSS);
    let _ = std::fs::write(input.join("custom.js"), embedded::SAMPLE_CUSTOM_JS);
    config::generate_config(config_path, overrides);
    log::info!(target: "marmite::site", "Site initialized in {}", input.display());
}

fn new_content(input: &std::path::Path, config_path: &std::path::Path, overrides: &config::CliOverrides, title: &str, page: bool, tags: Option<String>, edit: bool) {
    let cfg = site::load_config_quiet(config_path, overrides);
    let content_dir = site::content_dir(input, &cfg);
    let slug = content::slugify(title);
    let filename = if page {
        format!("{}.md", slug)
    } else {
        format!("{}-{}.md", chrono::Local::now().format("%Y-%m-%d-%H-%M-%S"), slug)
    };
    let path = content_dir.join(&filename);
    let body = match &tags {
        Some(t) => format!("---\ntags: {}\n---\n# {}\n\n", t, title),
        None => format!("# {}\n", title),
    };
    if let Err(e) = std::fs::write(&path, body) {
        log::error!(target: "marmite::content", "Failed to create file: {}", e);
        return;
    }
    println!("{}", path.display());
    if edit {
        let editor = std::env::var("EDITOR").unwrap_or_else(|_| "vim".to_string());
        if let Err(e) = std::process::Command::new(&editor).arg(&path).status() {
            log::error!(target: "marmite::content", "Failed to open editor: {:?}", e);
        }
    }
}

fn print_shortcodes(cfg: &config::Marmite) {
    let pattern = cfg.shortcode_pattern.clone().unwrap_or_else(|| r"<!-- \.(\w+)(?:\s+([^-][\s\S]*?))?\s*-->".to_string());
    println!("Shortcodes:");
    println!("Enabled: {}", cfg.enable_shortcodes);
    println!("Pattern: {}", pattern);
    println!();
    println!("Reusable blocks of content that can be used in your markdown files.");
    println!("They are defined in the shortcodes/ directory and are rendered using the Tera template engine.");
    println!("Check the documentation for details on how to use and create shortcodes.");
    println!("================");
    println!("Examples based on your configuration:");
    println!("  <!-- .toc -->");
    println!("  <!-- .posts -->");
    println!("  <!-- .posts param=value -->");
    println!("  <!-- .youtube -->");
    println!("  <!-- .youtube param=value -->");
    println!();
    println!("Note: Replace 'param' and 'value' with actual parameter names and values.");
    println!("--------------------------------");
    println!("Available shortcodes:");
    let descs = [
        ("authors", "Display a list of all authors with post counts. Params: ord=desc, items=0"),
        ("card", "Display a card for content based on slug with optional parameter overrides"),
        ("gallery", "Display a gallery of images"),
        ("pages", "Display a list of all pages. Params: ord=asc, items=0"),
        ("posts", "Display a list of recent posts. Params: ord=desc, items=10"),
        ("series", "Display a list of all content series with post counts. Params: ord=desc, items=0"),
        ("socials", "Display social network links"),
        ("spotify", "Embed Spotify content with custom dimensions"),
        ("streams", "Display a list of all content streams with post counts. Params: ord=desc, items=0"),
        ("tags", "Display a list of all tags with post counts. Params: ord=desc, items=0"),
        ("toc", "Display table of contents for the current content"),
        ("youtube", "Embed a YouTube video"),
    ];
    for (n, d) in descs {
        println!("  - {}: {}", n, d);
    }
}
