# email autolink postprocess
s += '''
fn is_in_link(arena: &Arena, mut node: usize) -> bool {
    while let Some(p) = arena.get(node).parent {
        if matches!(arena.get(p).value, NodeValue::Link { .. } | NodeValue::WikiLink { .. } | NodeValue::Image { .. }) {
            return true;
        }
        node = p;
    }
    false
}

pub fn process_email_autolinks(arena: &mut Arena, root: usize) {
    let mut stack = vec![root];
    while let Some(n) = stack.pop() {
        let children = arena.children(n);
        for c in children.into_iter().rev() {
            stack.push(c);
        }
        if let NodeValue::Text(_) = arena.get(n).value {
            if is_in_link(arena, n) {
                continue;
            }
            email_autolink_text_node(arena, n);
        }
    }
}

fn email_autolink_text_node(arena: &mut Arena, node: usize) {
    let text = match &arena.get(node).value {
        NodeValue::Text(t) => t.clone(),
        _ => return,
    };
    let contents = text.as_bytes();
    let len = contents.len();
    let mut i = 0;
    while i < len {
        if contents[i] == b'@' {
            if let Some((url, rewind, link_end)) = super::autolink::email_match(contents, i) {
                let start = i - rewind;
                let end = i + link_end;
                let link_text = String::from_utf8_lossy(&contents[start..end]).to_string();
