            if !defs.contains_key(&key) {
                defs.insert(key, n);
                def_order.push(n);
            }
        }
    }
    // find references in document order (including inside definitions)
    let mut ix_counter = 0usize;
    let mut used: Vec<usize> = Vec::new();
    let mut ix_map: HashMap<usize, usize> = HashMap::new();
    let mut ref_counts: HashMap<usize, usize> = HashMap::new();
    let nodes = arena.descendants(root);
    for n in nodes {
        let (name, is_ref) = match &arena.get(n).value {
            NodeValue::FootnoteReference { name, .. } => (name.clone(), true),
            _ => (String::new(), false),
        };
        if !is_ref {
            continue;
        }
        let key = strings::normalize_label(&name);
        match defs.get(&key) {
            Some(&d) => {
                let ix = *ix_map.entry(d).or_insert_with(|| {
                    ix_counter += 1;
                    used.push(d);
                    ix_counter
                });
                let cnt = ref_counts.entry(d).or_insert(0);
                *cnt += 1;
