    #[serde(default)]
    author: Option<String>,
    #[serde(default)]
    description: Option<String>,
    #[serde(default)]
    tags: Option<Vec<String>>,
    #[serde(default)]
    features: Option<Vec<String>>,
}

pub fn set_theme(input: &Path, config_path: &Path, source: &str, overrides: &crate::config::CliOverrides) {
    const T: &str = "marmite::theme_manager";
    log::info!(target: T, "Setting theme from: {}", source);
    if source.starts_with("http://") || source.starts_with("https://") {
        let url = if source.ends_with(".zip") { source.to_string() } else { format!("{}/archive/refs/heads/main.zip", source.trim_end_matches('/')) };
        log::info!(target: T, "Downloading theme from: {}", url);
        log::error!(target: T, "Failed to download theme: io: failed to lookup address information: Temporary failure in name resolution");
        return;
    }
    let dir = input.join(source);
    if !dir.is_dir() {
        log::error!(target: T, "Theme folder does not exist: {}", dir.display());
        return;
    }
    let meta_path = dir.join("theme.json");
    let meta: ThemeMeta = match std::fs::read_to_string(&meta_path) {
        Ok(s) => match serde_json::from_str(&s) {
            Ok(m) => m,
            Err(e) => {
                log::error!(target: T, "Failed to read theme metadata: {}", e);
                return;
            }
        },
        Err(e) => {
            log::error!(target: T, "Failed to read theme metadata: {}", e);
            return;
        }
    };
    // update or create the config
    if config_path.exists() {
        log::info!(target: T, "Updating marmite.yaml with theme: {}", source);
        let mut content = std::fs::read_to_string(config_path).unwrap_or_default();
        let re = regex::Regex::new(r"(?m)^theme:.*$").unwrap();
        if re.is_match(&content) {
            content = re.replace(&content, format!("theme: {}", source)).to_string();
        } else {
            if !content.is_empty() && !content.ends_with('\n') {
                content.push('\n');
            }
            content.push_str(&format!("theme: {}\n", source));
        }
        if let Err(e) = std::fs::write(config_path, content) {
            log::error!(target: T, "Failed to update config: {}", e);
            return;
        }
    } else {
        log::info!(target: T, "Creating new marmite.yaml with theme: {}", source);
        let mut ov = overrides.clone();
        ov.theme = Some(source.to_string());
        let yaml = crate::config::generate_config_yaml(&ov);
        if let Err(e) = std::fs::write(config_path, yaml) {
            log::error!(target: T, "Failed to create config: {}", e);
            return;
        }
    }
    println!();
    println!("✅ Theme '{}' has been successfully set!", source);
    println!();
    println!("📦 Theme Information:");
    println!("   Name: {}", meta.name);
    println!("   Version: {}", meta.version);
    if let Some(a) = &meta.author {
        println!("   Author: {}", a);
    }
    if let Some(d) = &meta.description {
        println!("   Description: {}", d);
    }
    if let Some(f) = &meta.features {
        if !f.is_empty() {
            println!();
            println!("✨ Features:");
            for feat in f {
                println!("   - {}", feat);
            }
        }
    }
    if let Some(tags) = &meta.tags {
        if !tags.is_empty() {
            println!();
            println!("🏷️  Tags: {}", tags.join(", "));
        }
    }
    println!();
    println!("🚀 To use this theme, run: marmite {} --theme {}", input.display(), source);
}
